/* 由 tools/build_lib.js 从 tools/lib_notes/liaozhai/*.json 组装，请勿手改。 */
LIT.addLibNotes({"liaozhai_kaochenghuang":{"intro":"《聊斋志异》开卷第一篇。宋公病中被召去“赴试”，考的是阴间的城隍缺。篇幅很短，只有一场考试、一次推让、一段托付，但题目“有心无心”把全书的伦理底色摆在了前头：善恶看用心，不看结果。蒲松龄一生困于科场，读这一篇，也要读他借考试写出的那点不甘。","focus":["考题只有八个字：“一人二人，有心无心。”答卷里最要紧的一联是“有心为善，虽善不赏；无心为恶，虽恶不罚”。它把赏罚的标准从行为挪到动机，既不奖励沽名钓誉，也给无心之过留了余地。“诸神传赞不已”，说明这是阴司认可的判例，而不是书生的巧辩。","宋公被点中之后第一句话不是谢恩而是“老母七旬，奉养无人”。神明没有硬压，反而让人“稽母寿籍”，查出“有阳算九年”，再安排张生“摄篆”、“九年瓜代”。冥府的行政在这里很讲人情，也很讲手续，写得像官场，这是《聊斋》常用的“以人间官制写阴间”。","收尾“时卒已三日”“后九年，母果卒”前后严丝合缝，连岳家看到“舆马甚众”的神驾也交代了。篇末说“公有自记小传，惜乱后无存，此其略耳”，是蒲松龄惯用的口吻：把异事推给一个有出处、有亲戚关系的人，增加可信感。"],"notes":[["廪生","由官府供给膳食的生员，秀才中的一等"],["文宗","明清时对提督学政（主持科考的学官）的尊称"],["关壮缪","关羽，“壮缪”是其谥号"],["城隍","一城的守护神，阴间的地方长官"],["稽","查核、查阅"],["阳算","阳寿，人在世的年限"],["摄篆","代理官职（篆指官印）"],["瓜代","任期届满由人接替"],["豁若梦寤","一下子像从梦里醒过来"],["镂膺朱幩","马胸前刻饰、马嚼上缠着红绸，指显贵的车马仪仗"]],"think":["“有心为善，虽善不赏；无心为恶，虽恶不罚”，你认为这条标准放在今天的商业或职场里，站得住吗？","大体站得住，但要补条件。只看动机会让人无法验证，所以现实里要用行为和后果去推断动机。这一联更像对评价者的提醒：同样的好结果，沽名钓誉者不该奖励，同样的坏结果，无心失误者不该重罚。"],"quiz":[["“一人二人，有心无心”这道题，答卷的核心主张是什么？",["善恶以用心为准，有心为善不一定受赏，无心为恶不一定受罚","善人必有好报，恶人必遭天谴","官位高低取决于考试成绩"],"答卷原文是“有心为善，虽善不赏；无心为恶，虽恶不罚”，即论心不论迹。"],["宋公为何先不肯赴任？",["老母七旬，无人奉养","嫌官位太小","不相信神明"],"他当场叩首说“老母七旬，奉养无人”，所以阴司特意查母寿，再安排张生代理九年。"],["“令张生摄篆，九年瓜代”是什么安排？",["让另一位考中者先代理九年，期满再换宋公","让张生永久接任","让宋公九年后转世"],"摄篆是代理，瓜代是期满换人，宋公因此得以先尽孝九年。"]],"cards":[["“有心为善，虽善不赏；无心为恶，虽恶不罚”讲什么？","善恶论心不论迹，动机比结果更重要。"],["宋公为什么能延九年再赴任？","老母七旬无人奉养，冥府查母寿后安排张生先代理。"],["《考城隍》常被读作蒲松龄的什么寄托？","借阴间公正的考试，写对人间科场的不甘。"]],"line":["有心为善，虽善不赏；无心为恶，虽恶不罚","评一个人的工作，我会先看他的用心；复盘时遇到无心之失，也不该按有心之过处理。"],"tags":["善恶论","科场","阴司官制"]},"liaozhai_huabi":{"intro":"朱孝廉在寺中看壁画，被一个“拈花微笑”的天女勾去魂魄，身入画中，与她私会，又被金甲使者追搜，伏榻下“耳际蝉鸣，目中火出”，最后被老僧一弹指叫回。故事从欲念起、以恐惧收，异史氏只用八个字概括：“幻由人生”。这是《聊斋》里把心理过程写成幻境的典型。","focus":["入壁前写得很细：“拈花微笑，樱口欲动，眼波将流”，三个短语把静止的画写成将动未动，朱“注目久，不觉神摇意夺”，才“身忽飘飘如驾云雾”。幻境不是外来的，是他自己的凝视造出来的。","幻中的情节遵循的是做贼者的逻辑：欢好时“蓝麝熏心”，听到“吉莫靴铿铿甚厉，缧锁锵然”就“面如死灰”，要“匿榻下”。从乐到惧只隔一声靴响，作者借此写出欲念和畏罪是同一条根。","异史氏的话不是劝善，而是解释机制：“人有淫心，是生亵境；人有亵心，是生怖境。”在他看来，菩萨点化也只是借幻相让人自己醒，所以他惋惜朱生未能“言下大悟”。"],"notes":[["兰若","佛寺，梵语阿兰若的略称"],["孝廉","举人的别称"],["随喜","游览寺庙，参观佛事"],["垂髫","头发下垂的小孩，这里指年轻少女"],["拈花","手持花枝；也有佛家拈花微笑的典故"],["檀越","施主，对僧人而言的信众"],["亵","轻慢、淫亵"],["婆心","老婆心，指苦口婆心"],["缧锁","拘系罪人的绳索锁链"],["吉莫靴","一种皮靴"]],"think":["老僧说“幻由人生，老僧何能解”，既不替朱生开脱也不责备。你觉得这种态度比直接说教高明在哪里？","他把责任交还给当事人：幻境既由你生，也只有你能破。说教让人防御，而亲身经历“伏榻下不敢息”的恐惧，比任何话都深。边界是：他仍用弹壁唤回，说明点醒需要外力，但理解必须自己完成。"],"quiz":[["朱生“身忽飘飘如驾云雾，已到壁上”的直接起因是？",["长时间凝视壁画天女，神摇意夺","老僧作法","同伴孟龙潭催促"],"原文写他“注目久，不觉神摇意夺，恍然凝想”，随后才入壁，起因在自己的凝视。"],["金甲使者的出现在情节中的作用是？",["使欢爱骤转为恐惧，体现欲念与畏罪相连","说明画中有真神","给孟龙潭一个出场机会"],"使者一到，女“面如死灰”，朱“伏榻下”，由乐到惧只一瞬，正为异史氏“亵境生怖境”铺垫。"],["异史氏对老僧的遗憾是什么？",["没能让朱生当场大悟、披发入山","没有救出朱生","没有惩罚天女"],"原文：惜不闻其言下大悟，披发入山也。"]],"cards":[["《画壁》里“幻由人生”的出处是谁说的？","老僧在朱生追问时说，异史氏再引来解释。"],["“人有淫心，是生亵境；人有亵心，是生怖境”讲什么？","幻境按人心自动生成：欲念引出亵境，亵境又引出恐惧。"]],"line":["幻由人生，此言类有道者","遇到心里自己生出来的纠结，我常对自己说一句“幻由人生”，先排查是不是自己把事情想大了。"],"tags":["幻境","欲念","心理"]},"liaozhai_wangliulang":{"intro":"淄川渔人许某每夜酹酒河上，祭奠溺鬼，引来少年王六郎暗中赶鱼相报。六郎本可趁一个溺水女子投生，却因不忍而放过，反被天帝升为土地。篇中最见功力的是“友”：酒友、故人、神与人之间的牵挂。篇末异史氏以林下者投友不遇作比，把写鬼的篇章落回现实。","focus":["开头只写许某“饮则酹地，祝云：河中溺鬼得饮”，细节不多，已把后文的恩义埋下：他不是为了求报，而是习惯。王六郎的赶鱼是“报酹奠”，所以两人交往一开始就是平等的酒友，而不是人对鬼的施舍。","两次代死的情节写得很克制。第一次，六郎看到“抱婴儿来”的妇人坠河，“怜其抱中儿，代弟一人，遂残二命，故舍之”；许某在岸边“意良不忍”，又“转念是所以代六郎者，故止不救”。一个想救又不救，一个能脱身又不忍，人鬼各有一次心理挣扎。","异史氏接着写“置身青云，无忘贫贱”，随后引一则同乡笑话：做官的童年好友被投靠，“殊失所望”。这段用冷笑话压住上文的温情，意思是：连鬼神都做得到的事，人间显贵反而做不到。"],"notes":[["业满","罪业期满，指溺鬼受罪的期限届满"],["代者","替死者，溺鬼需找一人代替才能投生"],["亭午","正午"],["投生","转世为人"],["资斧","旅费"],["贵介","地位高贵的人"],["林下","指退居乡野的人"],["周顾","周济照顾"],["戴笠人","戴斗笠的贫贱之交，典出越人歌式的誓语"],["羊角风","旋风"]],"think":["王六郎放弃代死，许某却曾一度“止不救”。你怎样看待两人的“不忍”和“不救”之间的差别？","六郎是当事人，放弃的是自己的解脱；许某是旁观者，不救的是一条无关的生命，却因为朋友的缘故。作者没有判许某的罪，只写他“意良不忍”，说明善意在利害面前会动摇，而六郎的“仁”更重。这正是升神的原因。"],"quiz":[["王六郎最初帮许某赶鱼，是为了什么？",["报答他每夜酹酒的情意","向他索要香火","测试他的善恶"],"原文：前君之获鱼，独胜于他人者，皆仆之暗驱，以报酹奠耳。"],["六郎被升为土地的原因是？",["一念恻隐，放弃代死，感通上帝","许某向官府保举","他生前是官员"],"六郎说“前一念恻隐，果达帝天”，因不忍妇人与孩子同死而放弃投生，才被授土地。"],["异史氏写林下者投友的笑话，用意是？",["对比鬼神能不忘旧交，显贵却不能","说明做官的人都贪","解释土地庙的来历"],"开头即点出“置身青云，无忘贫贱，此其所以神也”，笑话是反衬。"]],"cards":[["王六郎为什么放过抱婴儿的妇人？","怜她怀中的孩子，若代他一人会“遂残二命”。"],["《王六郎》异史氏的立意是什么？","身居高位不忘贫贱，才配称神。"],["许某最后为什么不再打鱼？","访友后得赠遗，家境稍裕。"]],"line":["置身青云，无忘贫贱，此其所以神也","升职之后我常提醒自己：置身青云，无忘贫贱，当年帮过我的人要记得联系。"],"tags":["友情","仁心","人鬼"]},"liaozhai_toutao":{"intro":"蒲松龄以“童时赴郡试”的亲历口吻写一场街头幻术：春节“演春”时，艺人受官府之命，在冰天雪地里“取桃”，竟派儿子顺绳爬上天去，最后“肢体纷堕”，又钻出箱子谢赏。全篇是短小精悍的叙事样板，值得看它怎样一步步把人带进幻觉，又在最后一笔拆穿。","focus":["开头先交代时间、场合与旁观者的身份：“余从友人戏瞩”“时方稚，亦不解其何官”。作者把自己写成一个看不懂官场、只看热闹的孩子，因而可信，也因而省去对官员的评论，留给读者自己去体会。","对话把幻术写成了一出父子家庭剧：“官长殊不了了！坚冰未解，安所得桃？”“阿翁亦大愦愦！如此一线之绳……倘中道断绝，骸骨何存矣！”父亲先诱“必有百金赏，当为儿娶一美妇”，再强迫。幻术的惊险被换成了世俗的无奈，所以最后“肢体纷堕”时，读者才真的信了悲痛。","末句“后闻白莲教，能为此术”，是蒲松龄常在篇末加的一句“传闻”，既收束又使篇章带上时代的阴影：民间幻术与秘密教门常被视为同路。"],"notes":[["演春","立春前一日的迎春游艺仪式"],["藩司","明清布政使司衙门，主管一省民政财政"],["颠倒生物","违反季节与常理的变化，这里指令桃实反季出现"],["笥","盛物的竹箱"],["王母园","西王母的蟠桃园"],["愦愦","糊涂"],["瘗","埋葬"],["结草","报恩的典故"],["白莲教","民间秘密宗教，常聚众起事"],["苗裔","后代"]],"think":["作者用“儿子被肢解”来铺垫，最后又让他钻出箱子。这种“先悲后喜”的结构，对观众和读者各有什么效果？","悲是为了让谎言更真，喜是为了让技艺亮相。观众先被情感带入，才会对“术”更折服；读者则在笑的同时意识到自己刚才也被骗了。边界是：它要成立，前面的悲必须写得克制，不能让人一眼看出是戏。"],"quiz":[["术人为什么要“偷桃”而不是直接取桃？",["春初坚冰未解，人间无桃，只有王母园四时不凋","他喜欢冒险","官府规定的做法"],"原文：“春初雪积，人间何处可觅？唯王母园中，四时常不凋谢。”"],["“八八儿，不出谢赏”揭示了什么？",["儿子并未真死，一切是幻术","儿子被官员救活","术人在说梦话"],"称呼出现后，“蓬头僮首抵笥盖而出”，揭开前面“肢体纷堕”的幻象。"],["作者用“余从友人戏瞩”开头的作用是？",["以亲历者口吻增加真实感","说明自己是官员","交代当年的考试内容"],"亲历叙述加上“时方稚”的天真视角，使后面的奇事更可信。"]],"cards":[["《偷桃》里的“演春”是什么？","立春前一日各行商贾在藩司前表演迎春的仪式。"],["《偷桃》结尾反转在哪里？","儿子“肢体纷堕”后又从竹箱里钻出来谢赏。"]],"line":["以其术奇，故至今犹记之","那场培训讲得不算精彩，但里面的一个方法很奇，所以至今犹记之。"],"tags":["幻术","叙事","亲历"]},"liaozhai_zhongli":{"intro":"一个卖梨的乡人，对破衣道士苦苦讨梨拒不给，旁人替道士买来一枚，道士竟当场种梨、结果、分尽。等乡人回头一看，车上的梨也没了，原来都被道士变成了赠品。幻术是外壳，内核是对吝啬的讽刺：异史氏骂的不是道士，是“憨状可掬”的乡人，以及一类“素封者”。","focus":["道士的话先占住了理：“一车数百颗，老衲止丐其一，于居士亦无大损，何怒为？”再接“出家人不解吝惜”，一句就把两方立场分出高下。乡人的“执不肯”“怒加叱骂”，在这样的话下显得小气。","种梨一段写得极有层次：“掬梨大啗，且尽，把核于手，解肩上镵，坎地深数寸……”“勾萌出，渐大，俄成树……倏而花，倏而实”。动词短促，时间被压缩，像一段快镜头，读者与围观者一样“万目攒视”。","异史氏借此转向现实：那些有钱人“良朋乞米，则怫然，且计曰：是数日之资也”，却“淫博迷心，则倾囊不吝”。他骂的是舍不得小钱、舍得大钱的人，笔锋刻薄而具体。"],"notes":[["居士","本指在家修佛者，这里是对一般人的敬称"],["老衲","老僧自称，这里道士也被如此说，指老和尚式的口吻"],["佣保","店里的雇工"],["镵","一种掘土的工具"],["勾萌","弯曲的新芽"],["扶疏","枝叶繁茂分散的样子"],["素封","没有官爵但富如封君的人"],["锱铢","极小的重量，喻极少的钱"],["愦愦","糊涂"],["俵散","分发"]],"think":["乡人并不是坏人，只是不愿白给。你觉得蒲松龄为什么偏要让道士用“变没他所有梨”的方式惩罚他？","因为他的“吝”是个小事，惩罚也不能太重；让梨凭空分尽，是让他亲眼看见自己的东西被别人轻松拿走。这样的结局既是教训，又带笑，不是复仇。边界是：道士其实只要一枚，最后拿走一车，可见作者的重点是讽刺，不是公平。"],"quiz":[["道士第一次开口讨梨时，用什么理由说服乡人？",["一车数百颗，只求一枚，对你无大损","他是出家人，应当受供养","他愿意以后重谢"],"原话：“一车数百颗，老衲止丐其一，于居士亦无大损，何怒为？”"],["乡人最后发现了什么？",["车里的梨都空了，车靶被新凿断","车被道士偷走","钱被人偷了"],"“方悟适所俵散，皆己物也”，车靶是新凿断的，所以那棵梨树正是他的车靶所化。"],["异史氏批评的对象是？",["吝于济人而挥霍于赌博的富人","出家人","围观的市人"],"他列举“良朋乞米则怫然”“淫博迷心则倾囊不吝”，批评的是这类人。"]],"cards":[["《种梨》里道士种梨靠什么材料？","乡人车上的车靶，被道士暗中取用。"],["异史氏骂的“蠢尔乡人”指什么人？","吝于济人、却挥霍于赌博的“素封者”。"]],"line":["出家人不解吝惜，我有佳梨，请出供客","他对预算很吝，却对客户的招待毫不吝惜。我常说一句“出家人不解吝惜”，提醒自己该花的钱别抠。"],"tags":["幻术","讽刺","吝啬"]},"liaozhai_laoshandaoshi":{"intro":"王生仰慕仙术，上劳山拜师，砍柴一个月就想回家，见了月中饮酒的神迹又留下，最后只学了个穿墙术，回家一试撞出个大包。故事极短，却是《聊斋》最广为人知的讽刺篇：它讽刺的是只想要结果、不肯下功夫的人。异史氏更借此指向官场那些教人“横行无碍”的献媚者。","focus":["开头说“恐娇惰不能作苦”，王生答“能之”。此后一个月“手足重茧，不堪其苦，阴有归志”，其变化被一句话概括：“不过早樵而暮归”。作者用“重茧”“不堪”写出所谓志向，只是想象中的仙术，一遇苦役就退缩。","师父的法术写得好看：剪纸为月、“箸掷月中”出嫦娥、“三人坐月中饮，须眉毕见，如影之在镜中”。这是仙术的展示，也是试探：门人“环听奔走”，王生只“窃忻慕，归念遂息”，说明他在意的是奇观，而不是学术。","异史氏的转折更重：“有伧父，喜疢毒而畏药石，遂有舐痈吮痔者，进宣威逞暴之术……势不至触硬壁而颠蹶，不止也。”他把王生放大为所有听信“可以横行无碍”的上位者：初试有效，就以为天下皆可。"],"notes":[["负笈","背着书箱，指外出求学"],["蒲团","用蒲草编的坐垫"],["樵苏","打柴割草"],["翦纸","剪纸"],["嫦娥","月宫仙女"],["踣","向前跌倒"],["伧父","粗鄙的人"],["疢毒","病毒，比喻有害的东西"],["药石","药物和砭石，喻规劝的忠言"],["舐痈吮痔","给人舔疮吮痔，比喻谄媚到极点"]],"think":["王生学到穿墙术的“口诀”，却失败了。他真正缺的是什么？","缺的是对条件的理解：第一次成功有师父在场、有“洁持”的前提，他不知道，也不愿意知道，只记住了动作。在工作里，也常有人把某次成功的做法当通则，忽略了背后的前提。"],"quiz":[["王生为什么想回家？",["砍柴月余，手足生茧，又没学到术","想念妻子","师父驱逐他"],"原文“过月余，手足重茧，不堪其苦，阴有归志”，之后又因师父不传术而辞别。"],["师父传穿墙术时最重要的叮嘱是？",["俛首骤入，勿逡巡；归宜洁持","念咒一百遍","夜里再练"],"他说“俛首骤入，勿逡巡”，又说“归宜洁持，否则不验”，王生只记住了前者。"],["异史氏把王生引申为哪一类人？",["听信“可横行无碍”之术而致失败的官员","好学的读书人","求仙的道士"],"他批评“舐痈吮痔者，进宣威逞暴之术”，终究“触硬壁而颠蹶”。"]],"cards":[["《劳山道士》的核心讽刺对象是？","想不吃苦只求捷径、又把偶然成功当通则的人。"],["王生回家试术的结果？","头撞硬壁，额上起大包。"]],"line":["俛首骤入，勿逡巡","这个项目想过关，就得俛首骤入，别在门口反复犹豫。"],"tags":["讽刺","求道","捷径"]},"liaozhai_changqingseng":{"intro":"长清寺里的老僧坐化，魂魄飘到河南，附到一个坠马而死的贵公子身上。他面对满屋的妻妾钱粮，一概拒绝，只想回寺。这个故事的奇不在转生，而在转生之后：富贵当前，他“灰心木立”，一定要回到旧寺。篇末异史氏给出的判语是“性定”。","focus":["“魂适相值，翕然而合”写借尸还魂只用八个字，没有渲染，作者把力气花在后面的反应上：“粉白黛绿者，纷集顾问，大骇曰：我僧也，胡至此？”一个八十岁的老僧突然被美人围住，惊骇比任何描写都更说明他的本性。","他的拒绝是一个个具体动作：“饷以脱粟则食，酒肉则拒，夜独宿，不受妻妾奉”；“钱簿谷籍，杂请会计，公子托以病倦，悉谢绝之”。这些细节让“性定”二字有了实感，守戒不靠壮语，而在每顿饭、每个夜晚。","异史氏说“予于僧不异其再生，而异其入靡丽纷华之乡，而能绝人以逃世”，把注意力从“再生”转到“能绝”，并反问“若眼睛一闪，而兰麝生心，有求死不得者矣”，也算警告自己。"],"notes":[["圆寂","僧人去世"],["翕然","聚合一致的样子"],["脱粟","只去壳的粗米"],["返魂","魂魄还生"],["手泽","遗物上留下的手迹气息"],["灰心木立","心如死灰、呆立如木"],["纪纲","仆人头目"],["靡丽纷华","奢靡华美"],["兰麝生心","美色熏染而动心"],["性定","本性坚定"]],"think":["老僧附身贵公子，却选择回到寺中。你觉得“性定”更接近天性，还是长期修行的结果？","文中看不出他是天生如此，只能从“八十余年”的积累推测：定性来自长期的守戒习惯，能在环境剧变时保持原样。边界是：作者说“予不异其再生”，不夸张神迹，只赞他定力，所以这不是天赋问题，而是修成的东西。"],"quiz":[["借尸还魂后，老僧对酒肉与妻妾的态度是？",["酒肉拒绝，妻妾不受，仍守僧戒","全部接受","一概视而不见但不拒"],"原文“饷以脱粟则食，酒肉则拒，夜独宿，不受妻妾奉”。"],["他重返长清寺，首先看到什么？",["自己的旧坟，荒草未合","寺院被拆","弟子都已散去"],"“三尺孤坟，荒草犹未合也”，旧身刚葬不久。"],["异史氏认为最难得的是？",["入富贵之乡而能绝人逃世","借尸还魂","记得前世"],"他说“不异其再生，而异其入靡丽纷华之乡，而能绝人以逃世”。"]],"cards":[["《长清僧》里的“性定”指什么？","魂魄千里不散，本性在环境剧变中不变。"],["老僧还魂后第一件想做的事？","回山东长清寺看自己的旧身。"]],"line":["人死则魂散，其千里而不散者，性定故耳","一个团队换了环境还能保持工作习惯，靠的就是性定故耳。"],"tags":["转生","定力","佛家"]},"liaozhai_sheren":{"intro":"弄蛇人养了两条青蛇，一条死了，另一条“二青”走失后又带回一条小蛇，取名“小青”。多年后，二青越长越大，蛇人把它们放归山林，又在山中被二青认出而不加害。这是《聊斋》里少见的动物与人长情的篇章。篇末异史氏借蛇骂人：“下井复投石”的，比蛇还不如。","focus":["二青的好处写在细节里：额有赤点，“尤灵驯”；走丢后蛇人“冥搜亟呼”，又每次“纵之去，俾得自适，寻复还”；找不到时“怏怏遂行”。人对蛇的信任来自长期放养，蛇的回报也由此而来。","二青带小蛇回来，“小蛇虽不去，然瑟缩不敢食。二青含哺之，宛似主人之让客者”。作者让蛇学会了做人的礼数，读来既可笑又温柔。","多年后二青暴出追人，蛇人“视其首，朱点俨然，始悟为二青”，呼名即止，“如昔弄状”，还听他叮嘱“勿扰行人，以犯天谴”。异史氏收尾：“独怪俨然而人也者，以十年把臂之交，数世蒙恩之主，辄思下井复投石焉”，是整篇的锋芒所在。"],"notes":[["弄蛇","以耍蛇为业"],["驯","顺从"],["笥","装蛇的竹箱"],["拱璧","大块的玉璧，喻极珍贵"],["委蛇","蜿蜒前行"],["衒技","炫耀技艺"],["天谴","上天的惩罚"],["把臂之交","亲密的朋友"],["下井复投石","朋友落难反而再加伤害"],["药石相投","忠言相劝"]],"think":["蛇人放走二青，二青后来又“暴出如风”。这是否说明放生是对的？","说明他的做法并不为了换回回报，却恰好得到回报：二青能认出他、听他劝，说明相处的情分在。边界是：作者没有说放生一定有好结果，而是把这段交情写得有来有往，使“人不如蛇”的批评成立。"],"quiz":[["蛇人为什么给新来的蛇起名“小青”？",["它由二青带来，经训练后与二青无异","它是青色","它额有赤点"],"原文“荷去教之，旋折辄中规矩，与二青无少异，因名之小青”。"],["二青“以首触笥”是什么意思？",["想带小青一起走","想吃东西","想攻击蛇人"],"蛇人悟其意，放出小青，二蛇“交缠如饴糖状”，一起离去。"],["异史氏借蛇批评哪种人？",["受恩却“下井复投石”的人","贪财的人","不信神的人"],"他说“以十年把臂之交，数世蒙恩之主，辄思下井复投石”的人，连这条蛇也比不上。"]],"cards":[["二青的特征是什么？","额上有赤点，灵驯，蛇人一见便认出。"],["蛇人放走二青时说了哪句话？","“世无百年不散之筵。”"]],"line":["世无百年不散之筵","项目组要解散了，我对同事说：世无百年不散之筵，今天好好道个别。"],"tags":["动物","情义","放生"]},"liaozhai_hujianv":{"intro":"历城殷天官年轻时家贫而有胆，与同学打赌，独宿荒废多年的凶宅，半夜撞见狐家嫁女，被奉为贵客，席间偷揣一只金爵，天亮拿出来证明自己宿过。多年后他在朱氏家宴上见到同款金爵，才知“千里之物，狐能摄致”。这篇没有悲欢，只有有趣的世情：胆大的人、热闹的婚宴、一个回收伏笔的结尾。","focus":["前半写胆与场景：“有能寄此一宿者，共醵为筵。”殷公“跃起曰：是亦何难！”“携一席往”。荒宅里“长莎蔽径，蒿艾如麻”，月光“昏黄”，细节写得稳，不夸张鬼气，反而衬出他的从容：“窃笑传言之讹”。","狐翁的应对最见人情：先是“有生人在”，然后“此殷尚书，其睡已酣，但办吾事，相公倜傥，或不叱怪”，到了公醒来，立即“跪而言曰：小人有箕帚女，今夜于归”。所谓凶宅里的怪异，其实是一家人办喜事，对来客只怕冒犯，不怕他是人。","收尾用另一个场景呼应：朱家的爵“凡八只”，如今“仅存其七”，而十年尘封如故。殷公赠回一只“近似之”的爵，主人“骇绝”。这不是寓言，是用小器物把“狐能摄致”这件事坐实，也让殷公的“偷”变成合理的物归原主。"],"notes":[["醵","凑钱，聚资饮酒"],["莎","莎草，多年生杂草"],["箕箒女","为人持箕帚的女儿，是对自己女儿的谦称"],["于归","出嫁"],["傧","婚礼上的接引者"],["酒胾","酒和大块的肉"],["金爵","金制的酒杯"],["什袭","层层包裹，珍藏"],["明府","对县令的尊称"],["摄致","凭法术把东西弄来"]],"think":["狐翁在殷公偷爵后“惟恐公闻”，选择不声张。你怎么理解这种“装不知道”的做法？","这是让对方保住颜面的做法：偷爵不是恶意，说破反而伤人；狐家有愧于“有失”，所以也不愿惹事。边界是：双方都选择沉默，是因为彼此之间没有真正的利害冲突；若涉及重大利益，沉默就是纵容。"],"quiz":[["殷公为什么敢夜宿凶宅？",["打赌，且自认胆大，想捉鬼狐为证","奉官府之命","想找宝藏"],"他说“有鬼狐，当捉证耳”，并答应同学的赌约。"],["狐翁见殷公醒来，第一反应是？",["跪下赔礼，请他陪坐","呵斥驱逐","装作不见"],"他“跪而言曰：小人有箕帚女，今夜于归，不意有触贵人，望勿深罪”。"],["结尾朱家酒宴上出现了什么？",["与狐家所见完全相同的金爵","一只假爵","那位狐翁"],"朱家酒爵“凡八只”，仅存七，与狐家所偷之爵“款式雕文，更无殊别”。"]],"cards":[["《狐嫁女》里的物证是什么？","殷公从狐家婚宴上带回的金爵。"],["狐翁说“有箕帚女”是什么意思？","自谦，称自己的女儿为“持箕帚者”。"]],"line":["千里之物，狐能摄致，而不敢终留也","对账时发现一笔丢失的货款自己回来了，大家都说：千里之物，狐能摄致，而不敢终留也。"],"tags":["狐","凶宅","伏笔"]},"liaozhai_jiaona":{"intro":"孔雪笠落魄寄居，被皇甫公子邀入“单府”授课，后来胸间生疮，公子的妹妹娇娜来治，他又得娶松娘。多年后狐家遭雷劫，孔生替他们挡雷，娇娜口吐红丸救活了他。这篇的写法与一般“人狐爱情”不同：孔生与娇娜始终没有成为夫妻，关系落在知己与恩义上。这里选两个关键场面：割瘤与雷劫。","focus":["割瘤一场写得很特别：娇娜“娇波流慧，细柳生姿”，“把握之间，觉芳气胜兰”，孔生“嚬呻顿忘，精神为之一爽”。可是动手时，“生贪近娇姿，不惟不觉其苦，且恐速竣割事，偎傍不久”。美色之心与割肉之痛并写，既逗笑，又让人记住“心脉动矣”的那句玩笑。","医术也写得干净：她“脱臂上金钏，安患处”，把肿块束在钏内，用“刃薄于纸”的刀割，再“口吐红丸，如弹大”按住旋转三周，由“热火蒸腾”到“遍体清凉”。过程像手术，又保持仙家的飘然。","孔生被雷震死后，娇娜“以舌度红丸入，又接吻而呵之”，才使他苏醒。古人对男女之防很严，这里却因救命而不避，使“友”的分量压过了“情”。"],"notes":[["娇波流慧","眼波灵动有神采"],["细柳生姿","身段柔美如柳"],["金钏","手镯"],["罗衿","丝罗衣襟"],["红丸","狐的内丹，能治病救命"],["雷霆之劫","狐修炼到一定阶段要经受的雷击之灾"],["仗剑","手握剑"],["霹雳","响雷"],["舁","抬"],["度","送入"]],"think":["孔生为什么愿意替狐家抵挡雷劫？这与他当初对娇娜的感觉有关吗？","动机里既有情义（对公子兄妹），也有救命之恩，同时也有对娇娜的爱慕；但他刀向鬼物时，“念似娇娜”的是念头，不是占有的心。边界是：蒲松龄在篇末说他“羡其得腻友”，说明作者想写的是知己之情，而非情欲。"],"quiz":[["娇娜割瘤时用什么先压住肿块？",["金钏","银针","手指"],"原文“脱臂上金钏，安患处，徐徐按下之”，创突起寸许，高出钏外。"],["孔生在雷劫中被什么救活？",["娇娜口吐的红丸","皇甫公子的符咒","松娘的汤药"],"“以舌度红丸入，又接吻而呵之，红丸随气入喉”，孔生乃苏。"],["娇娜说“姊姊乱吾种矣”指什么？",["姊姊（松娘）生的孩子带有狐意","孩子长得像孔生","孩子夭折"],"小宦长成“貌韶秀，有狐意”，说明松娘本是狐类，故娇娜笑她“乱吾种”。"]],"cards":[["《娇娜》里娇娜为何不嫁孔生？","作者用“腻友”写他们的关系，另给他娶了松娘。"],["娇娜的“红丸”是什么？","狐仙的内丹，能治病、救命。"]],"line":["孔郎为我而死，我何生焉","一个团队里有人因为替我顶雷而受损，我不会说一句“孔郎为我而死，我何生焉”，但得为他兜底。"],"tags":["狐","友情","医术"]},"liaozhai_sansheng":{"intro":"刘孝廉记得前世，说自己一生做官不干净，死后在阴间被判三世受罚：做马、做狗、做蛇。每一世他都受不了苦，想用死来逃避，结果被冥王一再加罪。这是一篇寓言式的轮回小品，看似荒诞，其实在写：以为可以投机取巧躲避，恰恰是罪的延长。","focus":["开篇的细节很戏谑：他见冥王的茶“清澈”，自己的杯中“浊如醪”，“暗疑迷魂汤得勿此耶？乘冥王他顾，以盏就案角泻之”。他想偷偷倒掉迷魂汤，保住前世记忆，这个小动作后来成了“能记前身事”的原因。","做马一段写得最有现场感：“主人骑，必覆障泥，缓辔徐徐，犹不甚苦；惟奴仆圉人，不加鞯装以行，两踝夹击，痛彻心腑。”作者从骑马者的角度写马的疼，连“障泥”这样的细部都具体到位，后文他劝人“乘马必厚其障泥”，因此有了来由。","异史氏的话把比喻说破：“毛角之俦，乃有王公大人在其中；所以然者，王公大人之内，原未必无毛角者在其中也。”这是对权贵的尖刻讽刺：衣冠之内可能是畜生。"],"notes":[["孝廉","举人的别称"],["搢绅","插笏于带的官员，指有身份的士大夫"],["迷魂汤","传说在阴间喝了就忘记前世的汤"],["障泥","垂在马腹两侧遮挡泥土的鞯"],["圉人","养马的人"],["规避","逃避责罚"],["冥司","阴间官府"],["毛角之俦","畜生一类"],["鞫","审讯"],["负盐车","拉盐车，典出伯乐遇骥，形容受苦役"]],"think":["三世的惩罚中，“规避”是反复出现的罪名。你怎么理解“想用死来逃避”被视为罪？","作者想说：苦是赎罪的一部分，若想逃避，就是对自己的罪不负责。边界是：这是蒲松龄的因果观，与现代的人权观念不同，但作为寓言，它提醒我们回避责任往往让代价翻倍。"],"quiz":[["刘孝廉为什么能记得前世？",["他偷偷把迷魂汤倒掉了","冥王特意给他保留","他修了佛法"],"开篇他趁冥王他顾，“以盏就案角泻之，伪为尽者”。"],["为什么他劝人“乘马必厚其障泥”？",["他做马时夹击之痛，只有奴仆不加鞯装才如此","他想卖障泥","他怕马踢人"],"“两踝夹击，痛彻心腑”，是他做马时最切身的苦。"],["异史氏的核心讽刺是？",["王公大人之中未必没有“毛角”（畜生）","畜生也有修炼的","轮回是假的"],"原文：“王公大人之内，原未必无毛角者在其中也。”"]],"cards":[["《三生》里三世指什么？","马、狗、蛇，最后才又为人。"],["“负盐车”在异史氏里指什么？","受苦役的马。"]],"line":["王公大人之内，原未必无毛角者在其中也","评价一个人，不能只看职位，要想到王公大人之内，原未必无毛角者在其中也。"],"tags":["轮回","因果","讽刺"]},"liaozhai_yesheng":{"intro":"叶生才高而科场不利，县令丁乘鹤赏识他，屡次相助，却始终没能考中。叶生病死，魂魄仍随知己赴任，教出县令的儿子，儿子连中举人，自己才魂销。这篇是蒲松龄借叶生写自己：士为知己者死，不是客套，是写一种“不被世间所识”的痛。异史氏的议论长而沉痛，值得慢读。","focus":["叶生出场只有一句：“文章词赋，冠绝当时，而所如不偶，困于名场。”紧接着是丁公的知遇：“召与语，大悦，使即官署，受灯火，时赐钱谷恤其家。”知遇之恩写得具体，所以后来“魂从知己”的行为有了依据。","他自己落第后“形销骨立，痴若木偶”，听说丁公要待他同行，才“持书啜泣，寄语来使：疾革难遽瘥，请先发”。一个人病到几乎不能起身，还在体谅别人，更显悲。","最后那一幕是反讽：衣锦荣归，妻子见他“掷具骇走”：“君死已久，何复言贵？”他一入灵堂，“扑地而灭”，“衣冠履舄如蜕委”。荣耀与死亡在同一刻出现，这是整篇最痛处。"],"notes":[["名场","科举考场"],["铩羽","羽毛受伤，喻失败"],["闱","科举考场"],["亚魁","乡试第二名，也泛指乡试名次靠前"],["黄钟长弃","黄钟（大吕）被抛弃，喻才高被弃"],["非战之罪","失败不是不会打，而是运气不济"],["窀穸","墓穴，指安葬"],["衣冠履舄","衣帽鞋履"],["游泮","入学成为秀才"],["孙山之外","落榜"]],"think":["叶生的魂魄始终不明自己已死，直到回家才“扑地而灭”。作者为什么让他“不知”？","因为他一心为知己，没有意识到自己已无身份、无前途。直到见到妻子、灵柩，才意识到。这是对科场失败者的哀悼：他们的价值被世界否认到连死亡都不被感知。边界是：作者在异史氏里直接自比，所以这是蒲松龄借叶生写自己。"],"quiz":[["叶生的魂为何随丁公而行？",["丁公是他的知己","他想成仙","他怕被鬼差抓走"],"异史氏说“魂从知己，竟忘死耶？”点出知遇之情。"],["叶生所说“非战之罪”指什么？",["自己的落第是命，不是才不足","战争不利","丁公用人不当"],"他希望借别人的成名，使“天下人知半生沦落，非战之罪”。"],["他回家后发现什么？",["自己早已死去，灵柩仍在","家人已搬走","妻子再嫁"],"妻子说“君死已久，何复言贵”，他见灵柩，“扑地而灭”。"]],"cards":[["《叶生》写的是谁？","借叶生写蒲松龄自己的科场失意与对知己的感恩。"],["“非战之罪”在篇中是谁说的？","叶生，说明自己落第不是不才。"]],"line":["魂从知己，竟忘死耶","对那些真正赏识过我的老领导，我始终是魂从知己，竟忘死耶的心态。"],"tags":["科举","知遇","魂"]},"liaozhai_qingfeng":{"intro":"耿去病夜入凶宅，与狐翁的侄女青凤结缘，被狐叔拆散；两年后青凤被猎犬追，躲进耿生怀里，才得团圆。这里选的是后半：狐翁之子孝儿来求耿生救他的父亲，耿生以“非青凤来不可”拒绝，青凤本人却先问“果救之否”。这一段把家族、礼教、情爱与恩怨拧在一起，既有人情，也有狐情。","focus":["孝儿的求救与耿生的拒绝，一问一答非常有分寸：孝儿“伏地，怆然曰：家君有横难，非君莫拯”，耿生答“楼下之羞，耿耿在念，他事不敢与闻”，又说“必欲仆效绵薄，非青凤来不可”。他拒绝的原因是旧怨，条件是旧情，两者混在一起，是人之常情。","青凤的反应更显品格：“果救之否？”“救则救之；适不之诺者，亦聊以报前横耳。”她先担心的是叔父，不是自己的委屈，笑着说“忍哉”，又替叔父辩解：“昔虽获罪，乃家范应尔。”她把礼教的严厉看作应有之事，也看出叔父的难处。","最后叟“赧然谢别”，当晚“果举家来”，从此“如家人父子，无复猜忌”。冤仇以救命化解，作者没有再让他们补一句道歉，已经在“赧然”里了。"],"notes":[["横难","突如其来的灾祸"],["年家子","科举同年的子弟"],["猎狐","打到的狐"],["镂膺虎韔","装饰华丽的马具与虎皮弓袋"],["托裘敝","借口皮衣破损"],["介介","心中耿耿不平"],["返哺","喻子女报答父母（这里指侄女报答叔父）"],["家范","家法，家风"],["赧然","羞惭脸红"],["楼下之羞","指前文耿生在楼下被狐叔斥责的难堪"]],"think":["耿生拒绝救狐翁，却又暗暗让青凤决定。你认为他是真的记仇，还是借此逼青凤表态？","文中他明确说“楼下之羞，耿耿在念”，说明确有怨气；但他把决定权交给青凤，是尊重她。边界是：作者既写了他的小心眼，也写了他的情义，没有把他写成完人。"],"quiz":[["耿生为何一开始不愿救狐翁？",["记着楼下被呵斥的羞辱，且想让青凤回来","嫌麻烦","不信孝儿的话"],"他说“楼下之羞，耿耿在念”，条件是“非青凤来不可”。"],["青凤听说后的反应是？",["先问是否救了她叔父，并替叔父辩解","责怪耿生","哭着不肯回去"],"“果救之否？”并说“昔虽获罪，乃家范应尔”。"],["莫三郎来时，耿生用什么借口留下黑狐？",["借口皮裘破旧，乞得补缀","说是友人","用钱买"],"原文“便托裘敝，乞得缀补”。"]],"cards":[["《青凤》里的“楼下之羞”指什么？","耿生在楼下与青凤相会，被狐叔呵斥的一幕。"],["青凤如何评价叔父的严厉？","“家范应尔”，认为那是应有的家规。"]],"line":["楼下之羞，耿耿在念","对方当年当众让我难堪，我嘴上不提，心里还是楼下之羞，耿耿在念，所以合作前得先谈开。"],"tags":["狐","报恩","情义"]},"liaozhai_jiaer":{"intro":"商人之妻被狐魅缠身，终日癫狂，十岁的儿子先用刀砍断狐尾，又摸清狐的巢穴，最终用掺了药的白酒毒死三只狐。故事中的“贾儿”不是神童，而是靠一点点具体的观察、套话、借钱买酒完成任务。节奏紧、细节多，是《聊斋》里难得的“少年侦探小说”。","focus":["先写母亲的病：“夜厌与人居”“日效杇者，以砖石叠窗上”，把狐魅的控制写成一个人行为的失序。这样的写法不夸鬼怪，只写她的反常，读者因此更怕。","贾儿的计谋很具体：夜里藏刀，“以瓢覆灯，伺母呓语，急启灯”，砍断狐尾；次日“视血迹逾垣而去，迹之，入何氏园中”；再潜入园中伏草，听到“明日可取白酒一瓻来”，才有下一步的买酒。线索与行动环环相扣，没有一处凭空。","收尾“我儿，讨狐之陈平也”是赞，随后一句“但益之嗽，呕痰辄数升，寻卒”是冷。母亲还是死了，狐祟虽除，代价仍在。作者没有让孩子的胜利变得轻松。"],"notes":[["贾","商人"],["庖妪","厨娘"],["杇","涂墙的工具，指泥瓦匠"],["瓢覆灯","用瓢罩住灯，暂时遮光"],["蓬科","蓬乱的草丛"],["一瓻","一壶，瓻是一种酒器"],["妗","舅母"],["猎药","毒杀猎物的药"],["汤饼","汤面"],["陈平","汉初谋臣，擅用奇计"]],"think":["贾儿用谎话和假尾巴骗过狐，这算不算不义？你怎么评价他的手段？","对害人的妖魅用计，在故事里没有道德负担；作者赞他是“陈平”，说明只要目的正当，手段不算污点。边界是：真实的人际里，欺骗的代价很大，这类“智取”只在对象是害人者时才被接受。"],"quiz":[["贾儿第一次伤狐是怎样？",["夜里以瓢覆灯，伺机开灯砍断狐尾","白天用火烧","请道士驱邪"],"原文“以瓢覆灯，伺母呓语，急启灯……击之，仅断其尾”。"],["他怎样骗取长须狐信任？",["谎称同类，露出假尾巴","送给对方钱","装哑巴"],"他自称“胡氏子”，“微启下裳，少少露其假尾”。"],["结局里母亲如何？",["狐除病愈，但痰嗽后不久死去","完全康复","出家"],"原文“而妇瘠殊甚，心渐明了，但益之嗽，呕痰辄数升，寻卒”。"]],"cards":[["《贾儿》里的“陈平”是谁？","汉初善用奇计的谋士，这里比喻贾儿。"],["贾儿用什么毒死狐？","买来的白酒里掺了从舅母处偷来的猎药。"]],"line":["窃之，不若沽之易","遇到取巧的捷径，我常问自己：窃之，不若沽之易，何不光明正大地买下来？"],"tags":["狐","机智","少年"]},"liaozhai_lupan":{"intro":"朱尔旦夜负陆判官塑像回家饮酒，结为酒友。陆判为他换心，使他文思大进；又为他妻子换上美女头，成了一桩奇案。这里选两处：换心考中、佩刀遗训。前者写“友”的奇事，后者写“父”的哀情，其中“胆欲大而心欲小，智欲圆而行欲方”是全篇的人格准则。","focus":["换心一段写得很平淡：“忽醉梦中，觉脏腑微痛……陆危坐床前，破腔出肠胃，条条整理。”朱惊问“夙无仇怨，何以见杀”，陆笑说“勿惧，我为君易慧心耳”。血腥的情节被写成亲切的家常，正因为他们是“友”。","陆判的判断不是神迹，而是批改：“朱献窗稿，陆辄红勒之，都言不佳。”换心之后“文思大进，过眼不忘”，陆又说“君福薄，不能大显贵，乡科而已”，并预言“今岁必魁”。这使“异术”回到科举的常规：天赋可换，福分不可换。","刀上的铭文“胆欲大而心欲小，智欲圆而行欲方”是全篇的价值：既要有魄力，又要有谨慎，既要机变，又要正直。这几句话本身就可作为管理者的座右铭，也是异史氏最后所欣慕的“执鞭”的理由。"],"notes":[["脏腑","内脏"],["慧心","聪明的心"],["毛窍","毛孔，喻灵性通路"],["羽葆","用羽毛装饰的仪仗伞盖"],["经元","乡试经魁第一名"],["乡科","乡试，举人的功名"],["司马","明清对兵部官员的称呼"],["行人","明清官职，掌传旨、册封等事"],["卤簿","帝王或高官出行的仪仗"],["镌","雕刻"]],"think":["陆判给朱尔旦换了心，朱却“福薄”。这说明作者在科举与天赋之间怎么看？","天赋可换，运数不可换：换心让文章进步，却不改命。作者既承认才学与考试成绩有关，也承认“命”的作用。这种混合的看法，正是科举时代读书人的自我宽慰。边界是：它并非主张努力无用，而是提醒功名不全由才定。"],"quiz":[["陆判为朱尔旦换心的理由是？",["朱作文不快，是毛窍塞","朱要求换心","朱病重"],"陆说“作文不快，知君之毛窍塞耳”，便换了一颗好心。"],["陆判预言朱的前途是？",["今岁必魁，但只止于乡科","一定中状元","永远不能考中"],"“君福薄，不能大显贵，乡科而已”，“今岁必魁”。"],["佩刀上刻的是什么？",["胆欲大而心欲小，智欲圆而行欲方","忠孝节义","为官清正"],"原文“镌字一行，曰：胆欲大而心欲小，智欲圆而行欲方”。"]],"cards":[["《陆判》里陆判官与朱尔旦关系是？","由夜背神像起结成的酒友，后换心换头。"],["佩刀上的铭文强调什么？","胆大心细，智圆行方，做事兼顾魄力与谨慎。"]],"line":["胆欲大而心欲小，智欲圆而行欲方","做新业务，我常把这句抄在白板上：胆欲大而心欲小，智欲圆而行欲方。"],"tags":["人鬼友情","科举","格言"]},"liaozhai_yingning":{"intro":"王子服爱上一个“笑容可掬”的女郎，追到深山，发现她是狐女婴宁，爱笑不止。后来她因一次恶作剧引出命案，从此不再笑，也说出自己的身世。这里选两段：园中的相见与收尾。第一段写“笑”和“痴”，第二段写“笑”的消失与哭，一个“隐于笑者”的形象由此立起来。","focus":["园中一场极有情趣：婴宁在树上“视生狂笑欲坠”，生说“勿尔，坠矣”，她“且下且笑，不能自止，方将及地，失手而坠，笑乃止”。笑从头到尾都不是装的，是她的本性。王生借机示爱：“我非爱花，爱捻花人耳。”","最妙的对白是“夫妻之爱”的定义：王生说“夜共枕席耳”，婴宁答“我不惯与生人睡”，回头对母亲坦然说“大哥欲我共寝”，王生“大窘，急目瞪之”。她不懂礼教的暗区，所以天真；而天真正是她最大的魅力。","异史氏的话是对全篇的解读：“观其孜孜憨笑，似全无心肝者，而墙下恶作剧，其黠孰甚焉。至凄恋鬼母，反笑为哭，我婴宁殆隐于笑者矣。”所以她不是傻，是把心藏在笑里。后面那句“若解语花，正嫌其作态耳”，则是对“做作美人”的反讽。"],"notes":[["细事","小事"],["葭莩之情","亲戚间的淡薄情谊，葭莩是芦苇里的薄膜"],["婢","侍女"],["瓜葛","亲戚关系"],["零涕","落泪"],["合厝","合葬"],["寒食","清明前一两日的节令，扫墓"],["憨笑","天真地笑"],["解语花","会说话的花，喻聪明的美人"],["作态","故意做出某种姿态"]],"think":["婴宁的笑到底是“憨”，还是“黠”？异史氏为什么说她“隐于笑”？","两者并存：她对世俗礼法天然不懂，所以笑得无遮拦；在西邻之事里又显出机巧，所以说“其黠孰甚”。“隐于笑”是说，她把真实的情感藏在笑里，到丧母之痛时才流露。边界是：这是异史氏的读法，不一定穷尽人物。"],"quiz":[["王子服对婴宁的“爱”是怎样表白的？",["“我非爱花，爱捻花人耳”","“愿结为兄妹”","“愿娶你为妻”"],"他说“我非爱花，爱捻花人耳”，又解释“非瓜葛之爱，乃夫妻之爱”。"],["婴宁最终为何不笑？",["因邻子之祸受责，矢不复笑","丈夫禁止","身体不适"],"母亲责备，她“正色，矢不复笑”。"],["异史氏用什么词概括婴宁？",["隐于笑者","解语花","无心肝者"],"原文“我婴宁殆隐于笑者矣”。"]],"cards":[["婴宁的身世？","狐女，由鬼母（秦氏）抚养。"],["“解语花”在文中的态度？","异史氏嫌这种做作的美人，反衬婴宁的本真。"]],"line":["我非爱花，爱撚花人耳","他说他喜欢这个产品，其实是我非爱花，爱撚花人耳，爱的是背后做产品的那个团队。"],"tags":["狐女","笑","人物"]},"liaozhai_niexiaoqian":{"intro":"宁采臣寄宿荒寺，先拒了女鬼聂小倩送上门的黄金，后又答应替她迁葬，最终把她带回家，成了妻子。这里选两段：小倩夜里自述身世并求救，以及她成为家人之后与妖物交战。前半写“信”，后半写“囊”，一个靠人的刚直，一个靠剑客的法器，合起来就是一个完整的守约故事。","focus":["小倩开口的第一句是“妾阅人多矣，未有刚肠如君者”，说明她的夜访是职务，不是情愿；“役贱务，觍颜向人，实非所乐”一句自白，让她从鬼魅变成受胁迫的人。宁采臣拒金一事因此显得重：他拒的不是美色，而是一个被逼的女子递来的“罗刹鬼骨”。","她提出的请求克制而具体：“倘肯囊妾朽骨，归葬安宅，不啻再造”，还补一句辨认标记“白杨之上，有乌巢者是也”。不求报仇、不求成人，只求一块安葬之地，鬼的愿望写得比人的更朴素。","后一段写小倩婚后惧怕革囊，却要求悬挂床头：“妾受生气已久，当不复畏”，说明她已被家人接纳。夜叉扑来时，革囊“格然一响，恍惚有鬼物突出半身，揪夜叉入”，“清水数斗而已”。打斗只写结果，不写过程，留白处很多。"],"notes":[["夭殂","早死"],["狎昵","亲近戏狎"],["罗刹","凶恶的鬼"],["义气干云","义气高到云天"],["囊妾朽骨","把我的枯骨装起来带走"],["怊怅","失意惆怅"],["怔忡","心悸不安"],["革囊","皮囊，这里指燕赤霞所赠的剑袋"],["夜叉","凶恶的鬼神"],["肌犹栗悚","皮肤仍然战栗"]],"think":["宁采臣拒金、救骨，却不让小倩入家门当晚留宿。你怎么看他的分寸？","他始终守着“非义之物”“别榻”的底线：拒金是不取不义之财，救骨是行义，不留宿是不乱礼，三者各守其位。他的刚直不是不近人情，而是先立规矩，再给人情。边界是这类分寸在今天的职场也适用：帮忙与越界之间需要先划线。"],"quiz":[["小倩为什么劝宁采臣与燕赤霞同室？",["燕生是奇人，妖物不敢近","燕生是她的亲人","燕生会驱鬼"],"她说“彼奇人也，不敢近”，同室可免。"],["小倩求宁采臣做什么？",["把她的尸骨带回家安葬","替她报仇","超度她"],"“倘肯囊妾朽骨，归葬安宅”，并说明墓上有白杨、乌巢。"],["革囊最后的结果是？",["收了夜叉，囊中只剩清水数斗","被夜叉撕裂","毫无反应"],"原文“囊亦顿缩如故”，“共视囊中，清水数斗而已”。"]],"cards":[["聂小倩为何被迫害人？","受妖物威胁，要做“贱务”，勾引男子供妖饮血。"],["革囊是谁给的？","剑客燕赤霞，赠给宁采臣防魑魅。"]],"line":["义气干云，必能拔生救苦","她在困境里认定对方义气干云，必能拔生救苦，所以敢于托付。我们找人合作，也要先看他守不守约。"],"tags":["鬼","信义","剑侠"]},"liaozhai_shuimangcao":{"intro":"水莽草是毒草，误食者成鬼，要找替身才能投生。祝生贪看茶摊少女，喝了她的茶而死，死后反而强把寇三娘留作妻子，又因“深恨此等辈”而不肯找替身，最后封为龙君。故事写鬼不凶，写人情很细，从怨到爱、从爱到德，是一条人鬼关系的弧线。","focus":["祝生之死由一个小动作引起：“戏捉纤腕，脱指环一枚。”少女“颊微笑”，他“益惑”。作者没有谴责他，只写轻浮、好奇与一杯茶，让读者意识到祸事其实从一个玩笑开始，却不能挽回。","他死后“强捉”三娘为妻，写得很不浪漫，反而真实：“寇氏坐听儿死，儿甚恨之。”但随即三娘“承顺殊怜人”，操作炊爨，寇家也送来金帛。怨恨被日常琐碎磨平，作者写出的是人情如何把阴阳之别化开。","收尾尤重：祝生不肯“取人以自代”，反而“方将尽驱除之”，中毒者向他祷告，“辄有效”。他由恶鬼变成保护神，是因为他懂得被害的滋味，这是“以怨报怨”的反面。最后上帝策为龙君，夫妻同去，三娘的骸骨“与生合葬”。"],"notes":[["水莽","一种有毒的蔓草"],["同年","同年出生者互称，这里指楚地的习俗"],["庚兄","同庚者之间的称呼"],["水莽鬼","误食水莽草而死的鬼"],["故裆","旧时穿过的贴身衣裤"],["改醮","再嫁"],["柏舟节","守节，典出《柏舟》"],["拳拳","诚恳深切"],["舁","抬"],["四渎","长江、黄河、淮水、济水"]],"think":["祝生死后“强捉”寇三娘为妻，后来又不肯找人替死。你怎样看这两件事的关系？","一件是怨，一件是德。前者是恨意的发泄，后者是恨意的升华：他懂得被害的痛，因而不愿把痛转嫁。边界是文中没有为“强捉”开脱，仍是任性，只是后来用善行补回。"],"quiz":[["祝生是怎样遇害的？",["喝了少女递的茶，茶里有水莽草","被人推入水中","吃了毒果"],"他嗅茶有异味，但少女再进一杯，他“吸尽再索”，才中毒。"],["他死后为何强捉寇三娘？",["怨她见死不救，也为投生","爱慕她","受命于阎王"],"“寇氏坐听儿死，儿甚恨之”，故驱鬼寻她。"],["后来他为什么封为龙君？",["有功人世，不取人替代","生前是官","因孝顺母亲"],"“上帝以我有功人世，策为四渎牧龙君”，他曾救中毒者，又不肯寻替。"]],"cards":[["水莽鬼靠什么投生？","找人毒死作替身。"],["祝生如何积德？","驱鬼救中毒者，不肯取人自代。"]],"line":["儿深恨此等辈，方将尽驱除之","我吃过某类合同的亏，所以现在对那类合同是儿深恨此等辈，方将尽驱除之，不让别人再踩。"],"tags":["鬼","报恩","民俗"]},"liaozhai_xianv":{"intro":"顾生家贫孝母，对门来了一对母女，女儿冷若冰霜，却暗中救济顾家，与他私合，又为他生子，最后提着仇人的头告别。这里选其中两段：杀妖狐与诀别。顾生始终是个被人照顾的人，侠女的言行则始终围绕“报恩”和“复仇”两件事展开，她的冷，是因为她有事在身。","focus":["杀狐一场，侠女一直不动声色：少年闯入，笑说“我来观贞节之人耳”，她“眉竖颊红，默不一语，急翻上衣，露一革囊”，“尺许晶莹匕首”一出，白狐“身首异处”。她给的解释只有一句：“我固恕之，奈渠定不欲生何！”语气几乎没有杀人的情绪。","她对顾生说过两句要紧话：“事可一而不可再”“枕席焉，提汲焉，非妇伊何也？”前者是界线，后者是承诺。她为顾家绵延后嗣，先立界线，再不顾礼法，这是侠者的方式：该做的做完，不求名分。","告别一段的信息密度最高：“养母之德，刻刻不去于怀……相报不在床第也”“仇人头耳”“妾浙人，父官司马，陷于仇”。三年隐姓埋名，有母在不报仇，母去后又“一块肉累腹中”，所以“迟之又久”。她的冷来自这样的负担，到这里才明白。"],"notes":[["娈童","男宠"],["革囊","皮囊"],["匕首","短剑"],["天数","天意，命数"],["戛然","形容声音清脆短促"],["晶莹","光亮透明"],["信水","月经，旧称信水"],["机事不密","大事不隐秘，语出《易经》"],["埋头项","隐姓埋名躲避"],["司马","明清对兵部官员的称呼"]],"think":["侠女对顾生“可一而不可再”，却又在生子之后“破戒而再”。你怎样理解这一矛盾？","她给出的解释是“本期一索而得，不图信水复来”，是为了生子报答养母，而非情欲。边界是：作者通过她的“破戒”表现出恩义有时高于自我约束，同时也让她的冷有了人情。"],"quiz":[["侠女杀白狐的理由是？",["他定要作恶，不欲生","他是妖","他冒犯了顾生"],"“我固恕之，奈渠定不欲生何”，他屡次骚扰又要揭发。"],["她为什么要为顾生生子？",["报养母之德，延顾家后嗣","爱上顾生","遵守师命"],"“为君贫不能婚，将为延一线之续”，相报不在床第。"],["她离去时提的是？",["仇人头","一包金银","孩子"],"“仇人头耳”，她是浙人，父亲官司马，陷于仇家。"]],"cards":[["侠女为何迟迟不报仇？","有母在不敢；母去又怀孕，“迟之又久”。"],["“事可一而不可再”什么意思？","一次就要点到为止，不能反复私会。"]],"line":["为君贫不能婚，将为延一线之续","她对我说得很清楚：为君贫不能婚，将为延一线之续，感情之外还有另一份责任。"],"tags":["侠女","报恩","复仇"]},"liaozhai_lianxiang":{"intro":"桑生遇狐女莲香与鬼女李氏，两人同时爱他。李氏是鬼，夜夜亲近，使他“日渐羸瘠”；莲香是狐，反而来救他，再把李氏逼到墙角，最后用药和口唾把桑生救回。这一段是全篇最关键的冲突：谁是真正害人者？作者把狐与鬼的善恶倒了过来，说“世有不害人之狐，断无不害人之鬼”。","focus":["莲香上场时说的话直接把“狐比鬼好”摆明：“妾李通判女，早夭，瘗于墙外。”李氏自陈，莲香笑问：“闻鬼物利人死，以死后可常聚，然否？”李答“两鬼相逢，并无乐趣”。对话的功夫在于把一个本来对立的二人，拉到同一个“救他”的位置上。","莲香的处置带着戏谑与老练：“恐郎强健，醋娘子要食杨梅也”，让李氏“接口而唾之”，凡三四唾，丸下咽，又“自接唇而布以气”。这是古人对“口中津液”入药的一种想象，写得怪而有情，没有色情意味，是救命的仪式。","最后的收束是“莲听鸡鸣，李徬徨别去”：李氏仍然离去，不是被驱，是被说服后自愿让位。后来她还魂为燕儿，莲香死后化狐，十年后再世——这篇的“妒”与“爱”不是互相敌对，而是相互成全。"],"notes":[["通判","州府的佐官"],["瘗","埋葬"],["采补","旧说中靠吸取他人精气的邪术"],["醋娘子","爱吃醋的女子"],["杨梅","酸果，戏指吃醋"],["接口","嘴对嘴"],["瘵蛊","痨病之类的蛊毒"],["敛衽","整理衣襟，表示恭敬"],["丹田","脐下一寸三分，道家气功所指的要处"],["徬徨","犹豫不安"]],"think":["莲香说“世有不害人之狐，断无不害人之鬼”，你认为这句话要说明什么？","按她的解释，鬼属阴，会损人之阳，所以本性上是害人的；狐有“采补者流”，但也有正派。作者想用这句话改写读者对狐的偏见，同时让读者对“表面温柔的鬼”提高警惕。边界是这是故事里的“学说”，不是普遍判断。"],"quiz":[["莲香与李氏的关系，最贴切的描述是？",["先对立，后互相成全","始终敌对","互不相识"],"莲香戳破李氏的身份，又救桑生，最后两人如姊妹；李氏还魂后还送走莲香。"],["莲香说“世有不害人之狐，断无不害人之鬼”理由是？",["鬼阴气盛，会损人","鬼更凶恶","狐比鬼更修行"],"“以阴气盛也”。"],["莲香为什么要李氏“接口而唾”？",["李氏是起病之因，要借她的津液引药","要羞辱她","要赶走她"],"“症何由得，仍以何引，不得不转求效力”。"]],"cards":[["《莲香》里谁是狐，谁是鬼？","莲香是狐，李氏是鬼。"],["“醋娘子要食杨梅”什么意思？","打趣李氏爱吃醋。"]],"line":["世有不害人之狐，断无不害人之鬼","面对新来的“很会说话”的合作方，我总想起一句：世有不害人之狐，断无不害人之鬼，不能以第一印象下判断。"],"tags":["狐","鬼","情"]},"liaozhai_abao":{"intro":"孙子楚“痴”得出名，听说富家女阿宝一句戏言，竟用斧头砍掉枝指；清明路遇一次，魂随她而去；又化为鹦鹉，咬走她的绣履；终于结为夫妻。这里选两段：魂随与鹦鹉。前者写“痴”如何成魂，后者写“痴”如何成形，最后异史氏把“痴”提到“志凝”的高度。","focus":["魂随一段完全不写孙生的动作，只写“魂”的行止：“渐傍其衿带间，人无呵者，遂从女归，坐卧依之，夜辄与狎。”魂不受限制，说明他的执念，连身体的存在都不需要。结尾“巫执故服草荐以往”，阿宝“惊极”，作者借第三者的“验证”让此事可信。","鹦鹉一段充满趣味：“姐姐勿锁，我孙子楚也。”这句话由一只鸟说出，既荒唐又深情。阿宝“祝曰：深情已篆中心。今已人禽异类，姻好何可复圆？”她承认了感情，也点出了障碍；孙生仍答“得近芳泽，于愿已足”，把爱写成一种不求回报的守候。","转折靠一只绣履：阿宝一脱履，鹦鹉“衔履飞去”，回家后孙生索履。履成了“信誓物”，逼得阿宝“矢不他”，“翁媪乃从之”。小物件把魂、鸟、人的三层关系收成一个现实承诺，这是《聊斋》写情很会用的“信物”。"],"notes":[["衿带","衣襟与衣带"],["招魂","民间为病人叫魂的仪式"],["草荐","草垫"],["香匳什具","梳妆匣与器物"],["鹦鹉","会学人话的鸟"],["篆中心","刻在心里"],["人禽异类","人与鸟不同类"],["芳泽","香气，指所爱之人的亲近"],["信誓物","作为誓约凭证的东西"],["金诺","重诺言"]],"think":["阿宝对“痴”的态度从戏弄转为敬重。你认为是什么使她改变？","是孙生的代价：断指、魂随、化鸟，每一步都不是表演，而是实实在在的牺牲。她起初当玩笑，后来被“深情已篆中心”击中。边界是：蒲松龄让“痴”获得回报，同时也让读者看到对此人的不对等。"],"quiz":[["阿宝最初提出的条件是？",["去掉枝指（后又说去掉痴）","送上聘礼","参加科举"],"她戏说“渠去其枝指，余当归之”，生便以斧断指。"],["鹦鹉带走了什么作为信物？",["阿宝的绣履","一条丝帕","一枚戒指"],"“女束双弯，解履床上，鹦鹉骤下，衔履飞去”。"],["阿宝之母的顾虑是？",["孙生才名不坏，但有相如之贫","孙生是外地人","年纪太大"],"母曰：“此子才名亦不恶，但有相如之贫。”"]],"cards":[["孙子楚以什么方式接近阿宝？","魂随、化为鹦鹉。"],["“信誓物”指什么？","阿宝的绣履。"]],"line":["深情已篆中心","他认真做一件事的时候，深情已篆中心，别人再怎么劝也没用。"],"tags":["痴情","魂","信物"]},"liaozhai_kouji":{"intro":"一个村妇卖药，诊病时说要“夜问诸神”，闭在斗室里，门外人只听见里面三姑六姑来去、婢女寒暄、小儿啼笑。其实她一人包办全部声音，是“口技”，借此售药。这篇很短，却有两层：写声音的功夫，以及蒲松龄的冷静结论“试其方，亦不甚效”。","focus":["声音层次是篇的主体：先是“九姑来耶？”“腊梅从九姑来耶？”，再有“六姑至矣”“春梅亦抱小郎子来”，每次都由女子先开口、对方应答。这种“点名式”设计，让门外人不用看就知道进了几人。","细节全靠声：“拗哥子！呜呜不睡，定要从娘子来。身如百钧重，负累煞人！”一句说出小郎、婢女的关系；“小郎君亦大好耍，远迢迢抱猫儿来”，再加一只猫。作者让每个角色都有一个“特征”，听者因此信以为真。","收尾有两个转折：一是“群讶以为真神，而试其方，亦不甚效”，揭穿其用意；二是附记“王心逸言”，一个少年以一指捺颊，“与弦索无异”，也是口技。蒲松龄不夸神奇，只说“亦奇矣”，写的是民间艺人的真本事。"],"notes":[["斗室","狭小的房间"],["絮语","连续低声说话"],["嘈杂","混杂喧闹"],["拗哥子","执拗的小孩"],["温凉","问候寒暖"],["参酌","斟酌商量"],["苏苏然","撮药时的细碎声"],["了了","清楚明白"],["市廛","市中商铺"],["曼声度曲","拖长声音唱曲"]],"think":["作者说此技“特借之以售其术”，你怎么评价这种“包装”？","这是一种营销：借神秘包装给药方增值，但药不效，说明包装不能替代实质。边界是：作者没有批判，只是平实地写“亦奇矣”，因为技艺的真实与药的虚假可以并存。"],"quiz":[["门外人为什么相信是神？",["听到多人来去、对话，各有声态","看到神像","药很灵验"],"“九姑之声清以越，六姑之声缓以苍，四姑之声娇以婉”，各有态响。"],["最后药方的效果是？",["不甚效","立竿见影","毫无作用"],"“试其方，亦不甚效”。"],["附记王心逸所见的口技是？",["不用乐器，以一指捺颊且捺且谣","用笛子模仿鸟声","借水碗发声"],"“并无乐器，惟以一指捺颊际”。"]],"cards":[["《口技》靠什么让人信服？","一个人用声音塑造多个角色的来去与对话。"],["作者对这个女子的评价？","口技很奇，药方不效，不过是借技售术。"]],"line":["此即所谓口技，特借之以售其术耳","这家公司靠一场发布会把产品炒得很热，其实是此即所谓口技，特借之以售其术耳。"],"tags":["技艺","民间","声音"]},"liaozhai_hongyu":{"intro":"冯相如与狐女红玉相爱被父亲拆散，红玉出资为他另娶，后来邑绅宋氏强夺其妻，打死老父，冯家几乎家破人亡。一个陌生的虬髯客杀了宋家，却在县令床上留下一把“剁床入木”的刀。数年后红玉带着孩子回来，白手重建家业。这里选刀入木与再造两段，一冷一暖。","focus":["夜里杀人写得简洁：“有人越重垣入，杀御史父子三人，及一媳一婢。”不写凶手是谁，也不写过程。接着县令被一把“短刀银利如霜，剁床入木者寸余，牢不可拔”吓得魂飞魄散，随即代生开脱。把义侠的刀当作官场的“判决”，既荒诞，又痛快。","冯相如的下场是在这一段之前的苦：“生惧祸及，抱子亡去”，被官差“系缧而行”，县令说“杀汝子，何怨？”。作者借县令一句话写出官场的冷漠：他对“杀人”有判断，对“冤”无兴趣，直到刀入木，才有“恐惧”这个逻辑。","红玉重来时的第一句是“大冤昭雪，可幸无恙？”随后“剪莽拥篲，类男子操作”，“租田数十亩，雇佣耕作”，半年“类素封家”。她还说“妾前以四金寄广文，已复名在案”，可见早有算计。侠情之外，更有理家之智。"],"notes":[["重垣","层层院墙"],["系缧","用绳索拘系"],["褫革","革除功名"],["梏","刑具，指枷锁"],["短刀","短刃"],["荷戈","持兵器"],["详诸宪","向上级申报"],["下帷","闭门读书"],["素封","有钱而无官爵"],["广文","对县学教官的称呼"]],"think":["县令因一把刀入木而“代生解免”。你怎样看这种“被吓出来的公正”？","这是对官场的讽刺：公正不是由制度保证，而是靠恐惧。异史氏的话更直白——“何惜不略移床上半尺许哉”，他希望刀再准一点。边界是：这是对现实司法失灵的愤怒，而不是对侠客暴力的提倡。"],"quiz":[["县令为何释放冯生？",["夜里被刀钉入床上，吓破胆","查明真凶","上级命令"],"“短刀银利如霜，剁床入木者寸余”，令“魂魄丧失”，此后“代生解免”。"],["红玉来归时带回了？",["冯生的儿子福儿","一份诉状","一大笔金银"],"她说“见儿啼谷中，抱养于秦”。"],["红玉怎样助冯生复学籍？",["以四金寄广文","找旧友说情","请求县令"],"“妾前以四金寄广文，已复名在案”。"]],"cards":[["红玉的真实身份？","狐女，之前自称邻女。"],["“剁床入木”的作用？","吓退县令，使冯生得释。"]],"line":["灰烬之余，卿白手再造矣","再大的挫折也有重来的一天，我对团队说：灰烬之余，白手再造，也不是不可能。"],"tags":["狐","复仇","官场"]},"liaozhai_linsiniang":{"intro":"青州道陈宝钥夜里遇一个“长袖宫装”的女子，自称林四娘，实为衡王府宫人，十七年前殉难。两人往来三年，她唱亡国之音，诵经咒，评诗词，最后“慨然而歌”告别。这篇没有曲折情节，重在气氛：一个女鬼的忧伤背后，是一个王府的覆灭。","focus":["女子出场就带着旧朝的痕迹：“长袖宫装”。陈公问她为何哀婉，她答“声以宣意，哀者不能使乐，亦犹乐者不能使哀”。对音乐的理解，说明她是受过训练的宫人，而不是普通女鬼。","家人偷听“无不流涕”，是篇中最打动人处：不需要知道歌词，听到曲调就哭。作者借此写“亡国之音”的感染力，也避开了对政治细节的直接评论。","诗里有“静锁深宫十七年，谁将故国问青天”“红颜力弱难为厉，惠质心悲只问禅”，她不能报仇，只能求超度。篇末作者补一句“诗中重复脱节，疑传者错误”，承认文本的缺漏，也是对史料的一种诚实。"],"notes":[["衡府","衡王府，明代分封的藩王府"],["宫商","古代五音，泛指音律"],["伊凉","唐代边塞乐曲名"],["亡国之音","哀伤的乐曲"],["式微","衰落，指王府败落"],["九原","黄泉，指阴间"],["准提","佛教的准提咒"],["评骘","评议"],["梨园","戏班"],["贝叶","佛经"]],"think":["林四娘说“红颜力弱难为厉”，这一句在诗里意味着什么？","她表示自己无力化为厉鬼复仇，只能选择念经求来世。这既是性格，也是处境：女子、宫人、亡国之后，所有反抗的可能都被削尽。边界是：她并未说不愿，只是“力弱”，所以哀。"],"quiz":[["林四娘自称是什么人？",["衡王府宫人","官宦千金","民间歌妓"],"她说“妾衡府宫人也，遭难而死，十七年矣”。"],["她每夜做什么？",["起诵准提金刚诸经咒","弹琴","读诗"],"“女不甚睡，每夜，辄起诵准提金刚诸经咒”。"],["她为什么与陈公永别？",["冥王让她生王家，不再见","陈公调任","她被驱逐"],"“冥王以妾生前无罪，犹不忘经咒，俾生王家”。"]],"cards":[["林四娘是谁？","衡王府宫人，亡国后化鬼。"],["她的诗末二句？","“高唱梨园歌代哭，请君独听亦潸然。”"]],"line":["哀者不能使乐，亦犹乐者不能使哀","情绪由内而发，哀者不能使乐，亦犹乐者不能使哀，你很难指望强颜欢笑的演讲打动人。"],"tags":["鬼","亡国","诗"]},"liaozhai_liboyan":{"intro":"李伯言“抗直有肝胆”，被阴司请去暂摄阎罗，三天里审了两个案：一个是奸淫八十二名良家女的江南人，被判炮烙；一个是占买被拐婢女的王某，因为他是李的亲家，李心里偏向，大殿上就“火生”。短篇的重点是后者：只有“一念之私”，火就烧起来，必须“急消他念，则火自熄”。","focus":["炮烙一段写得惊心动魄：“铜柱，高八九尺……空其中而炽炭焉”，群鬼“以铁蒺藜挞驱使登”，“三堕，则匝地如烟而散，不复能成形矣”。刑罚的恐怖不在痛，而在“不复能成形”，是彻底的消灭。","关键的转折在“火生”：“李见王隐存左袒意，忽见殿上火生，燄烧梁栋”。吏人提醒：“阴曹不与人世等，一念之私不可容。”想念一偏，殿火即起，公正被写成具有物理后果的东西。","异史氏说“阴司之刑，惨于阳世，责亦苛于阳世，然关说不行，则受残酷者不怨也”，批评的是人间官场的“关说”（走后门）。末句“第恨无火烧临民之堂廨耳”最锋利：他希望阳间衙门也有这样的火。"],"notes":[["暂摄其篆","暂时代理其职务"],["驺从","贵人出行时前后的随从"],["炮烙","古代酷刑，使人登烧红的铜柱"],["铁蒺藜","带刺的铁刑具"],["左袒","偏袒"],["关说","私下说情"],["路引","通行证"],["道场","僧道作法事的场所"],["夜台","坟墓，指阴间"],["堂廨","官署"]],"think":["“一念之私不可容”在今天的组织里有什么对应？","对应利益冲突申报制度：当事人如果与案件有关，要回避。这篇用“火”形象化了这条制度，说明即使没有行动，仅仅存在偏心，也要处理。边界是：这是对理想司法的想象，现实中制度比“火”更靠不住。"],"quiz":[["李伯言在阴司遇到的“火”是怎么回事？",["他心里偏袒亲家，殿上起火","地狱之火蔓延","鬼差纵火"],"“李见王隐存左袒意，忽见殿上火生……急消他念，则火自熄”。"],["江南某被判什么刑？",["炮烙","斩首","发配"],"“按冥律，宜炮烙”。"],["异史氏最后的遗憾是？",["人间官府没有这样的火","阴司刑罚太重","李伯言还阳太早"],"“第恨无火烧临民之堂廨耳”。"]],"cards":[["“一念之私不可容”出自何篇？","《李伯言》，阴司吏提醒李伯言。"],["炮烙之刑是什么？","让人登上烧红的铜柱，三堕后化烟而散。"]],"line":["阴曹不与人世等，一念之私不可容","在评审会上，我先申明和对方有合作，是因为阴曹不与人世等，一念之私不可容。"],"tags":["阴司","公正","官场"]},"liaozhai_liancheng":{"intro":"乔生因一首诗被史家小姐连城引为知己，为救她割下胸肉，史家却悔婚；他后来一笑而死，随连城入阴间，又因赏识的同乡顾生之助，带她还魂。这里选两段：割肉之后的“知己”之论，和阴间还魂的情节。篇的中心句是“士为知己者死，不以色也”，把爱情写成知己之感。","focus":["乔生拒收千金，说“仆所以不爱膺肉者，聊以报知己耳，岂货肉哉”。他把割肉看作情义，而不是交易。连城听说后，托媪慰谕，说“天下何患无佳人”，他答“‘士为知己者死’，不以色也。诚恐连城未必真知我”，求的是对方的“知”，而不是对方的人。","后来相遇，连城“秋波转顾，启齿嫣然”，乔生“大喜曰：连城真知我者”。仅仅一笑，他便心满意足，等到连城病死，他“一痛而绝”。异史氏说“一笑之知，许之以身”，是对这种情的高度概括。","阴间的部分把情感的主线收成行动：连城说“如此负义人，尚不吐弃之，身殉何为”，乔生答“卿死，仆何敢生”。顾生出手相助，又带来同行的宾娘，使一段本是二人的故事，加入第二位女子的命运，显出这个世界对“知己”的另一种等待。"],"notes":[["泉下物","指死后去处，代指连城的未来"],["知己","懂得自己的人"],["愆尤","罪过，过失"],["媪","老妇人"],["秋波","女子的眼波"],["嫣然","美好地笑"],["廨署","官署"],["平章","商量处理"],["返魂","还魂"],["宛转","缠绵悲切的样子"]],"think":["乔生说“不以色也”，却在连城一笑后欣喜若狂。这两者矛盾吗？","不矛盾。他要的是被理解的确证，而一笑恰是“知我”的信号。边界是：作者并未否定对美的向往，只是强调“知”才是底色，“色”只是外化。"],"quiz":[["乔生拒绝千金的理由是？",["割肉是报知己，不是卖肉","钱太少","史家悔婚"],"“岂货肉哉”。"],["连城所说“不以色也”指什么？",["乔生认为知己之情不是因容貌","她不美","她不愿嫁"],"这是乔生的话：“‘士为知己者死’，不以色也。”"],["顾生在阴间帮了什么忙？",["安排连城、宾娘随乔生还魂","送金银","说服阎王"],"“我为君平章已确，即教小娘子从君返魂”，后又愿代担责任带上宾娘。"]],"cards":[["《连城》异史氏说“一笑之知”的意思？","因对方的一笑相知，便愿以身相许。"],["连城为什么曾被拒？","史父嫌乔生贫，后又背盟。"]],"line":["诚恐连城未必真知我，但得真知我，不谐何害","我宁可被一个人真正理解，也不想被很多人赞赏，诚恐连城未必真知我，但得真知我，不谐何害。"],"tags":["知己","爱情","还魂"]},"liaozhai_shangsanguan":{"intro":"商士禹被邑豪打死，诉讼多年不得直，女儿三官劝兄长埋葬父亲，自己却连夜出走。半年后，邑豪家过生日，一个叫李玉的“男孩”被留宿，夜里主人身首异处，李玉自缢，人们才发现是女扮男装的三官。篇幅仅七百字，节奏如快刀。","focus":["三官在前半只有两句话：先拒婚家“焉有父尸未寒而行吉礼”，再对兄说“人被杀而不理，时事可知矣。天将为汝兄弟专生一阎罗包老耶”。她看清的不是家事，而是官场不会替人申冤，所以她的复仇不是情绪，而是对制度的失望。","刺杀的方法写得冷静：“玉往来给奉，善觑主人意向。豪悦之。”借歌伶的身份靠近，再“阖扉下楗”，先杀人再自缢。她没有想活着走出去，“绳断堕地”的细节更说明她算好了结局。","收尾“女貌如生，抚之，肢体温软。二人窃谋淫之”，一人“脑如物击，口血暴注，顷刻已死”，众人“敬若神明”。作者让死者仍有尊严，也让官府“判二兄领葬，敕豪家勿仇”，一句话收住，使复仇获得官方的默认。"],"notes":[["醉谑","酒后戏谑"],["吉礼","婚礼"],["阎罗包老","阎罗王包公，指铁面无私的包拯"],["怍","惭愧"],["优人","艺人"],["参母","拜见母亲"],["行觞","行酒，劝酒"],["下楗","上闩"],["素舄","白鞋，为父服孝"],["女豫让","女刺客，豫让是战国刺客"]],"think":["三官劝兄“乃葬父”，而自己则暗中行动。她为什么不让兄长参与？","一来兄长已败诉，信不过官府的结果；二来她作为女子，更易接近仇人而不被怀疑；三来不牵连家人。边界是：文中只写她的决定，没有说出理由，上述是依据情节作的合理推断。"],"quiz":[["三官出走的原因是？",["要独自复仇","逃婚","投亲"],"“三官夜遁，不知所往”，后来在豪家杀人。"],["李玉的真实身份？",["商三官扮男装","商家刺客","孙淳之弟"],"“解之，则素舄如钩，盖女子也”。"],["异史氏称她为？",["女豫让","女包公","女侠客"],"“家有女豫让而不知”。"]],"cards":[["商三官如何接近仇人？","扮作男优伶，借行酒讨好邑豪，夜里杀之。"],["她的白鞋说明了什么？","她仍在为父服丧。"]],"line":["人被杀而不理，时事可知矣","遇到长期不处理的投诉，我常感叹：人被杀而不理，时事可知矣，要有人对结果负责。"],"tags":["复仇","女子","官场"]},"liaozhai_leicao":{"intro":"乐云鹤弃文经商，在金陵旅舍遇到一个饥饿的巨人，请他吃了几顿饭，后来这人救他出海难、带他上天、教他看云雷，最后说破自己是雷曹，因误行雨被罚谪三年。一饭之恩，换来一次“云中游”。篇尾“少微星”转世的传说，是对“友”的最高褒奖。","focus":["乐云鹤的善心很具体：“乐推食食之；则以手掬啗，顷刻已尽。”再添一份又尽，“遂命主人割豚肩，堆以蒸饼，又尽数人之餐”。作者不写他的动机，只写递食物的动作，因此更真。","水中救援写得有力：“其人负乐踏波出，登客舟，又破浪去；少时，挽一船至……两臂夹货出，掷舟中，数入数出，列货满舟。”这样的“神力”在文中并不玄虚，用在了实实在在的货物上，把神话写成商旅的脚程。","上天一段写星是“老莲实之在蓬”，大者“如瓮”，小者“如盎盂”，乐生摘下一颗袖中；“二龙夭矫，驾缦车”，群雷曹“以器掬水，遍洒云间”。乐生“约望故乡，尽情倾注”，所以“独乐里沟浍皆满”。恩情与故乡之爱相叠，是全篇最可爱的细节。"],"notes":[["同斋","同窗读书"],["规","劝告"],["兼人之馔","相当于两个人的饭量"],["饫饱","吃饱"],["婴","遭受"],["天谴","上天的惩罚"],["盎盂","盆钵，小器皿"],["缦车","没有彩饰的车"],["夭矫","屈伸有力的样子"],["少微星","星名，古人称处士星"]],"think":["雷曹说“君有大难，吾不忍忘一饭之德”。这种报恩的逻辑与今天有什么不同？","古代的报恩常以“不成比例”的方式出现：小恩换大难。它的价值在于“记得”而非等值。今天的商业讲究对等，但真正的长期关系仍依赖这种“多一点”的记忆。边界是：别把它当做期待回报的投资，那样就没有“恩”了。"],"quiz":[["乐云鹤为何弃文从商？",["科场失意，又要照顾夏平子的家","想发财","父命"],"他叹“文如平子，尚碌碌以没，而况于我”，“不如早自图也”。"],["雷曹的真实身份？",["因误行雨被谪三年的雷曹","龙王之子","仙人"],"他说“我本雷曹，前误行雨，罚谪三载”。"],["异史氏如何解释雷曹与少微星的报恩？",["造物公报贤豪","神人私报恩施","偶然"],"“岂神人之私报恩施哉，乃造物之公报贤豪耳。”"]],"cards":[["雷曹为何饿？","被罚谪人间三年，受苦。"],["乐云鹤摘下的星后来怎样？","进入妻子口中，后生子“星儿”。"]],"line":["君有大难，吾不忍忘一饭之德","我记得谁在最难的时候给过我一碗饭，君有大难，吾不忍忘一饭之德。"],"tags":["报恩","友情","奇想"]},"liaozhai_pianpian":{"intro":"罗子浮少年被娼妓引诱，沦为乞丐，满身烂疮，被山洞中的仙女翩翩收留，洗澡、做衣、生子，十数年过去，回家见叔父，所穿的蕉叶衣尽化为叶。这一篇少有悲剧，也少有劝善，只写一种近于家常的仙居生活：叶可作衣，云可作絮。异史氏的“何殊于人世”，把仙话压回到平凡。","focus":["洞中衣食写得极具体：“取大叶类芭蕉，剪缀作衣”，“山叶呼作饼，食之，果饼；又剪作鸡、鱼，烹之皆如真者”；“秋老风寒，霜零木脱”，女“收落叶，蓄旨御冬”，又“掇拾洞口白云，为絮复衣”。洞里的一切物资都来自自然，却也是一份居家的精打细算。","花城与翩翩的关系是篇中另一线索：花城“笑入”，一见罗子浮就显出对他的兴趣，罗生“阴捻翘凤”，衣服“悉成秋叶”。仙女的道德测验没有惩罚，只让他“渐颜息虑”，说明“欲”可止，不必打压。","结尾先写“子有俗骨，终非仙品；儿亦富贵中人”，所以翩翩让他们回家，自己留下。回家后“衣悉蕉叶，破之，絮蒸蒸腾去”，此后罗生再去只见“黄叶满径，洞口云迷”。仙境的消失用的是平常语，不夸张，悲而不痛。"],"notes":[["狭邪","娼妓场所"],["悬鹑","形容衣服破烂如鹌鹑尾"],["悬鹑","衣服破烂如鹌鹑尾"],["痂","伤口结的硬壳"],["蕉叶","芭蕉叶"],["花城","篇中另一位仙女之名"],["翘凤","指女子的小脚"],["怔忡","心悸不安"],["御冬","抵御冬寒"],["绿锦","绿色的锦缎"]],"think":["翩翩说罗子浮“子有俗骨，终非仙品”。这是对他的否定吗？","是平实的判断而非责备：他想回乡，想孝养叔父，这正是俗世情怀。作者写“俗骨”不含贬义，反而是人情的证据。边界是：这是仙女的口吻，作者借此让读者看到仙人与人的不同。"],"quiz":[["翩翩为罗子浮疗疮的方法是？",["让他在溪水中洗，后痂皮脱落","用药膏","念咒"],"“命生解悬鹑，浴于溪流。曰：濯之，创当愈。”"],["花城出现时，罗生做了什么？",["私下捻她的脚，衣变成叶","求婚","逃走"],"“阴捻翘凤”，“袍袴无温；自顾所服，悉成秋叶”。"],["最后他们回家时衣服变成什么？",["蕉叶","金丝","棉布"],"“各视所衣，悉蕉叶；破之，絮蒸蒸腾去”。"]],"cards":[["翩翩教子读书用什么？","取叶写书。"],["为何说“何殊于人世”？","仙女也过着生子、持家、言笑的日子。"]],"line":["子有俗骨，终非仙品","她直说子有俗骨，终非仙品，但这并不是羞辱，只是实话。"],"tags":["仙","家居","浪子"]},"liaozhai_luochahaishi":{"intro":"商人之子马骥乘船被风吹到“大罗刹国”，那里的人以丑为美、以美为丑：他因面目好看被当作妖怪，后来用煤涂脸扮张飞，才得宰相赏识，拜为下大夫。这里选两段：初到时的“反美丑”，以及涂面求宠。后半写海市龙女的情节，另成一线。篇尾异史氏的“花面逢迎，世情如鬼”是点睛之笔。","focus":["前一段的设定很讽刺：问村人为何害怕，答“我国所重，不在文章，而在形貌。其美之极者，为上卿”。官员们个个“双耳皆背生，鼻三孔，睫毛覆目如帘”，位越低越“丑亦渐杀”。把颠倒的价值写成日常，读来比说教更尖锐。","马骥的应对分两步：先是“遇饮食者，则奔而往；人惊遁，则啜其余”，用被人惧怕的优势吃东西；后来用“以煤涂面作张飞”，竟赢得“何前媸而今妍”的好评。他一时的玩笑成了通行证，说明社会评价体系会奖励“与之一致”的人。","他接受了“花面逢迎”，却自觉“颇觉其面目之假”，被人“耳语”，“孤立不自安”，终于乞休。作者没有谴责他，只写他的不安。后文异史氏说“嗜痂之癖，举世一辙”，把罗刹国推向整个世间。"],"notes":[["罗刹","这里指虚构的国度名"],["形貌","外貌"],["上卿","高官"],["民社","地方官职，主管民政与祭祀"],["狰狞","凶恶丑陋"],["相国","宰相"],["前媸而今妍","以前丑陋如今美丽"],["张飞","三国猛将，戏曲中画黑脸"],["涂面","涂画脸面"],["下大夫","官阶名"]],"think":["马骥为什么愿意“涂面求荣”？他与罗刹国人的审美有何区别？","他一开始只当游戏，后来被主人强迫，也被利益诱惑。罗刹国人的审美颠倒，但他们的“以貌取人”与现实无二，这才是讽刺的关键。边界是：马骥始终保留了自我意识，所以最终离开。"],"quiz":[["罗刹国以什么为官位标准？",["容貌的美丑，丑者尊","文章","财富"],"“我国所重，不在文章，而在形貌”，丑之极者为上卿。"],["马骥如何得到宰相赏识？",["以煤涂面扮张飞","献宝","作诗"],"“以煤涂面作张飞”，客曰“何前媸而今妍也”。"],["马骥在罗刹国的感受如何？",["觉人以面目为假，孤立不安，乞休","志得意满","想留下"],"“久而官僚百执事，颇觉其面目之假……憪然不自安”。"]],"cards":[["罗刹国的“美”是什么？","丑，越丑官越大。"],["“花面逢迎”是什么意思？","涂画脸面迎合世俗。"]],"line":["我国所重，不在文章，而在形貌","看着那些以形象代替实力的评价，我只想起一句：我国所重，不在文章，而在形貌。"],"tags":["讽刺","海外","世情"]},"liaozhai_tianqilang":{"intro":"武承休夜梦有人指点：他广交的朋友都是“滥交”，只有猎户田七郎可共患难。他登门结交，七郎的母亲劝儿子不要受恩，因为“无故而得重赂，不祥”。后来七郎还是为武家杀人而死。这里选两段：母亲的训诫与七郎的刺杀。前者写“义”的计算，后者写“义”的代价。","focus":["母亲的话被写得像条契约：“受人知者分人忧，受人恩者急人难。富人报人以财，贫人报人以义。”她看出武公子“有晦纹，必罹奇祸”，所以劝儿子别取钱。作者让一个猎户之母掌握了道义的算术：不要的钱是自由，收下了就是债。","刺杀一段几乎是无声电影：“樵人至前，释担抽利刃，直奔之”，一刀断腕，再一刀决首。七郎“自刭”之后，“尸忽崛然跃起，竟决宰首，已而复踣”。这是全篇最强的一笔：他死了仍要完成未竟的复仇，写出“愤未尽雪，死犹伸之”。","两段之间的关系是人物的因果。七郎起初不愿受重礼，母亲也不愿“事贵客”，是因为他们知道一旦接受，就要用命还。最后七郎的刺杀，既报仇，也还债，使“不轻受”的原则变成“可以一命报之”的信义。"],"notes":[["晦纹","面相上不吉的暗纹"],["罹","遭受"],["重赂","丰厚的馈赠"],["鹿脯","腌干的鹿肉"],["关说","私下说情"],["樵人","打柴人，七郎扮作樵夫"],["格刃","挡住刀刃"],["张皇","惊慌失措"],["僵卧","僵直地躺着"],["崛然","忽然挺立"]],"think":["母亲劝七郎不要受人财物，理由是“富人报人以财，贫人报人以义”。这一逻辑今天还有价值吗？","有。接受别人的好处，本质上是承担一笔关系成本。贫者无财可还，只能还义，所以谨慎。边界是：这种谨慎也会拒绝善意，田七郎母子的拘谨最终也没躲过命运，说明“不受”不等于“无债”。"],"quiz":[["七郎的母亲为什么劝他不要受武的金子？",["无故重赂不祥，恐取死报于子","金子不够","怕邻居议论"],"她说“无故而得重赂，不祥，恐将取死报于子矣”。"],["七郎最终刺杀的是谁？",["御史的弟弟，以及县令","武承休的仇家本人","林儿"],"某弟“被决其首”，宰也“被决首”。"],["“尸忽崛然跃起”的作用是？",["表现死后仍要伸冤，强调七郎之义","暗示他没死","增加恐怖"],"异史氏说“愤未尽雪，死犹伸之，抑何其神”。"]],"cards":[["田七郎之母的核心主张？","小恩可谢，大恩不可谢；贫人报人以义。"],["“愤未尽雪，死犹伸之”说的是？","七郎死后还跃起杀宰。"]],"line":["受人知者分人忧，受人恩者急人难","团队里有人提拔了我，我就要为他的难处出力，受人知者分人忧，受人恩者急人难。"],"tags":["义气","猎户","复仇"]},"liaozhai_gongsunjiuniang":{"intro":"于七之乱后，山东栖霞、莱阳大批人牵连被诛，莱阳生去济南祭奠亲友，遇亡友朱生替外甥女求亲，对象是同在冥中的公孙九娘。他与九娘冥婚，九娘托他把骸骨带回，他却找不到墓，再遇到时九娘已“湮然灭矣”。全篇以冥婚始，以失约终，是《聊斋》里最苍凉的篇章之一。","focus":["冥婚一段仍有温度：朱生“整履摇箑，意甚忻适”，“望尘即拜”，办的是正式的婚礼：“青衣导生去。入室，则九娘华烛凝待。”鬼界的礼仪仍在，只是菜肴“主人自举，殊不劝进”，冷冷地提醒读者这是鬼筵。","九娘的身世只用一句话交代：“母不堪困苦死，九娘亦自刭。”接着她“口占两绝”：“昔日罗裳化作尘，空将业果恨前身。”“血腥犹染旧罗裙”。诗里没有哭，却写出被杀的少女对生前衣裙的牵念，这是全篇最疼的地方。","结尾的失约写得极节制：生“忘问志表”，“千坟累累，竟迷村路”；再去，“墓兆万接，迷目榛荒”。最后遇见九娘，“女竟走，若不相识”，“顿呼九娘，则湮然灭矣”。九娘不是怨恨，是羞见，生也并非无情，是无能。"],"notes":[["整履摇箑","整理鞋子，摇着扇子，形容悠闲得意"],["忻适","欣喜舒适"],["望尘即拜","远远看见尘土就下拜，表示恭敬"],["华烛","婚礼上的红烛"],["欢昵","亲近欢爱"],["自刭","自刎"],["口占","随口作诗"],["业果","佛家所说前世行为造成的果报"],["柔魂","女子的魂魄"],["湮然","消失无迹的样子"]],"think":["九娘最后“若不相识”，是怨还是羞？你怎么判断？","文中异史氏说“怨怼不释于中耶”，作者的判断倾向于怨：他认为九娘为生未能收骨而怨。但文本给的是九娘“色作努，举袖自障”，带有羞与怒。两者并存，难以断言。边界是：这类阴婚故事常以“失约”收尾，更重要的是写出生者对亡者的亏欠感。"],"quiz":[["九娘诗里“血腥犹染旧罗裙”的意思是？",["她死时衣裙上仍染着血","她衣裙华丽","她洗过衣裙"],"九娘自刭而死，血迹仍在旧罗裙上。"],["生没能完成九娘的什么托付？",["收骸骨归葬墓侧","带她还魂","为她报仇"],"“幸念一夕恩义，收儿骨归葬墓侧”，但生“忘问志表”，找不到。"],["“莱霞里”得名的原因是？",["里中多栖霞、莱阳两处新鬼","本是村名","官府命名"],"“里中多两处新鬼，因以为名”。"]],"cards":[["《公孙九娘》的背景事件？","于七之乱后牵连被诛，众多山东人死难。"],["九娘最后的反应？","色作怒，举袖自障，随即消失。"]],"line":["千里柔魂，蓬游无底，母子零孤，言之怆恻","读到这样的叙述，我总会想：千里柔魂，蓬游无底，母子零孤，言之怆恻，有些人的重量在历史里只剩一个名字。"],"tags":["冥婚","亡灵","历史"]},"liaozhai_huxie":{"intro":"万福在济南租房，夜里有狐女来同居，朋友们想见狐，狐只闻声不见形，但每次来必与客斗嘴，以“狐典”取笑他们。孙得言善俳谑，被狐一句“贤孙子”顶回去，又被“龟也得言”戏弄。通篇的魅力在对话，是中国古代少见的“喜剧小说”。","focus":["狐的第一句反击很有手段：“贤孙子欲为高曾母作行乐图耶？”孙得言说“得闻娇音，魂魄飞越”，她便顺势把他的“孙”字用成辈分，说他要为“高曾母”作画。一句话占了便宜又不脏。","两个“狐典”的结构相同：先建立一个正经的场景，再用谐音或字形落到“狐孙子”“瓜+犬”。如“右边是一大瓜，左边是一小犬”，把“狐”字拆开，既嘲笑狐，又嘲笑听者。狐自己讲狐的笑话，是自嘲，也是转移“被冒犯”的风险。","对联一段是全篇高潮：孙出“妓者出门访情人，来时‘万福’，去时‘万福’”，狐对“龙王下诏求直谏，鳖也‘得言’，龟也‘得言’”，用万福、得言双关。对仗工整，让“孙得言”无话可说。作者用这种谐音游戏把谐谑做成了一门技艺。"],"notes":[["俳谑","诙谐戏谑"],["行乐图","描绘人物享乐场景的画像"],["高曾","高祖和曾祖"],["粲然","露齿而笑"],["阳台","指男女欢会（宋玉《高唐赋》）"],["狐典","狐编的笑话"],["红毛国","指西洋国家，泛称"],["绝倒","笑得前仰后合"],["殚述","全部说出"],["万福","妇女行礼时说的吉利话，也是人名"]],"think":["狐为什么总能占上风？她的谐谑与孙得言的不同在哪里？","狐懂得自嘲，把自己放在“被笑”的位置，再反过来占便宜；孙得言只会攻击。好的幽默常是先把自己放低，让对方无法生气。边界是这类幽默依赖语言默契，在跨文化场合很难复制。"],"quiz":[["狐为何拒绝露面？",["她说“见我何为哉”，不愿以形示人","她是鬼","她不会现形"],"“见我何为哉？我亦犹人耳。”"],["“右边是一大瓜，左边是一小犬”拆的是哪个字？",["狐","犯","猎"],"“狐”字左犬右瓜，是以字形开玩笑。"],["狐对出的下联用了什么手法？",["以“万福”“得言”两个人名双关","对仗平仄","引用典故"],"孙出“万福”，狐对“得言”，两人名都被嵌入对联。"]],"cards":[["《狐谐》里主要的笑点来源？","文字游戏：拆字、谐音、双关。"],["狐娘子的特点？","机敏、自嘲、擅长在众人前占口头便宜。"]],"line":["我为狐，请与客言狐典","在会上我主动讲一个自己的失败案例，说：我为狐，请与客言狐典，大家就放松了。"],"tags":["狐","谐谑","喜剧"]},"liaozhai_yuqian":{"intro":"滨州一个秀才贫穷，结识狐仙胡养真，请他帮忙变出钱来。狐仙让他拿十几枚钱当“母”，念咒后钱像雨一样下，满屋深至脚踝，等秀才进屋再取，全部消失，只剩十几枚“母钱”。狐仙拂衣而去：“我本与君文字交，不谋与君作贼。”一个小品，一句话，把“凭空得财”的逻辑拆穿。","focus":["狐仙最初的形象是“皤然一翁，形貌甚古”，“经义，则名理湛深”。他不是来变钱的，是来做文字交。因此秀才一句“君但一举手，金钱宜可立致”，一下把关系从知音变成借贷。","钱雨一段写得声势浩大：“钱有数十百万，从梁间铿铿而下，势如骤雨。转瞬没膝；拔足而立，又没踝。”好比一场幻觉，量大得夸张，却也暗示它不可能留下。结尾“惟母钱十余枚，寥寥尚在”，是最重的讽刺。","胡翁的理由很明白：“便如秀才意，只合寻梁上君交好得。”意思是，这种钱只能从盗贼处来，他不做贼。把仙术与偷盗等同，是对“不劳而获”的直接批评。这是篇名“雨钱”的伏笔：它只是雨，不是财。"],"notes":[["皤然","头发雪白的样子"],["博洽","学问广博"],["镂花雕缋","形容文采华美"],["名理","事物的道理"],["禹步","道士作法时的步法"],["阿堵物","钱的别称"],["母钱","起引导作用的本钱"],["梁上君","窃贼的雅称"],["拂衣","甩袖，表示愤然"],["怼","怨恨"]],"think":["胡翁说“不谋与君作贼”，这是否说明凭空得钱就一定不义？","他的逻辑是：不是靠劳动或对价得来的钱，其性质和偷盗相似。边界在于“凭空”二字：如果是创造价值的结果，另当别论。这个故事针对的是想要“立致金钱”的心态。"],"quiz":[["秀才求狐仙做什么？",["变出金钱","教他写文章","介绍官职"],"“君但一举手，金钱宜可立致。”"],["最后屋里剩下什么？",["十几枚母钱","一半金钱","一箱银子"],"“满室阿堵物，皆为乌有，惟母钱十余枚，寥寥尚在”。"],["胡翁离开前说什么？",["我本与君文字交，不谋与君作贼","你再给我钱","明日再来"],"原话如此，点明二人本是文字交。"]],"cards":[["“阿堵物”指什么？","钱。"],["“雨钱”的结果？","钱雨过后全部消失，仅余母钱。"]],"line":["我本与君文字交，不谋与君作贼","合作前我会先说明：我本与君文字交，不谋与君作贼，灰色的钱我不做。"],"tags":["狐","钱","寓言"]},"liaozhai_qieji":{"intro":"益都某富户有一个常受正妻鞭打的小妾，一夜盗贼数十人翻墙入屋，小妾提着挑水木杖冲出，击倒四五人，笑着把他们放走。原来她是枪棒师之女，尽得其术。这篇短小得几乎像速写，却有两层：一层是“人不可貌相”，一层是“是吾分耳”。","focus":["前半写“忍”：“冢室凌折之，鞭挞横施。妾奉事之惟谨。”写的是被欺压的弱者，没有怨言。作者早早埋下对比，使后面的“舞杖”有落差：能打百人的人，在家里却只受鞭子。","击贼一场很快：“拔关遽出”，“风鸣钩响，击四五人仆地；贼尽靡”。她笑说：“此等物事，不直下手插打得！亦学作贼！”语气里没有杀意，只有不屑，“我不汝杀，杀嫌辱我”，放走盗贼。身手之后是教养，是判断。","邻妇问她为何不反抗，她只说“是吾分耳，他何敢言”。“分”是名分，也是自己认定的位置。异史氏说“居数年而人莫之知，而卒之捍患御灾，化鹰为鸠”，把她比作潜伏的人才，感慨“技之不可以已也”。"],"notes":[["冢室","正妻"],["鞭挞","用鞭子抽打"],["逾垣","翻过墙"],["拔关","拉开门闩"],["风鸣钩响","棍棒挥动时发出风声"],["枪棒师","教授枪棒武艺的师傅"],["俛首","低头"],["分耳","本分罢了"],["化鹰为鸠","由凶猛变温顺，典出《礼记》月令"],["射雉","典出《左传》，贾大夫之妻不言不笑，射雉后才笑"]],"think":["小妾有本事却隐忍，她的“分”是美德还是束缚？","文中看是两者并存：作者赞她“终无纤毫失礼”，同时也让人看到她因身份而不得不忍。边界是：作者没有批评冢室，也没有提供出路，所以这是对古代妾的处境的一种“隐性控诉”。"],"quiz":[["小妾为何能击退数十盗贼？",["父亲是枪棒师，她尽得其术","她有神力","盗贼是纸人"],"“则妾父故枪棒师，妾尽传其术”。"],["她为何放走盗贼？",["不愿杀人辱自己","害怕","贼首求情"],"“我不汝杀，杀嫌辱我”。"],["邻妇问她为何受打，她怎么回答？",["是吾分耳，他何敢言","因为害怕","因为爱丈夫"],"原话如此。"]],"cards":[["“冢室”是什么？","正妻，大妇。"],["小妾为何不反击正妻？","她认为这是自己的本分。"]],"line":["是吾分耳，他何敢言","面对越级的指责，我只说：是吾分耳，他何敢言，先把本职做好。"],"tags":["女子","武艺","隐忍"]},"liaozhai_xuhuangliang":{"intro":"曾孝廉新中进士，问相士“有蟒玉分否”，被许为“二十年太平宰相”，随即在僧舍睡去，梦里一路升至宰相，也一路作恶，被弹劾、抄家、杀头，在阴间受油鼎、刀山、灌金钱，转世为乞儿之女，被冤杀。醒来时黄粱未熟。“续黄粱”继承唐传奇的梦，但把重点放在宰相的行为上。这里选三段：得势、地狱与梦醒。","focus":["得势一段，是权力快感的素描：“早旦一疏，荐为谏议，即奉俞旨，立行擢用”，“越日，弹章交至，奉旨削职以去。恩怨了了，颇快心意。”接着“醉人适触卤簿，即遣人缚付京尹，立毙杖下”。作者让曾孝廉的“恩怨”与“杀人”并列，说明权力一旦没有制约，善恶标准就变成个人好恶。","地狱一段写得极有设计：王者让人“持筹握算”，算出他“卖爵鬻名、枉法霸产”所得共三百二十一万，“彼既积来，还令饮去！”金钱被熔成汁灌入口，“生时患此物之少，是时患此物之多也”。惩罚与罪行一一对应，既是黑色幽默，也是最直接的因果。","梦醒的收束很冷：同侣说“日暮腹枵，何久酣睡？”老僧“微笑曰：宰相之占验否？”曾孝廉“胜气而来，不觉丧气而返”，最后“入山不知所终”。僧人的话只有一句“修德行仁，火坑中有青莲也”，不劝诫，只留一线出路。"],"notes":[["微时","地位低微的时候"],["蹉跎","时光虚度，仕途不顺"],["引手","伸手援引"],["擢用","提拔任用"],["睚眦","瞪眼，指小小的怨恨"],["弹章","弹劾官员的奏章"],["卤簿","帝王或高官出行的仪仗"],["京尹","京城的行政长官"],["持筹握算","手拿算筹计算"],["青莲","佛教中出于污泥而不染的莲花"]],"think":["曾孝廉的“恩怨了了，颇快心意”，与阴司的“彼既积来，还令饮去”之间的对应关系说明什么？","说明作者把“权力”与“报应”做成一个对称的设计：他怎么用权，就怎么受罚。边界是这套报应只在梦里成立，现实里很少如此精准；它更像一种道德想象，提醒掌权者审视自己的“快意”。"],"quiz":[["曾孝廉在梦中得意的主要表现是？",["随意提拔与打击他人，甚至杀人","勤政爱民","辞官归隐"],"他“荐为谏议”“授意弹劾”，还因醉人冲撞仪仗，令“立毙杖下”。"],["阴司对他“卖爵鬻名”之罪怎么罚？",["把所得金钱熔化灌进口中","罚做苦役","发配远方"],"“彼既积来，还令饮去！”，“渐入铁釜，熔以烈火”。"],["老僧最后一句话的含义是？",["在火坑里也能有青莲，意即修德行仁仍有生路","山僧不懂","宰相的占卜灵验"],"他说“修德行仁，火坑中有青莲也。山僧何知焉。”"]],"cards":[["《续黄粱》续的是哪篇故事？","唐代《枕中记》的黄粱一梦（异史氏说“附之邯郸之后”）。"],["“青莲”象征什么？","佛家莲花出污泥不染，喻在苦海中也能清净。"]],"line":["生时患此物之少，是时患此物之多也","看着堆积如山的仓库，我常想起一句：生时患此物之少，是时患此物之多也。"],"tags":["梦","权势","因果"]},"liaozhai_zhaochenghu":{"intro":"赵城的老妇独子被虎吃了，她一次次到县衙哭诉，县令不忍，勉强发了“捉虎”的牌票，差役李能被迫在山里蹲了一个多月，最后在东岳庙里向神明祷告，竟有一只虎自来受缚。县令审虎，问它是否吃了人，虎点头，又问“倘尔能为若子，我将赦之”，虎又点头。此后虎替老妇奉养终身，死后建“义虎祠”。","focus":["开头县令的态度很值得读：“虎何可以官法制之乎？”他明知荒谬，仍“又怜其老，不忍加威怒，遂诺为捉虎”。一个“怜”字把荒唐的判案变成了不得已的善意，所以后面的“审虎”才不显得闹剧。","差役李能的苦写得实：“月余，受杖数百，冤苦罔控”。他到岳庙里哭，神明没有显灵，只是虎来了。作者留下很大的空白，让读者自己去想：是神，是巧合，还是虎的灵性。这种不解释，使故事保持了一种天真的信任。","审虎的逻辑非常简洁：“杀人者死，古之定律。且妪止一子，而尔杀之，彼残年垂尽，何以生活？”判决不是死，而是“替子”。“虎又颔之”，这个“又”字写出了对话的完整性。最后虎在老妇墓前“嗥鸣雷动”，把一个官府的权宜之计变成了一个有感情的人兽故事。"],"notes":[["勾牒","拘捕人犯的文书"],["咥噬","咬噬"],["缧索","拘系人的绳索"],["帖耳","耳朵贴下，表示驯服"],["颔","点头"],["货","出售"],["瘗","埋葬"],["嗥鸣","大声吼叫"],["醺醉","大醉"],["塞责","搪塞责任"]],"think":["县令让虎“替子”奉养老妇，是荒诞还是善政？","形式荒诞，实质是一种变通：既满足了法理（杀人者要偿），又顾及了现实（老妇需要生活）。边界是它建立在虎有灵性的前提上，故事里的县令赌对了，现实中很难。"],"quiz":[["县令为什么答应为老妇“捉虎”？",["怜她年老、不肯罢休","受贿","被神明托梦"],"“又怜其老，不忍加威怒，遂诺为捉虎”。"],["县令对虎的判决是？",["放了它，让它替老妇之子","处死","关入笼中"],"“倘尔能为若子也，我将赦之。”虎颔之，乃释。"],["虎死后怎样？",["建“义虎祠”","被人猎杀","消失"],"“土人立义虎祠于东郊，至今犹存”。"]],"cards":[["李能是谁？","被派去捉虎的差役。"],["虎怎样回报老妇？","送鹿、金帛，守着她到死。"]],"line":["杀人者死，古之定律","对待规则，不能只说杀人者死，古之定律，还要看如何善后。"],"tags":["虎","官府","义"]},"liaozhai_maya":{"intro":"白家庄一个人偷邻居的鸭子煮了吃，夜里浑身长出鸭毛，一碰就痛。梦里有人告诉他，须被失主痛骂才能脱毛。邻翁向来不骂人，他只好承认真相，翁才骂了一顿，毛落病愈。故事极短，只有一百多字，异史氏的两句“甚矣”把偷与骂都说透了。","focus":["报应来得极快也极形象：“夜，觉肤痒。天明视之，茸生鸭毛，触之则痛。”不是死，不是病，而是偷什么变什么。这种“对应式报应”是民间故事的常用逻辑，既荒诞又好记。","解法比病更有意思：必须“得失者骂”。偏偏邻翁“素雅量，生平失物，未尝征于声色”。偷鸭的人先骗翁说“彼深畏骂焉”，翁笑着说“谁有闲气骂恶人”。这一幕写出两个人：一个想蒙混，一个不动气。","最后“某益窘，因实告邻翁。翁乃骂，其病良已。”惩罚的核心是坦白。异史氏说“骂行其慈”，邻翁不骂是宽，肯骂是慈，作者把一场小纠纷写成了一个伦理判断。"],"notes":[["攘","偷窃"],["茸生","细毛长出"],["天罚","上天的惩罚"],["雅量","宽宏的度量"],["征于声色","表现在声音和脸色上"],["诡告","欺骗地说"],["良已","确实痊愈"],["闲气","无谓的气"],["恶人","这里指偷鸭人"],["失者","失物的主人"]],"think":["为什么必须“被骂”才能康复？","因为骂是一种让他承认罪、让邻翁表达情绪的仪式。偷鸭的人若不愿面对，罪就在他身上“长”着。边界是：现实里并非受害者都应该发火，作者强调的是“坦白”才是起点。"],"quiz":[["偷鸭者的病如何治？",["让失主骂他","吃药","烧香"],"梦中有人告诉他“须得失者骂，毛乃可落”。"],["邻翁为什么起初不骂？",["素有雅量，不喜动气","怕得罪人","不信"],"“素雅量，生平失物，未尝征于声色”，又说“谁有闲气骂恶人”。"],["异史氏说“骂行其慈”是什么意思？",["邻翁以骂这一方式施行慈悲","骂人是对的","偷鸭者可怜"],"“彼邻翁者，是以骂行其慈者也。”"]],"cards":[["偷鸭之人遭什么报应？","全身长鸭毛，碰就痛。"],["解除之法？","失主痛骂一顿。"]],"line":["一攘而鸭毛生","他一贪小便宜就出了事，一攘而鸭毛生，别人以为是巧合，他自己明白。"],"tags":["报应","偷窃","慈"]},"liaozhai_tiaoshen":{"intro":"这是一篇民俗速写。济南一带病人求神，请老巫“跳神”，良家少妇也自己跳。蒲松龄不解释，不评论，只写：烛火、鼓声、酒肉、突然吹灭灯，再点起时，酒肉全空。又写满洲妇女的“跳虎神”，神气更凶。篇幅短，场景鲜明，适合当作“看一个仪式”的练习。","focus":["布置场面时不夸张：“堂中肉于案，酒于盆，甚设几上。烧巨烛，明于昼。”接着女子“束短幅裙，屈一足，作商羊舞”，“两人捉臂，左右扶掖之”。这样的白描让读者像围观者，先看到的是器物与动作，而不是神。","高潮是“忽伸颈巨跃，离地尺有咫”，室中人说“祖宗来吃食矣”，“一嘘，吹灯灭，内外冥黑”。人们“惵息立暗中，无敢交一语”，再点灯时“视尊中，盎中，案中，都复空空”。酒肉的消失是全篇唯一的“神迹”，作者不点破，是魔术还是附体，留给读者。","后半转写“腹诽”：中有腹诽者，“神已知，便指某姗笑我，大不敬，将褫汝袴。诽者自顾，莹然已裸”。这是一个带讽刺的小细节：神只会惩罚笑的人，其实也是对家族权威的一种形象化。再看满洲妇女的“跳虎神”，“赫气惨凛，尤能畏怖人”，作者以“森森蹜蹜，雁行立”收尾，笔调也冷。"],"notes":[["老巫","年长的巫婆"],["商羊舞","一种模仿商羊鸟的舞蹈，商羊是传说中的雨鸟"],["剌剌","说话絮絮不休的样子"],["挝","击打"],["休咎","吉凶"],["姗笑","讥笑"],["褫","剥去"],["玄坛","赵公明，民间财神"],["跳虎神","满族妇女的另一种跳神"],["雁行","像大雁一样排成行"]],"think":["作者全篇不评价“跳神”是真是假，为什么？","一是写民俗的方式：只记，不判。二是为留白，“酒肉皆空”的事既可是神迹也可是人的戏法。边界是：这种“不评价”不是赞成，而是一种冷静的观察。"],"quiz":[["“跳神”是为了什么？",["给病人求神问卜","庆祝节日","祭祀祖先"],"“民间有病者，闺中以神卜。”"],["灯一灭一亮之后发生了什么？",["案上酒肉都空了","神像出现","病人痊愈"],"“视尊中，盎中，案中，都复空空。”"],["满洲妇女的“跳虎神”特点？",["骑假虎假马，执长兵，舞于榻上，气势凶猛","安静坐着","唱歌"],"原文“时严妆，骑假虎假马，执长兵，舞榻上”。"]],"cards":[["“商羊舞”是什么？","一种跳神舞蹈，模仿传说中的雨鸟商羊。"],["全篇最神秘的一笔？","吹灯再点，酒肉皆空。"]],"line":["祖宗来吃食矣","一到年终，办公室里总有人开玩笑：祖宗来吃食矣，那份报销单终于有人签了。"],"tags":["民俗","巫","场景"]},"liaozhai_langsanze":{"intro":"三个屠夫夜行遇狼。第一个把肉挂在树上，狼吊死；第二个靠着柴草堆，劈杀了两头假寐、打洞的狼；第三个把狼爪割破，以吹猪法把狼吹胀。三则故事共同点是：狼贪而狡，屠夫更狡。蒲松龄在每则末尾加评语：缘木求鱼，禽兽之变诈，屠人之残可用于杀狼。短小的叙事、清晰的转折、一两句冷评，是这篇的看点。","focus":["第一则写“贪”：狼“瞰担中肉，似甚涎垂；步亦步，尾行数里”。屠夫把肉挂树，“示以空空”，狼就止步。第二天狼死，“口中含肉，肉钩刺狼腭，如鱼吞饵”。“缘木求鱼，狼则罹之”，一句评语把动物与成语勾在一起。","第二则写“诈”：两狼并行，一狼“犬坐于前，久之，目似瞑，意暇甚”；另一狼“洞其中，意将隧入以攻其后”。屠夫“暴起”劈狼，又“自后断其股”，“乃悟前狼假寐，盖以诱敌”。狼的战术与屠夫的反应，节奏紧凑得像一场战斗。","第三则写“智”：屠夫抓住狼爪，“割破爪下皮，以吹豕之法吹之”，狼“胀如牛，股直不能屈”。这是三则里最奇的一则，也最具体：吹猪法是屠夫的日常手艺，用来制狼，才是“非屠乌能作此谋也”。"],"notes":[["瞰","窥视"],["涎垂","口水流下"],["缘木求鱼","爬树捉鱼，比喻方向错误"],["苫","覆盖，苫盖"],["积薪","堆积的柴草"],["假寐","装睡"],["尻","臀部"],["吹豕","给猪吹气以便刮毛的手艺"],["变诈","变化诡诈"],["罹","遭受"]],"think":["三则狼故事都写“狼贪而诈”，你能从中学到什么应对策略？","第一则以静制动，用不让它得手；第二则认清对方的“假象”再出手；第三则善用自己的专业手艺。三者共同点是不盲目反击，而是用自己最熟的工具。边界是：这些是屠夫的经验，不能简单搬到其他场景。"],"quiz":[["第一则屠夫怎样处理狼？",["把肉挂在树上，狼想取肉被钩死","用刀砍","逃跑"],"“肉钩刺狼腭，如鱼吞饵”。"],["第二则中的“前狼”其实在做什么？",["假寐诱敌，另一狼从后挖洞","休息","守卫"],"“乃悟前狼假寐，盖以诱敌”。"],["第三则的关键技巧是？",["以吹猪法吹胀狼","用毒药","用火"],"“以吹豕之法吹之”，狼“胀如牛”。"]],"cards":[["“缘木求鱼”在第一则里指什么？","狼想取树上的肉，却被肉钩刺死。"],["第三则中屠夫用的手艺？","吹猪，使狼身体胀直。"]],"line":["非屠乌能作此谋也","这套解决方案之所以有效，是因为用的是我们最熟悉的手艺：非屠乌能作此谋也。"],"tags":["狼","机智","寓言"]},"liaozhai_xihou":{"intro":"满生在杭州遇见青楼女细侯，两人订约：他去湖南筹百金，她闭门等。三年不归，富商骗她他已死，她被迫嫁人；满生出狱后才知道，细侯杀子投奔，两人团圆。蒲松龄在篇末说：“壮缪之归汉，亦复何殊？顾杀子而行，亦天下之忍人也！”这是对细侯的赞美，也是对她的批评，非常复杂。","focus":["细侯的“志”写得具体：她问满生“视妾可当家否”，随即安排：“四十亩聊足自给，十亩可以种黍，织五匹绢，纳太平之税有余矣。闭户相对，君读妾织。”一个青楼女子想象出的家庭生活，不求富贵，只求“闭户相对”。这一番话让读者理解她后来为何宁愿受骗也不肯再嫁。","骗局来得很具体：“富贾某……以金贿当事吏，使久锢之。归告媪云：生已瘐死。”再让人假写“绝命书”。细侯的回答是“满生虽贫，其骨清也”，最后“不得已，遂嫁贾”。人物是被一层层压力逼出来的，不是轻易变心。","结尾最重的是“杀抱中儿，携所有亡归满；凡贾家服饰，一无所取”。她杀子为义，又不取一物。作者借“寿亭侯之归汉”比拟，同时说“杀子而行，亦天下之忍人也”。这句话没有对错，只让我们看到“义”的代价。"],"notes":[["雏姬","年轻的歌伎"],["要妙","美好动人"],["口占","随口吟诗"],["麝兰","麝香与兰草，指香气"],["措大","穷书生"],["椎布","椎髻布衣，形容贫寒"],["瘐死","在狱中病死"],["绝命书","临终遗书"],["寿亭侯","汉寿亭侯关羽"],["忍人","残忍之人"]],"think":["细侯杀子归满生，作者为何同时赞与贬？","赞她守约、不取分文；贬她杀掉亲生儿子。作者用“忍人”这个评价，让人对“义”的代价保持清醒。边界是：这不是对细侯的单一裁决，而是对一种极端选择的复杂态度。"],"quiz":[["细侯最初的愿望是什么？",["与满生闭户相对，读书织布","嫁给富商","开店经商"],"“四十亩聊足自给……君读妾织”。"],["谁设了计让细侯嫁人？",["富贾，买通官吏并伪造绝命书","满生的朋友","细侯的母亲"],"“贾以金贿当事吏，使久锢之”，又“假作满生绝命书”。"],["篇末“寿亭侯之归汉”指什么？",["关羽离曹归汉，比喻细侯弃贾归满","关羽被杀","关羽之死"],"关羽因义离开曹操，细侯因义离开富商。"]],"cards":[["细侯杀的是谁？","她与富贾所生的孩子。"],["“其骨清也”是评价谁？","满生，虽穷但清高。"]],"line":["满生虽贫，其骨清也","选合作伙伴，我看重的不是眼前资源，而是满生虽贫，其骨清也。"],"tags":["青楼","守志","评价"]},"liaozhai_wangcheng":{"intro":"王成是没落世家子，又懒又穷，捡到祖母（狐仙）失落的金钗，把它还给失主，得到她的资助：先让他去贩葛，亏了本；再让他贩鹌鹑，鹑死剩一只，他靠斗鹑一路赢，最终以六百金卖给王府，成了富户。这里选两段：拾钗与斗鹑。故事的看点在“懒”如何变成“勤”，也在他拒绝高价时的那股“至性”。","focus":["拾钗一段交代了王成最重要的品质：“王虽故贫，然性介，遽出授之。”他饿着肚子仍把拾到的金钗还给失主，这种“介”（耿直）是狐仙愿意帮他的唯一理由。作者没有说他懒，是为了让读者先看到他的底色。","斗鹑一段写得像比武：王府的鹑“素羽如鹭，神骏不凡”，王成的鹑“伏如怒鸡以待之”，再“起如翔鹤以击之，进退颉颃，相持约一伏时”。动作对仗，层次清楚。把一场鸟斗写成战役，是《聊斋》擅长的“小事大写”。","最有趣的是卖鹑：王爷出价二百、三百，王成都摇头，说“连城之璧不过也”，理由是“日得数金，易升斗粟，一家十余食指，无冻馁忧”。他的价格不是市场价，而是“生活价”。最后六百金成交，主人说“再少靳之，八百金在掌中矣”，他却“惟恐失时”。这一笔使人物既精明又老实。"],"notes":[["牛衣","给牛御寒的草编衣，指贫寒"],["仪宾","明代宗室郡主之夫的称号"],["缱绻","情意深厚缠绵"],["把鹑","手持鹌鹑"],["铁喙","鸟喙坚硬"],["铩羽","羽毛摧折，指失败"],["颉颃","不相上下"],["一伏时","一昼夜，也说十二个时辰"],["连城之璧","价值连城的玉璧"],["食指","家中吃饭的人口"]],"think":["王成最后只卖六百金，理由是“恐交而不成，获戾滋大”。你认为他是见好就收，还是缺乏谈判力？","两者皆有：他确实是个“心愿盈溢，惟恐失时”的老实人；但同时也清楚王爷是权贵，拒绝久了会惹祸。故事里借主人之口说“再少靳之，八百金在掌中”，是商人式的遗憾，也是作者对“知足”的一种幽默。"],"quiz":[["王成能得到狐仙帮助的原因是？",["拾金钗不昧，性介","出身高贵","会读书"],"“王虽故贫，然性介，遽出授之。”"],["王成为什么拒绝王爷的第一次出价？",["他把鹑看作谋生之本","价格太低","不懂行"],"他说“小人无恒产，与相依为命”。"],["异史氏说“此独得于惰”是什么意思？",["他的富不是靠勤劳，是靠狐仙和运气","他后来变懒","他勤劳"],"“富皆得于勤，此独得于惰，亦创闻也。”"]],"cards":[["王成为什么能发财？","狐仙祖母帮他买鹑，加上斗鹑获胜，卖了六百金。"],["“介”是什么？","正直耿介，不取不义。"]],"line":["日得数金，易升斗粟，一家十余食指，无冻馁忧","报价时我不只想市场价，还要想自己的底线：日得数金，易升斗粟，一家十余食指，无冻馁忧。"],"tags":["狐","经商","斗鹑"]},"liaozhai_laotao":{"intro":"邢德是绿林好汉，连珠箭天下无双，却出门总亏钱。年末回乡路上，他在小店里瞥见一个老头带着两个少年和一个仆人，带着大笔钱财，起了抢劫之意，结果被老头“笑曰：技但止此，何须而翁手敌”，后来又被那个仆童碾压，丢了钱财。故事极短，却把“高手在民间”写得淋漓尽致，最后一句“孟浪”，是最大的讽刺。","focus":["对手的出场极为日常：老头与少年饮酒，“僮行觞，误翻盘具，污叟衣”，少年立刻“摘其耳”，又“捧巾持帨，代叟揩拭”。这是先给读者一个“不惹眼的富家”的印象，再用僮手上“铁箭环，厚半寸”作暗示。","邢德出手后，连发两箭，叟“仰卧鞍上，伸其足，开两指如箝夹矢住”，又被后矢“贯其口”，却“吐矢跃起，鼓掌曰：初会面，何便作此恶剧”。老头不怒，是因为根本没把他放在眼里。","僮童的一段最干脆：“手接二，口衔一。笑曰：如此技艺，辱没煞人！”再把箭穿进铁环，“以手力掷，呜呜风鸣”，震断弓弦，“弓亦绽裂”。取金之后，“作一举手，致声孟浪，霍然径去”。这句“孟浪”不是道歉，是对对方鲁莽的冷评。"],"notes":[["绿林","指盗贼、强盗"],["满引","把弓拉满"],["连珠","接连发射"],["踣然","向前倒下"],["箝夹","像钳子一样夹住"],["款段","缓缓而行"],["革囊","皮袋"],["老饕","这里是老头的自称，意为老贪吃的"],["孟浪","鲁莽，冒失"],["揩拭","擦拭"]],"think":["为什么作者要把真正的高手设计成老头与仆人，而不是年轻的少年？","因为“不起眼”最具反差。高手越不事声张，越显出邢德的轻率。边界是这也是传统叙事的套路：“扮猪吃老虎”。蒲松龄的好处在于只写动作与对话，不加判断，由读者自行体会。"],"quiz":[["邢德的绝技是？",["连珠箭","飞镖","长枪"],"他“能挽强弩，发连矢，称一时绝技”。"],["仆童怎样挫败邢德？",["接箭并穿环回掷，断弓","用刀","下毒"],"“以手力掷，呜呜风鸣，邢急拨以弓；弦适触铁环，铿然断绝，弓亦绽裂。”"],["“孟浪”一词在文中的意味？",["对邢德的冒失作冷评","向邢德道歉","夸邢德英勇"],"童在抢走钱后“致声孟浪”，是揶揄。"]],"cards":[["《老饕》里“老饕”指谁？","那位老头，自称“老饕”。"],["邢德的结局？","被劫去钱财，后来成为善士。"]],"line":["如此技艺，辱没煞人","看着那份草率的方案，评审只说一句：如此技艺，辱没煞人，但并没有生气。"],"tags":["武艺","高手","绿林"]},"liaozhai_huaguzi":{"intro":"安幼舆爱放生，在华山迷路，遇到老翁章叟和他的女儿花姑子。后来他患相思病，花姑子来救，但她直言“实不能永谐琴瑟”。安生不甘，再夜上山，被冒充花姑子的蛇精害死；真正的花姑子来哭，以草汤救活他，并说破自己是他当年所放獐子的女儿。这里选两段：花姑子的救治，与她说破真相。","focus":["救治一段是极轻的笔：“女倾头笑曰：痴儿何至此耶？”她“坐安股上，以两手为按太阳穴”，“安觉脑麝奇香，穿鼻沁骨”，又留下“数蒸饼”。药是饼，情是香，没有一句关于病的专业话，却写出了温柔。","安生复活后，她的话把全篇的结构揭开：“君五年前，曾于华山道上买猎獐而放之否？”“是即妾父也。”原来章叟一家是獐，花姑子是以报恩的身份出现。这样的反转比“狐报恩”更有新意，因为獐的“仙”与“不懂人事”被写成了“憨”。","再看她为他做的牺牲：“父愿坏道代郎死，哀之七日，始得当。”她还告诉他怎样取蛇血疗痹，叮嘱“多残生命，累我百年不得飞升”，“业行已损其七”。报恩之后，她留下一个孩子，也留下“不复娶”的安生。她的情不是“占有”，而是“恝”，异史氏称这是“情之至”。"],"notes":[["太阳穴","眉梢后的凹陷处"],["蒸饼","蒸熟的面饼"],["噭啕","大声哭"],["涕洟","眼泪鼻涕"],["燂汤","煮汤"],["蛇精","蛇所化之妖"],["痿痹","肢体瘫软麻木"],["晡时","申时，下午三点到五点"],["强弩","强劲的弓弩"],["孽根","因缘留下的后代，这里指孩子"]],"think":["花姑子早就知道安生将要遭祸，却没有直接阻止他。作者想表现什么？","她的不干预，是因为人神之别与天条：父亲已经违规以命救一次，她再干预只会更麻烦。作者借此写出“报恩”的限度：能救一次，不能救一世。边界是：这一点文中并未明说，是读者的推断。"],"quiz":[["花姑子救安生的第一步是？",["按太阳穴，留下蒸饼","用符水","念咒"],"“以两手为按太阳穴”，又“出数蒸饼置床头”。"],["冒充花姑子的是？",["蛇精","狐精","鬼"],"“此蛇精冒妾也。前迷道时所见灯光，即是物也。”"],["花姑子为何报恩？",["安生曾买獐放生","安生是她的丈夫","她欠安生钱"],"“君五年前，曾于华山道上买猎獐而放之否？是即妾父也。”"]],"cards":[["花姑子的真身？","獐。"],["异史氏评她“憨者慧之极”意思？","看似天真的人反而最聪明。"]],"line":["再杀之惟卿，再生之亦惟卿矣","他对她说：再杀之惟卿，再生之亦惟卿矣，一句话里是怨，也是敬。"],"tags":["放生","报恩","蛇精"]},"liaozhai_lvyinv":{"intro":"于璟在寺中夜读，一个绿衣女子来访，同居数夜，她只敢低声歌唱，又总担心“偷生鬼子常畏人”。一晚她忽然心动：“妾禄尽矣。”他送她出门，听到屋檐上呼救，原来是一只绿蜂被蜘蛛缠住。他破网救了绿蜂，它伏在墨汁里写下“谢”字飞去。全篇只有五百字，却是《聊斋》最短而最动人的爱情篇之一。","focus":["绿衣女子出场时的话“于相公勤读哉！”重复两次，既写出她的轻快，也让人隐隐觉得有些不对：谁会在深山夜里这样称赞书生？“腰细殆不盈掬”，则暗示她就是蜂。","歌的一段最精彩：她“以莲钩轻点足床”，唱“树上乌臼鸟，赚奴中夜散。不怨绣鞋湿，只恐郎无伴”。声音“细如蝇”，“宛转滑烈，动耳摇心”。蜂的嗡嗡声被写成了歌，细微，却打动人。","收束有两个动作：“徘徊复返，曰：不知何故，惿惿心怯。乞送我出门。”以及“自以身投墨汁，出伏几上，走作‘谢’字”。前者写预感，后者写感恩。没有一个多余的字，却把一个生命的终点和重生写得很轻。"],"notes":[["赞","称赞"],["咋噬","咬噬"],["罗襦","丝罗短衣"],["更筹","夜间计时的竹签"],["莲钩","女子小脚的美称"],["乌臼鸟","乌鸦或一种鸟名"],["偷生鬼子","偷偷活着的鬼，形容不敢见人"],["心怯","心里害怕"],["砚池","砚台里储墨的凹处"],["绿蜂","绿色的蜂"]],"think":["绿衣女对“偷生鬼子常畏人”的说法，暗含了什么？","暗含她其实是弱小的昆虫，生活在随时被捕食的环境里，所以格外谨慎。作者借“畏人”写出对弱者的同情。边界是：这句话本身是比喻，不是蜂的自述，故事里并没有明说。"],"quiz":[["绿衣女为何频频要求关窗或送她出门？",["预感危险，怕蜘蛛","怕被发现","害怕黑暗"],"她说“妾心动，妾禄尽矣”，又“心怯”，后来果然被蛛网缠住。"],["她最后用什么表达谢意？",["以身投墨，在几上走出“谢”字","赠送金银","唱歌"],"“自以身投墨汁，出伏几上，走作‘谢’字。”"],["她的真身？",["绿蜂","绿鸟","绿蜻蜓"],"“则一绿蜂，奄然将毙矣”。"]],"cards":[["绿衣女唱的歌说了什么？","“不怨绣鞋湿，只恐郎无伴。”"],["她为何夜夜来？","与于生相爱。"]],"line":["不怨绣鞋湿，祗恐郎无伴","她写下的这句歌词，我常想起：不怨绣鞋湿，祗恐郎无伴，把牺牲说得很轻。"],"tags":["蜂","爱情","报恩"]},"liaozhai_yuncuixian":{"intro":"梁有才是个小贩，在泰山上追求云翠仙，婚后好赌，辜负妻子，又被赌友挑唆，打算把她卖入娼籍。翠仙假意同意，半夜带他回到“母家”，当着母亲与众人历数他的罪，他被刺伤，眼前一黑，坐在悬崖边。后来他腐烂乞讨，最终因杀人被囚死。这里选两段：卖妻之夜与结局。这是《聊斋》里最严厉的“负心人”篇之一。","focus":["翠仙的计谋很沉着：“念一贫如此，便死相从，不过均此百年苦，有何发迹？不如以妾鬻贵家，两所便益。”她用梁的口吻把“卖妻”说成“两益”，诱他签约，“立券八百缗，事濒就矣”。她不是被动受骗，而是主动设局，让他把恶行做足。","回到“母家”后，她的数落具体到身体：“初近我，熏熏作汗腥，肤垢欲倾塌，足手皴一寸厚，使人终夜恶。”不是抽象的“负心”，而是一个富家女对一个贫贱男的细致回忆。“我岂不能起楼宇、买良沃，念汝儇薄骨、乞丐相，终不是白头侣”，写出她其实有能力，选择不是能力问题，而是人品。","结局写得非常冷：“身坐削壁上，俯瞰绝壑，深无底”，“腹受枯，手足无着”，樵人把他“缒而下”，“腰肿溃为癞”，“里党薄其行，悉唾弃之”。他最后杀了当年劝他卖妻的人，被捕，“寻瘐死”。作者没有给他一个悔过的瞬间，只让他按着既有的轨迹走到底。"],"notes":[["乐籍","官府登记的乐户、歌妓名册"],["缗","成串的铜钱"],["豺鼠子","豺狼、老鼠一样的东西，骂人语"],["儇薄","轻佻浅薄"],["香火情","一同烧香的交情，指夫妻缘分"],["削壁","陡峭的山壁"],["缒","用绳子吊着放下去"],["溘毙","突然死去"],["里党","同乡的人"],["瘐死","囚犯在狱中病饿而死"]],"think":["翠仙为什么选择让梁有才自己先“做错”，再惩罚他？","因为她要的是确证：她“固知郎不义”，但想在行动上让所有人看到。让他自己签约，使惩罚变得不可辩驳。边界是：她所用的计谋近于“钓鱼”，在今天的法律语境里并不严谨，作者写的是道德审判。"],"quiz":[["翠仙为什么说“以妾鬻贵家，两所便益”？",["诱他签下卖妻契约，暴露其恶","她真的想卖身","她爱慕富人"],"她“故愕言”，“固言之，色作庄”，把他的恶念引出来。"],["翠仙骂梁有才的主要罪状是？",["贪赌、轻薄，甚至想卖她为娼","懒惰","不孝"],"“鬻妻子已大恶，犹未便是剧；何忍以同衾人赚作娼！”"],["梁有才最后的结局？",["杀人入狱，瘐死","发迹","出家"],"“遂被收，官廉得其情……系狱中，寻瘐死。”"]],"cards":[["“以善规人，如赠橄榄”是什么意思？","善意规劝，像送橄榄，入口苦涩，回味甘甜。"],["“以恶诱人，如馈漏脯”呢？","诱人为恶，像送腐肉，吃了送命。"]],"line":["我岂不能起楼宇、买良沃，念汝儇薄骨、乞丐相，终不是白头侣","有些合作伙伴能力很强，但我知道他儇薄骨、乞丐相，终不是白头侣。"],"tags":["负心","赌博","报应"]},"liaozhai_dalijiangjun":{"intro":"查伊璜在寺里看见一个乞丐能单手举起大钟，吃饭相当于五六人，就劝他从军，赠他五十金。十几年后，那乞丐成了吴将军，盛礼迎他，行君父之礼，又把所有婢仆家产一半相赠。再后来查因“修史一案”被株连，赖将军之力得免。篇名“大力将军”，写的是大力，更是大恩。","focus":["寺中一幕交代了乞丐的奇力：“古钟，大于两石瓮……使数人抠耳，力掀举之，无少动”，乞儿“以一手起钟，一手掬饵置筐内”。他之所以要饭，是因为“啖噉多，无佣者”。作者用最简洁的方式写出“力”与“饿”的矛盾，也写出了查伊璜的眼光。","吴将军的报恩写得郑重：“朝拜，如觐君父”“先命数人按查座上不使动”。他让侍女“捧朝服”，让人“按住”恩人受拜，礼之重近乎夸张。随后“投辖下钥，锢闭之”，把客人锁住，按籍点数家产，“敢以半奉先生”。这段把豪爽写得近乎喜剧。","异史氏的判断是：“厚施而不问其名，真侠烈古丈夫哉！而将军之报，其慷慨豪爽，尤千古所仅见。”两者对举，既赞查，也赞吴。最后一句“两贤之相遇，非偶然也”，说明作者更重“识人”与“知恩”这对关系。"],"notes":[["抠耳","提起钟耳（钟顶的环）"],["糗糒","干粮"],["投辖下钥","把车辖投入井中、锁上门，指强留客人"],["犹子","侄子"],["投刺","递名帖求见"],["行伍","军队"],["伛偻","弯腰恭敬的样子"],["朝服","上朝穿的礼服"],["藏镪","收藏的钱财"],["修史","编修史书"]],"think":["吴将军报恩时，把自己的一半家产相赠。你觉得这是“慷慨”还是“夸张”？","在故事里它是慷慨，也是作者借极端化的方式强调“恩情”的重量。边界是现实里这样做难以持续，不过故事要写的是人心而不是账本。"],"quiz":[["查伊璜为何注意这位乞丐？",["他单手举钟，且食量惊人","他会读书","他长得高大"],"“以一手起钟”，“计其食，略倍五六人”。"],["吴将军报恩的方式？",["行君父之礼，并以一半家产相赠","送一封信","荐官"],"“朝拜，如觐君父”，“敢以半奉先生”。"],["异史氏的评价是？",["厚施不问名，报恩慷慨，皆为古丈夫","查贪财","吴过分"],"“厚施而不问其名，真侠烈古丈夫哉！”"]],"cards":[["“大力将军”的“大力”指什么？","吴将军早年单手举钟的力气。"],["查伊璜赠乞丐多少钱？","五十金。"]],"line":["厚施而不问其名，真侠烈古丈夫哉","他帮过的人遍布各地，却从不提，真是厚施而不问其名，真侠烈古丈夫哉。"],"tags":["报恩","侠义","武将"]},"liaozhai_kaobisi":{"intro":"闻人生病中被一个秀才鬼引到阴间的“考弊司”，求他向鬼王说情，免去新鬼例须割大腿肉的“规矩”。鬼王拒绝，闻人生愤而诉到阎罗，鬼王受罚，他自己却因一时贪欢，在烟花巷里被两个牛头鬼“花夜叉”骗住。这篇用阴间的“例”写了一个讽刺：一套明知不合理的规矩，靠“成例”存在，靠“贿赂”豁免。","focus":["考弊司的布置是篇的锚点：堂下两碣刻着“孝弟忠信”“礼义廉耻”，楹联写“曰校、曰序、曰庠……上士、中士、下士，一堂礼乐鬼门生”。教化的招牌与割肉的刑罚并置，对比强烈。后世读者常把这里读作对学官索取生员财物的讽刺，但文中没有直接点明，只写“例”。","鬼王的形象很典型：“鬈发鲐背，若数百年人”，“鼻孔撩天，唇外倾，不承其齿”，从者是“虎首人身”。当闻人生开口，他“色变曰：此有成例，即父命所不敢承”，把规矩抬到“比父命还大”的位置。这是制度压人的一句话。","闻人生仗义，自己却败在“欲”上：他在曲巷里与柳氏秋华缠绵，临别时“囊橐空虚”，“暂解衣为质”，窥见两人“自肩以上化为牛鬼”。作者没有嘲笑他，只写“历两昏晓，凄意含酸，响肠鸣饿”，让他吃了苦头，也让读者看到义愤与自制不是一回事。"],"notes":[["缓颊","替人说好话"],["割髀肉","割大腿上的肉"],["栲栳","用柳条编的圆斗，形容字大"],["鲐背","背上生斑如鲐鱼，指高龄"],["徽纆","绳索"],["考弊司","篇中阴司衙门名"],["曲巷","烟花巷"],["夜度娘","夜里陪客的女子"],["花夜叉","对娼妓的蔑称"],["鬼王","阴间掌管者"]],"think":["鬼王说“此有成例，即父命所不敢承”，你怎样看这种“成例”的力量？","它是一种自我保护：把规则说成不可违，就不必为后果负责。边界是故事里“成例”最终仍被阎罗推翻，说明规则也受更高权威的制约，作者对制度并不完全绝望。"],"quiz":[["秀才鬼为什么求闻人生？",["新鬼例须割髀肉，他想求免","想借钱","想还阳"],"“初见之，例应割髀肉，浼君一缓颊耳。”"],["闻人生在阴司的结局？",["使鬼王受罚，却被曲巷鬼骗住","获封官","升天"],"他告赢鬼王，却因贪恋曲巷而被“花夜叉”所困。"],["“花夜叉”指什么？",["烟花女，变为牛鬼","夜叉鬼","女官"],"“自肩以上化为牛鬼，目睒睒相对立”。"]],"cards":[["考弊司门前的两块碑刻什么？","“孝弟忠信”“礼义廉耻”。"],["鬼王的外貌特点？","鬈发鲐背，鼻孔朝天。"]],"line":["此有成例，即父命所不敢承","每次听到“这是惯例”，我都想起一句话：此有成例，即父命所不敢承，然后问一句，谁定的例。"],"tags":["阴司","讽刺","规矩"]},"liaozhai_xianggao":{"intro":"向杲的兄长向晟因娶妓女波斯，被豪强庄公子活活打死。向杲诉讼无门，天天带刀伏在山径里要杀庄公子，庄公子也请了射手焦桐保护。一场暴雨之后，向杲被道士赠一件袍，穿上后变成老虎，咬死了庄公子，自己也被射死，魂魄归身，复活。这是《聊斋》的复仇篇，异史氏最后一句“恨不令暂作虎”，是全篇的情绪出口。","focus":["冤情写得极简：“晟不服，遂嗾从人折箠笞之，垂毙，乃去。杲闻奔视，则兄已死。”随后“具造赴郡，庄广行贿赂，使其理不得伸”。几行字，把官司的结局写尽：有钱有势的人，不必辩白。","转虎的细节很精：道士先送布袍，“杲易衣，忍冻蹲若犬，自视，则毛革顿生，身化为虎”。没有咒语，没有仪式，只是穿上一件衣服，就换了身份。这里的“衣”既是法器，也是社会身份的隐喻：人穿上不同的衣服，就能做不同的事。","复仇的过程极其直接：“虎暴出，于马上扑庄落，龁其首，咽之。焦桐返马而射，中虎腹，蹷然遂毙。”仇报了，人也死了，“杲在错楚中，恍若梦醒”。异史氏说：“壮士志酬，必不生返，此千古所悼恨也。借人之杀以为生，仙人之术亦神哉！”这一句，既赞道术，也为千古义士惜。"],"notes":[["友于","兄弟之情"],["从良","妓女脱离娼籍嫁人"],["嗾","唆使"],["折箠","折断的鞭杖"],["具造","具状，递交诉状"],["山神祠","祭祀山神的小庙"],["毛革","毛皮"],["龁","咬"],["蹷然","忽然倒下"],["焦桐","篇中射手的名字"]],"think":["向杲化虎杀仇，被视为义举，但他也杀了人。你怎样评价这种“正义”？","作者站在受害者一边，承认“足发指者多矣”，但他把复仇安排在“借术”与“舍命”之中，显示这是极端情境的选择，而不是推广的法则。边界是：在现代法治背景下，不能用此为私刑辩护。"],"quiz":[["向杲的兄长为何被打死？",["娶了庄公子看上的妓女波斯","欠债不还","冒犯官府"],"“庄闻，怒夺所好……垂毙，乃去。”"],["道士给向杲什么帮助？",["一件布袍，穿上变虎","一把剑","金钱"],"“乃以布袍授之……毛革顿生，身化为虎。”"],["异史氏最后的感叹是？",["恨不令暂作虎","虎有仁心","兄弟情深"],"“使怨者常为人，恨不令暂作虎！”"]],"cards":[["向杲为何一直伏在山径？","要刺杀庄公子，为兄报仇。"],["焦桐是谁？","庄公子雇来保护的射手。"]],"line":["使怨者常为人，恨不令暂作虎","读到那些久拖不决的冤案，我常想起这一句：使怨者常为人，恨不令暂作虎。"],"tags":["复仇","化虎","兄弟"]},"liaozhai_geyi":{"intro":"邹平张公子爱鸽成癖，一夜遇到白衣少年，自称“漂泊之人”，带他去看自己的鸽子，又送了一对。两年后他把两只白鸽送给父执某公，结果被炖了吃。夜里白衣少年入梦责他“明珠暗投”，所有的鸽子都随之飞去。故事之后又附了两则“暴殄”的小事：一条鱼摆上桌、一壶茶无人赏。三个小故事合起来，是对“识货”的讽刺。","focus":["张公子的“癖”写得近乎病态却可爱：“其养之也，如保婴儿：冷则疗以粉草，热则投以盐颗。”他以十金购一鸽，夜里放进鸽群“使惊诸鸽”，说明“夜游”是为了防它们麻痹而死。越是细节，越见痴。","白衣少年的鸽技是篇中最美的一段：两只白鸽“且鸣且斗，每一扑，必作筋斗”，大者“如鹜”，小者“裁如拳”，学鹤舞，“翼翩翩如燕子落蒲叶上，声细碎，类鼗鼓”。语言轻盈，几乎是舞蹈。结尾“少年化白鸽，大如鸡，冲霄而去”，也写出这位“寓公”的身份。","后半转折：“选二白鸽，笼送之，自以千金之赠不啻也。”某公答“亦肥美”“味亦殊无异处”，公子“大惊曰：此非常鸽，乃俗所言‘靼鞑’者也！”这里的讽刺不是对某公的，而是对“赠礼”的：你以为的珍宝，在别人眼里只是食物。异史氏的叶公好龙、“阿堵之物”之说，更把话题引到“好者聚、贪者散”。"],"notes":[["坤星","晋地所产的鸽种名"],["粉草","甘草的别称，作药用"],["夜游","张公子所称的鸽法，使鸽夜里走动以防麻痹"],["望洋","望见大海而叹，喻自愧不如"],["父执","父亲的朋友"],["明珠暗投","珍贵的东西落到不识货人手里"],["鼎镬","烹煮食物的器具，也是酷刑"],["叶公好龙","假好龙者，真龙来则惧，这里借指"],["阿堵之物","钱的别称"],["靼鞑","鸽的一种，也有说为一类鸽名"]],"think":["张公子送出“千金之赠不啻”的鸽子，结果被吃了。这件事说明什么？","说明礼物的价值取决于接受者的判断。送礼要“知人”：对爱鸽者，鸽是爱物；对食客，鸽只是菜。边界是张公子既没有说明鸽种，也没有试探对方的态度，错在“默认”。"],"quiz":[["白衣少年的真身是？",["白鸽","仙人","书生"],"“回视少年，化白鸽，大如鸡，冲霄而去。”"],["张公子送给某公的鸽子结果是？",["被某公烹来吃了","被养起来","被放生"],"某公答“亦肥美”，公子“惊曰：烹之乎？”"],["后附的两则小事共同点是？",["都写礼物不被识货人珍惜","都写贪财","都写孝顺"],"一尾鱼被端枯，一壶最好的茶被评“甚热”，与送鸽同一笑。"]],"cards":[["“明珠暗投”在篇中指什么？","把珍贵的白鸽送给不爱鸽的人，被烹食。"],["鸽异的“夜游”是什么？","放进鸽群走动，防止鸽子因久睡而麻痹。"]],"line":["物莫不聚于所好","我常说：物莫不聚于所好，所以想要人才，先要有真正的热爱。"],"tags":["鸽","好物","讽刺"]},"liaozhai_lengsheng":{"intro":"平城冷生资质愚钝，二十多岁还读不通一部经，一天有狐来与他同处，他忽得“狂易病”，只要作文就闭门枯坐，忽而大笑，笑完手里已写完一篇。这篇是蒲松龄关于“创作状态”的一则小喜剧，后面附了两个相同气质的短笑话：学师独自一人的笑，和骑驴人的“不遑下骑”。","focus":["冷生的变化写得很快：“少最钝，年二十余，未能通一经”，后来“入泮”“食饩”。作者不写苦读，只写“狐来与之燕处”，让读者去想：是狐点化了他，还是他本来就有的才情被打开了？","“闭门枯坐，少顷哗然大笑，窥之，则手不停草，而一艺成矣。”这几句写出了灵感来临的模样：先枯坐，再大笑，最后一气呵成。蒲松龄自己是个会写文章的人，这里有几分自嘲，也有几分对“才气”的羡慕。","异史氏说：“闭门一笑，与佛家顿悟时何殊间哉！大笑成文，亦一快事，何至以此褫革？如此主司，宁非悠悠！”他为冷生被黜名鸣不平，说主考官“悠悠”，是对科场不近人情的批评。附记的两个小笑话，一个独笑，一个驴伏，与“笑”主题相近，是《聊斋》常见的“笔记补缀”。"],"notes":[["狂易病","精神失常而言行异常的病"],["入泮","考中秀才入学"],["食饩","秀才成绩优异，由官府供给廪米"],["学使","主管一省学政的官员"],["黜","罢免，革除"],["颠草","冷生文集名"],["默温","默默回想"],["蹇劣","瘸而顽劣"],["蹶然","突然倒下"],["不遑","来不及"]],"think":["冷生的“笑”和他的文章是什么关系？","笑是一种释放，把积累的压力与灵感同时打开，使文章一气呵成。作者既写这种状态，也写了它与官场的格格不入：主考官“终日危坐”，容不下这笑。边界是：文中没有解释笑的来源，只写现象。"],"quiz":[["冷生写文章时的特别表现是？",["闭门枯坐，忽然大笑","边走边写","唱歌"],"“则闭门枯坐；少时，哗然大笑。”"],["冷生为何被革除功名？",["在学使面前笑出声被视为失仪","作弊","懒惰"],"学使“怒执之”，后“黜其名”。"],["附记里的宫生的驴有什么特点？",["遇到徒步客，拱手致歉才伏地","遇人就叫","不肯行走"],"“适忙，不遑下骑，勿罪！”驴就“蹶然伏道上”。"]],"cards":[["冷生为何被称为“笑生”？","因每作文必大笑。"],["异史氏如何比喻大笑成文？","与佛家顿悟没有差别。"]],"line":["闭门一笑，与佛家顿悟时何殊间哉","一个团队突然笑起来的时候，往往就是方案想通的时候，闭门一笑，与佛家顿悟时何殊间哉。"],"tags":["科举","狂笑","文思"]},"liaozhai_shanshi":{"intro":"山市是奂山上的海市蜃楼，“邑八景之一”，几年才出现一次。孙禹年与朋友在楼上喝酒，忽见山头出现孤塔，接着宫殿、城墙、楼阁依次出现，又被风吹散，最后只剩一座高楼，窗户洞开，人影往来，慢慢缩小，消失。全篇不到三百字，是《聊斋》写景的代表，没有人物，只有变化。","focus":["叙述顺序是一个“渐”：先是“山头有孤塔耸起”，接着“宫殿数十所”，再“高垣睥睨，连亘六七里，居然城郭矣”，最后“忽大风起，尘气莽莽然，城市依稀而已”。从点到面，从有到无，节奏如电影镜头。","最动人的是“五架窗扉皆洞开，一行有五点明处，楼外天也”的写法：作者不写楼，写窗里透出的天光，“层层指数；楼愈高，则明愈少；数至八层，裁如星点”。用一行行光点来表达高度，既准确又有想象力。","收尾处“楼渐低，可见其顶；又渐如常楼；又渐如高舍；倏忽如拳如豆，遂不可见”，比喻连用，像电梯降落。最后补一句“早行者，见山上人烟市肆，与世无别，故又名鬼市”，把景与民间传说联在一起，使景色多了一层阴影。"],"notes":[["奂山","山东淄川县境内山名"],["山市","山中出现的海市蜃楼般的幻景"],["青冥","青天"],["飞甍","高耸的屋脊"],["睥睨","城上的矮墙"],["缥缈","隐约不清"],["屑屑","琐碎忙碌的样子"],["鬼市","民间对山市的别称"],["孙公子禹年","孙禹年，作者友人"],["孤塔","单独的一座塔"]],"think":["为什么作者不写“山市”的成因，只写景象？","因为他的兴趣在“看”：写出观看的过程，给读者一个视觉体验。边界是：当时没有科学解释，作者以“鬼市”之说收束，保留了未知。"],"quiz":[["山市出现的顺序是？",["孤塔，宫殿，城郭，楼阁，最后只剩高楼","城郭，宫殿，塔","塔，海，船"],"原文依次写孤塔、宫殿、高垣连亘、堂坊，最后“危楼一座”。"],["“五点明处”是什么？",["楼窗透出的天光","星星","灯笼"],"“楼外天也”，用窗口数楼层。"],["山市又叫什么？",["鬼市","仙市","幻市"],"“故又名鬼市云”。"]],"cards":[["山市在哪里？","山东淄川的奂山。"],["山市多久出现一次？","数年恒不一见。"]],"line":["楼愈高，则明愈少","作报告时我会说：楼愈高，则明愈少，层次越多越要看清每一层的光。"],"tags":["写景","幻景","小品"]},"liaozhai_jinheshang":{"intro":"诸城金和尚是被父亲卖进寺院的顽童，师父死后卷款经商，几年暴富，买田置宅，门徒千计，出门前呼后拥，从不念经，不入寺院。他死后，嗣子（买来的养子，后中举人）与门徒瓜分家产，葬礼“倾国来瞻”。蒲松龄不写他的恶，只写他的“派头”，以及对一个时代的锋利嘲笑。异史氏以“和样、和撞、和唱、和障”收尾，是全篇的点睛。","focus":["前半写“富”：“弟子繁有徒，食指日千计，绕里千百亩，悉良沃”；室内“螺钿雕檀为床，床上锦茵褥褶叠厚尺有咫”，客来“十余筵咄嗟可办”。堆叠的数字与器物，使他的身份只剩财富。他“生平不奉一经，持一咒，迹不履寺院”，连僧人的本业都没有。","中段写“势”：“金又广结纳，即千里外呼吸可通，以此挟方面短长”，官员对他“偶气触之，辄惕自惧”。这里写的不是宗教，而是一个有钱有势的“地方实力”，和尚的身份只是壳。","葬礼是全篇的高潮：“殉葬……马千蹄，美人百袂……冥宅楼阁房廊亘数亩”，“会葬者盖相摩，上自方面，皆伛偻入，起拜凡八”。“孕妇痛急欲产，诸女伴张裙为幄”，把场面推到荒诞。异史氏最后一问“金也者，尚耶？样耶？撞耶？唱耶？抑地狱之障耶？”，把“和尚”的四种假冒一次问尽。"],"notes":[["食指","家中需要吃饭的人口"],["甲第","上等宅第"],["僦屋","租房"],["螺钿","用螺壳镶嵌的装饰"],["咄嗟","一会儿，形容快速"],["帖括","科举应试的文章"],["乡荐","乡试中举"],["五蕴皆空","佛教认为色受想行识皆空"],["六尘不染","不被色声香味触法污染"],["和障","指以僧人身份作恶的障碍"]],"think":["金和尚“生平不奉一经”，却人人称他“爷”。这种身份的悖离反映了什么？","反映了社会对“资源”的崇拜超过对“职守”的要求。僧人的身份在这里只剩下一个“称呼”，与信仰无关。边界是作者只写了现象，并未给出改善方案。"],"quiz":[["金和尚发家的方式是？",["卷走师父遗产，经商贩卖","科举得官","受人供奉"],"“后本师死，稍有所遗，金卷怀离寺，作杂负贩……数年暴富。”"],["他的后嗣是？",["买来的养子，后来中举","亲生儿子","弟子"],"“金又买异姓儿，子之……旋援例作太学生……领乡荐。”"],["异史氏的“和样、和撞、和唱、和障”意思？",["对假冒和尚的四种讽刺","四种宗派","四种修行"],"他按“五蕴皆空、六尘不染”的标准，说出四种“似和尚而非”的情形。"]],"cards":[["金和尚为何能“挟方面短长”？","他广结官府，财势惊人。"],["“和障”指什么？","狗苟蝇营、淫赌之类，以和尚之名行恶。"]],"line":["五蕴皆空，六尘不染，是为和尚","评一位“大师”，最后总要回到原点：五蕴皆空，六尘不染，是为和尚。"],"tags":["僧","暴富","讽刺"]},"liaozhai_menglang":{"intro":"白翁梦见去阴间，看到当官的儿子衙署里到处是狼，院里白骨如山，儿子自己要变成虎。梦醒后，儿子的门牙被摔掉，正与梦里被敲掉相合，父亲写信力劝，儿子不听。一年后，儿子遇劫被杀，头被神人续接，还魂，但“目能自顾其背”。篇末附李进士门役假借官长索贿的小故事，主旨是“官虎吏狼”。","focus":["梦境的设计是篇中最有力的一笔：“窥其门，见一巨狼当道……堂上堂下，坐者、卧者，皆狼也。又视墀中，白骨如山。”吃人是常态，“聊充庖厨”四个字，是儿子随口的回答。这种“平静的恐怖”，比血淋淋的描写更重。","儿子的辩解很现实：“弟日居衡茅，故不知仕途之关窍耳。黜陟之权，在上台不在百姓。上台喜，便是好官；爱百姓，何术能令上台喜也？”他不是不明白，而是被制度推着走。作者借此写出了官场逻辑：向上负责，不向下负责。","“目能自顾其背”是异史氏所谓“鬼神之教微”的具体化：被劫之后复生，眼睛能看到自己背后，意思是此后他得时刻自省。最后的“官虎而吏狼”和李进士门役的故事，把批判从一人扩大到“役”，指出清官也会被身边人牵着走。"],"notes":[["走无常","民间说法，替阴司勾魂的人，常指能往来阴阳的人"],["蝉冠豸绣","高官的冠服，蝉冠和獬豸绣服"],["肴蔌","菜肴"],["怔忡","心悸不安"],["黜陟","官员的罢免与提升"],["上台","上司"],["蠹役","贪污的衙役"],["行取","考选地方官入京任职"],["官虎而吏狼","官如虎、吏如狼，比喻残害百姓"],["苞苴","贿赂"]],"think":["儿子说“上台喜，便是好官”，这是官场的真相吗？","这是一种制度性的判断：当考核由上级而非百姓决定时，官员自然对上负责。作者用这句话写出了一个“不得不如此”的借口。边界是：它也是一种自我辩护，因为“上台喜”并不等于必须贪污。"],"quiz":[["白翁梦中见到的景象是？",["衙署里全是狼，院中白骨如山","官员审案","天宫"],"“见堂上、堂下，坐者、卧者，皆狼也。又视墀中，白骨如山。”"],["儿子被劫后怎样？",["头被神人续接，复生，但目能自顾其背","当场死亡","逃脱"],"“即有一人掇头置腔上……移时复苏。”“目能自顾其背”。"],["李进士那件事说明了什么？",["廉官身边的役人也能借势索贿","李进士贪污","富民诬告"],"“官自以为廉，而骂其贪者载道焉。”"]],"cards":[["“官虎吏狼”是什么意思？","官如虎，吏如狼，都是吃人的。"],["“目能自顾其背”有什么象征？","时刻自省，看到自己的背后。"]],"line":["人患不能自顾其后耳","做决策之前，我常提醒自己：人患不能自顾其后耳，要看一看背后留下什么。"],"tags":["官场","梦","批判"]},"liaozhai_wangzian":{"intro":"王子安是个屡考不中的秀才，入场后期待甚切，放榜之日喝醉了，家人为了哄他，假装报马来、赏钱、翰林。王子安在醉中自以为高中，大呼长班，被妻子叫醒，才知一切是胡闹。异史氏借这个狐的恶作剧，写出科举考生的“七似”，是《聊斋》中最幽默也最辛酸的文字之一。","focus":["前半写“醉”中的虚荣：报马来了，他大喊“赏钱十千”；又来人，“汝殿试翰林”，他又喊赏钱。家人“因其醉，诳而安之”，逐渐加码，他却越来越大胆：“大呼长班，凡数十呼。”这一段充满喜剧节奏，同时写出秀才对功名的渴望。","转折是一句：“措大无赖！向与尔戏耳，而真骂耶？”那长班不是人，是狐。王子安上去扑，“落其帽”，醉醒后“得一缨帽如盏大”。作者以这顶帽子为证，让梦与现实相交，既好笑，又让人感到被戏弄的人其实也是被时代戏弄的人。","异史氏的“七似”是文笔高峰：“初入时，白足提篮，似丐。唱名时，官呵隶骂，似囚……出场也，神情惝恍，似出笼之病鸟……忽然而飞骑传入，报条无我，则似饵毒之蝇，弄之亦不觉也。”七个比喻，写尽考生从入场到放榜的状态，是对科举之苦最幽默的总结。"],"notes":[["场屋","科举考场"],["报马","传报喜讯的骑手"],["长班","官员的随从"],["措大","穷书生"],["缨帽","官员的帽子"],["司衡","主考官"],["惝怳","失意恍惚"],["且夫","八股文常用的起首语"],["奚落","讥嘲"],["须臾","片刻"]],"think":["异史氏说“狐之恩与荐师等”，意思是什么？","狐让他在醉中尝到了片刻的得志，就像推荐他的老师给了他一个机会。这是半嘲讽、半同情：得志的滋味不过几刻，狐给了他一次，也是对他长期失意的补偿。边界是：这句话带有苦涩，不是祝福。"],"quiz":[["王子安听到的“报马”是？",["家人哄他的假话","真实的喜报","狐变的"],"“家人因其醉，诳而安之。”"],["长班为何生气？",["王子安骂他“钝奴”","他被打","他要赏钱"],"“措大无赖！向与尔戏耳，而真骂耶？”"],["“七似”里“似丐”指哪个阶段？",["入场时白足提篮","放榜时","归号时"],"“初入时，白足提篮，似丐。”"]],"cards":[["王子安醉后的幻觉是？","他以为自己中进士、点翰林，有长班随从。"],["“似饵毒之蝇”指什么？","发现榜上无名后神色猝变，嗒然若死。"]],"line":["顾得志之况味，不过须臾","读完这个故事，我常说：顾得志之况味，不过须臾，别为一次成绩太久忘形。"],"tags":["科举","喜剧","狐"]},"liaozhai_shiqingxu":{"intro":"邢云飞爱石，得一块“峰峦叠秀”的奇石，每当要下雨，石上“孔孔生云”。被豪强夺去，又意外落入河中，被他找回；一老叟自称是石的旧主，说“出早则魔劫未除”，让他折三年寿换石；后被盗，又被尚书夺去，最后石殉葬，终被盗墓贼取走，在官库中“忽堕地，碎为数十余片”。石与人的关系写得带有宿命色彩。","focus":["老叟与邢云飞争石的一段是篇中最有戏的：叟说“前后九十二窍，巨孔中五字云：清虚天石供”，邢“审视，孔中果有小字，细如粟米”。主人换来换去，不是借此显示神通，而是把“谁拥有”变成一个难题：石有没有主人，谁有资格。","折寿一段设定奇特：“石上窍数，即君寿也。”叟用两指捏窍，使其软如泥，“二三窍已”。物与人的生命相连，爱物的代价是自己的寿。邢“曰：愿”，说明他明白这笔账。","结尾石的碎裂，是全篇的收束：“石忽堕地，碎为数十余片，罔不失色。”官想占为己有，石选择碎了，主人邢子“拾石出，仍瘗墓中”。异史氏说“石与人相终始，谁谓石无情哉？”并引“士为知己者死”，把对石的爱提到对人的知遇。"],"notes":[["孔孔生云","石孔中冒出云气"],["踵门","亲自登门"],["悬金署约","悬赏并署名立约"],["清虚天石供","石上的刻字，意为清虚天的石供"],["魔劫","修行中遇到的灾难"],["报国寺","北京报国寺，当时有集市"],["海岱门","北京崇文门的旧称"],["昧爽","天将亮"],["瘗","埋葬"],["士为知己者死","语出战国策等，为知己而死"]],"think":["邢云飞为石愿意折寿、愿意坐牢，你觉得这是“痴”还是“明”？","两者兼有：他对石的爱是“痴”，但他清楚自己为石付出了什么，所以也是“明”。作者让石也有选择，这就使这场爱不是单向的占有，而是互相认定。边界是：蒲松龄在异史氏中直说“亦痴甚矣”，保留了保留态度。"],"quiz":[["老叟怎样证明石是自己的？",["说出石上有九十二窍及刻字","出示契约","请官府判断"],"“前后九十二窍，巨孔中五字云：清虚天石供。”"],["邢云飞为何折寿？",["为留下石头，须减三年寿数","为石治病","为官府罚款"],"“既欲留之，当减三年寿数”，“石上窍数，即君寿也”。"],["石最后怎样了？",["在官库中坠地碎裂，邢子拾碎石仍葬墓中","被毁","被送回"],"“石忽堕地，碎为数十余片……仍瘗墓中。”"]],"cards":[["石上的字？","“清虚天石供”。"],["异史氏的评语？","物之尤者祸之府；石与人相终始。"]],"line":["天下之宝，当与爱惜之人","一件作品，要交给真正懂它、爱它的人：天下之宝，当与爱惜之人。"],"tags":["石","痴","知己"]},"liaozhai_jiuchong":{"intro":"长山刘氏体肥嗜酒，一天能喝一瓮，家里有三百亩田，一半种黍，他自己并不为此发愁。一个番僧看出他“有异疾”，用酒香引诱出他喉中的“酒虫”，并讨去。刘氏从此“恶酒如仇”，身体渐瘦，家境渐衰。这篇仅二百多字，却留下一个耐人寻味的问题：虫是病，还是福？","focus":["僧人治病的方法很直观：“令于日中俯卧，缚手足；去首半尺许，置良酝一器。移时，燥渴，思饮为极。酒香入鼻，馋火上炽，而苦不得饮。”不用药，用诱，写得几乎像催眠。接着“咽中暴痒，哇有物出，直坠酒中”，一系列动作紧凑。","酒虫的形状写得具体：“赤肉长三寸许，蠕动如游鱼，口眼悉备。”僧人说“此酒之精，瓮中贮水，入虫搅之，即成佳酿”，这是故事里的小亮点：虫本身有功能，也说明虫不是纯粹的“祸”。","异史氏的话没有定论：“日尽一石，无损其富；不饮一斗，适以益贫：岂饮啄固有数乎？或言：虫是刘之福，非刘之病，僧愚之以成其术。然欤否欤？”作者只提问，不判断。留下的是对“嗜好”“福气”与“命数”关系的不确定。"],"notes":[["番僧","外国或边地来的和尚"],["异疾","奇怪的病"],["酒虫","嗜酒者体内的虫"],["良酝","好酒"],["蠕动","慢慢爬动"],["佳酿","好酒"],["饮啄","饮水啄食，比喻日常享受"],["俯卧","趴着"],["馋火","馋欲如火"],["酬以金","用金钱酬谢"]],"think":["酒虫被除之后，刘氏“体渐瘦，家亦日贫”。你认为作者想说什么？","作者没有给定论，只提示“福”与“病”的边界模糊：嗜酒是病，却也与他的富足与体质相关。或者，作者在借此说明人的“癖好”也许就是他身体与命运的一部分，除去并不一定是好事。边界是：这是一种民间的“命数”观念，不是医学结论。"],"quiz":[["僧人怎样诱出酒虫？",["让刘氏缚手足趴着，面前放好酒，渴极而吐出","用药","念咒"],"“置良酝一器……酒香入鼻，馋火上炽，而苦不得饮。”"],["酒虫的用途？",["放入水中搅动即成佳酿","制药","喂鸟"],"“此酒之精，瓮中贮水，入虫搅之，即成佳酿。”"],["异史氏提出的疑问是？",["虫是刘之福还是病","刘氏是否贪酒","僧人是否有术"],"“或言：虫是刘之福，非刘之病……然欤否欤？”"]],"cards":[["酒虫的形状？","赤肉长三寸，蠕动如游鱼，口眼俱全。"],["刘氏除虫后的变化？","恶酒如仇，身体渐瘦，家境转贫。"]],"line":["岂饮啄固有数乎","不必强求把所有习惯都改掉，岂饮啄固有数乎？要看它与生活的关系。"],"tags":["酒","异事","命数"]},"liaozhai_nongren":{"intro":"一个农人在山下锄地，发现饭罐里的剩粥每天被偷，原来是狐。他用锄头追击，狐头被陶罐套住逃走。数年后，山南一户贵家的女儿被狐缠上，符咒无效，女儿哄狐说出“所畏之人”，正是当年的农人。贵家请农人披戴旧装束入室，一声厉喝，狐便“奉头鼠窜而去”。故事只有三百多字，却有个反差：真正管用的不是法术，而是狐记得的“那顶笠和那把锄”。","focus":["开头写得很生活：农人“芸于山下”，“妇以陶器为饷”，“食已，置器垄畔。向暮视之，器中余粥尽空”。没有鬼魅，只有日常的疑心，这样的写法使狐的出现不突兀。","农人的反应也很实在：“睨注以觇之”，“荷锄潜往，力击之”，狐“器囊头，苦不得脱”，“攧蹶，触器碎落”。作者把一次冲突写得有点滑稽，使狐的恐惧不是来自神威，而是来自一场意外。","后半的反转在于“畏”：狐说“纸上符咒，能奈我何！”“但十年前……被一人戴阔笠，持曲项兵，几为所戮，至今犹悸。”它怕的不是术，而是当年那一把锄头。农人最后“咤曰：我日觅汝不可得，汝乃逃匿在此耶”，一声就把狐吓走，既写农人的朴素，也写出对“民间”的信任。"],"notes":[["芸","同“耘”，除草"],["饷","送饭"],["荷锄","扛着锄头"],["敕勒","用符咒命令"],["阔笠","宽边斗笠"],["曲项兵","弯头的农具，指锄头"],["鼠窜","像老鼠一样逃窜"],["咤","大声怒喝"],["攧蹷","跌倒"],["绐","欺骗"]],"think":["为什么符咒对狐无效，而一个农人的旧装束有效？","因为狐的恐惧来自亲身经历，比抽象的符咒更实在。作者暗示：真正有力量的，往往是让对方记得的“后果”。边界是这类故事偏向民间智慧，不能简单推广。"],"quiz":[["狐为什么偷吃农人的粥？",["觊觎剩粥","寻找食物","报复"],"“器中余粥尽空。如是者屡。”"],["贵家女如何得知狐怕什么？",["哄狐说出所畏之人","请道士占卜","试了各种符咒"],"“女绐之曰……不知生平亦有所畏者否？”"],["农人怎样吓走狐？",["披戴旧装，持锄入室厉喝","念咒","烧符"],"“使披戴如尔日状，入室以锄卓地，咤曰……”"]],"cards":[["狐怕什么？","当年持曲项兵、戴阔笠的农人。"],["“曲项兵”是什么？","弯头的农具，指锄头。"]],"line":["纸上符咒，能奈我何","纸面上的流程再完整，也要问：纸上符咒，能奈我何？真正能管事的是谁。"],"tags":["狐","农人","民间智慧"]},"liaozhai_wuji":{"intro":"淄西人李超好施，一个少林僧人来托钵，教了他三个月武艺。他自以为学成，又被僧人一脚踢倒，于是更加虚心。后来他在济南遇到少年女尼，轻视她，结果被一击伤了腿，也是因为是“憨和尚弟子”才幸免。这篇用两次“被打”，写出“武技无止境”，也写出少年好胜的鲁莽。","focus":["师傅测他的学艺：“可矣。子既尽吾能，请一角低昂。”李“欣然”，结果被“一脚飞掷”，“仰跌丈余”。僧人说“子尚未尽吾能也”。这一句既是教训，也是师傅留的一手，是中国武术故事中常见的“留一手”。","遇尼是第二个转折：尼先“呵止”，说“此少林宗派也”，又“愿拜下风”，直到李“请之再四”，才同意比试。李“以其文弱故，易之；又少年喜胜，思欲败之，以要一日之名”。作者把他的轻敌心理写得清清楚楚：不是不懂，而是想赢。","结局：“尼骈五指下削其股；李觉膝下如中刀斧，蹶仆不能起。尼笑谢曰：孟浪迕客，幸勿罪！”这句“孟浪”与《老饕》的结尾同一句，但这里是客气。后来僧人说“幸先以我名告之；不然，股已断矣”，说明尼是手下留情。"],"notes":[["托钵","僧人持钵乞食"],["少林","少林寺，武术名派"],["低昂","高低，比较高下"],["瑕","破绽"],["骈五指","五指并拢"],["颉颃","不相上下"],["孟浪","鲁莽"],["卤莽","粗率"],["憨和尚","李超师傅的法号"],["仰跌","向后摔倒"]],"think":["李超第二次又被击败，为什么作者强调“少年喜胜”？","因为他把“学成”当作终点，把胜负当作名声。强者往往在不被注意的地方出现，轻敌就是自己的破绽。边界是：故事里他之所以伤得不重，是因为老僧的名字，说明武林里仍重辈分与礼数。"],"quiz":[["僧人为何说“子尚未尽吾能”？",["他一脚把李踢倒，仍留有后手","他对李不满","李学得太快"],"“僧忽一脚飞掷，李已仰跌丈余。僧抚掌曰：子尚未尽吾能也！”"],["女尼发现李超来历的方式是？",["一交手便看出少林宗派","他报了名字","旁人告知"],"“才一交手，尼便呵止，曰：此少林宗派也。”"],["李超受伤后师傅怎么说？",["幸先以我名告之，不然股已断矣","你练得不够","你自己活该"],"“汝大卤莽！惹他何为？幸先以我名告之；不然，股已断矣！”"]],"cards":[["李超的师傅是谁？","少林寺的憨和尚。"],["女尼的出手？","五指并拢下削其股。"]],"line":["子既尽吾能，请一角低昂","评估自己的真实水平，最好找个能一角低昂的对手：子既尽吾能，请一角低昂。"],"tags":["武艺","谦虚","少林"]},"liaozhai_jiangcheng":{"intro":"高蕃与邻家女江城青梅竹马，婚后才发现她凶悍异常，打骂公婆，鞭打丈夫，甚至逼丈夫拾尘土里的饼吃。高母梦见老叟说这是前世因：江城是和尚养的长生鼠，高蕃前世误杀过它。后来一位僧人念“鼠子缩头去，勿使猫儿寻”，一口清水喷在江城脸上，她从此判若两人。这里选两段：悍妇的横行与僧人点化后的转变。","focus":["第一段写“悍”：高生被打，“奔避父所，茫茫然如鸟雀之被鹯驱者”，江城“横梃追入，竟即翁侧捉而箠之”。公公说“我惟避嚣，故析尔。尔固乐此，又焉逃乎”，连父亲也无计可施。作者让家人都被卷入，把家庭暴力写得带有一种荒诞感。","第二段写转折：老僧“吹鼓上革作牛鸣”，引江城出来，再“吸水噀射女面”，念“莫要嗔，莫要嗔！前世也非假，今世也非真”。这个仪式很朴素，没有神迹，只有一碗水。她回屋后“嗒然若丧，终日不食”，半夜把丈夫拉进被窝，抚摸刀杖痕“嘤嘤啜泣，辄以爪甲自掐，恨不即死”。","转变后的江城“承颜顺志，过于孝子”，“见人，则觍如新妇”，“戏述往事，则红涨于颊”。这些细节使故事有了一点可信：不是人格被改写，而是醒悟后的羞愧。异史氏的“业果”之说，把这归于“前世因”，却也说明作者对家庭暴力的无奈。"],"notes":[["挞楚","鞭打"],["横梃","横握棍棒"],["悻悻","怨恨愤怒的样子"],["钲鼓","锣与鼓"],["噀","含水喷出"],["嗒然","沮丧失意的样子"],["丹诏","皇帝的诏书，这里比喻不敢违抗"],["定省","晨昏向父母请安"],["长生鼠","佛寺里养了长久的老鼠"],["观音咒","念诵观世音菩萨的咒语"]],"think":["江城的转变靠的是“一口清水”和一番话，这在现实里意味着什么？","更像是一种精神上的顿悟：她被某句话击中，看到自己的行为。边界是：故事把原因推给“前世”，这是为了让荒诞合理；但其内核是承认暴力需要外力才能打破，而且需要当事人的自觉。"],"quiz":[["高蕃的母亲梦中得知什么？",["江城是和尚的长生鼠，高蕃前世误杀过","江城是仙女","高蕃欠债"],"“江城原静业和尚所养长生鼠，公子前生为士人，偶游其地误毙之。”"],["僧人宣的偈语核心是？",["前世非假，今世非真，鼠子缩头去","你要行善","你要孝顺"],"“前世也非假，今世也非真。咄！鼠子缩头去，勿使猫儿寻。”"],["转变后的江城怎样？",["承颜顺志，勤俭持家，见人如新妇","依然凶悍","离家出走"],"“女自是承颜顺志，过于孝子。见人，则觍如新妇。”"]],"cards":[["江城的前世？","和尚养的长生鼠。"],["僧人用什么点化江城？","一口清水喷在脸上，并念偈语。"]],"line":["前世也非假，今世也非真","当我被执着的念头缠住，我会对自己说：前世也非假，今世也非真，放一放。"],"tags":["悍妇","因果","佛"]},"liaozhai_meinv":{"intro":"封云亭寓居旅舍，夜里梅女的鬼魂出现，她生前被诬为通奸，含冤自缢。后来有位典史（正是当年诬陷她的人）来找封生，想问冥世姻缘，竟被梅女与鬼老娼联手教训。这里选典史遇鬼的一幕，写得短促而痛快，是《聊斋》“鬼复仇”类型的代表。","focus":["整场戏的设计是“偶遇”：典史某“以问冥世之缘”，请封生招鬼妓，结果来的是“顾氏”（他死去的妻子），却是鬼妓；“某审视，大怒，投以巨碗”。这个“被前妻骗”的反转，既荒诞又讽刺：他自己曾“受贿诬奸”，现在轮到自己的妻“入青楼代偿”。","老娼的骂声最泼辣：“汝本浙江一无赖贼，买得条乌角带，鼻骨倒竖矣！汝居官有何黑白？袖有三百钱，便而翁也！”“乌角带”指官身，“三百钱”是他受贿的价码。把官场的“一钱”写成“便而翁”，既直白又好笑。","梅女的出场则是另一种笔调：“张目吐舌，颜色变异，近以长簪刺其耳。”她没有长篇控诉，只是一簪，随后封生劝“少存投鼠之忌”，她才收手。次夜“某患脑痛，中夜遂毙”，作者只写“痛快！恶气出矣！”，让冤屈与欢快在同一句话里结束。"],"notes":[["典史","明清县级佐官，管缉捕狱囚"],["钱树子","摇钱树，指能赚钱的人"],["乌角带","明清官员的腰带，借指官职"],["投鼠之忌","打老鼠怕伤到旁边的器物，比喻有顾忌"],["长簪","长发簪"],["鼠窜","仓皇逃走"],["鬼囊","盛放魂魄的袋子"],["合卺","新婚夫妇共饮交杯酒"],["昭雪","洗清冤屈"],["受贿诬奸","收受贿赂，诬陷奸情"]],"think":["梅女的复仇是“惩恶”，也是“借力”。你怎样看她对封生的依赖？","她身为鬼，需要一个活人帮她完成最后一步，这说明鬼的世界仍受限制；也说明冤屈的昭雪需要“人”的参与。边界是：这种复仇依旧建立在偶然上，不是制度。"],"quiz":[["典史找封生想做什么？",["问亡妻的冥世姻缘","求诗","借钱"],"“欲以问冥世之缘”，请封生招鬼妓。"],["老娼骂他“三百钱，便而翁”是什么意思？",["他受三百钱就当起大爷","他只有三百钱","他欠三百钱"],"讽刺其受贿，以袖中三百钱就自称“你爸爸”。"],["梅女如何教训典史？",["以长簪刺其耳，次夜他脑痛而死","把他赶走","吓唬一下"],"“近以长簪刺其耳”，“患脑痛，中夜遂毙”。"]],"cards":[["梅女的冤屈？","被典史受贿诬奸，自缢而死。"],["“投鼠之忌”在这里意思？","怕伤及封生，不敢当场杀典史。"]],"line":["少存投鼠之忌","处理对手时我提醒自己：少存投鼠之忌，别因为一个人伤到身边的无辜。"],"tags":["鬼","复仇","官场"]},"liaozhai_qinge":{"intro":"霍桓十三岁还分不清叔伯，却爱上了邻家女青娥，母亲央媒被拒。道士赠他一把能穿墙的小铲，他半夜穿两重墙进入青娥房中，伏在榻侧睡去，被发现时，他只是“腼然不作一语”，说“我非贼，实以爱娘子故，愿以近芳泽耳”。这一幕是《聊斋》最天真的情节，笔调轻快，看点在“痴”。","focus":["霍桓出场的“呆”是故事的底色：“年十三，尚不能辨叔伯甥舅焉。”因此他穿墙进房的行为，只能是出于不明世事的本真，而不是淫邪。作者先写出他的“不懂”，所以后面的“荒唐”变成“可爱”。","穿墙一段几乎是传奇的缩影：“历试砖石，略无隔阂。顿念穴墙则美人可见，而不知其非法也。”“穿墉入，女已熟眠。轻解双履，悄然登榻；又恐女郎惊觉，必遭诃逐，遂潜伏绣褶之侧。”他想的是“只看看”，结果“少一合眸，不觉睡去”。这个“睡着了”是全篇的笑点。","被发现之后，青娥“俛首沉思，意似不以为可”，众人替他圆场：“此子声名门第，殊不辱玷……不如纵之使去，俾复求媒焉。”霍桓“觑枕边，有凤钗一股，阴纳袖中”，被婢子看见，“女不言亦不怒”。这一细节暗示青娥对他并不真的反感，最后“莫道他騃若，意念乖绝也”，一句笑话收束。"],"notes":[["评事","大理寺属官，掌平决刑狱"],["何仙姑","八仙之一"],["委禽","送聘礼求婚"],["斸药","挖药"],["穿墉","穿过墙"],["总角","古代儿童束发成角的样子，指童年"],["腼然","惭愧的样子"],["芳泽","指所爱之人的亲近"],["凤钗","凤形发钗"],["騃","傻，愚笨"]],"think":["霍桓这种“痴”会让人觉得荒唐，也让人觉得可爱。你觉得作者怎样让后者占上风？","通过先写他的“不辨叔伯”，再写他的怯懦与坦白。他并没有任何邪念，只想亲近。边界是：现实里这种行为属于侵扰，故事通过“纯真”的设定淡化了冒犯，这是文学与现实的差异。"],"quiz":[["霍桓靠什么穿墙？",["道士所赠的小镵","符咒","武功"],"“手握小镵，长裁尺许”，“坚石可入”。"],["他在青娥房中做了什么？",["伏榻边，不觉睡去","盗取财物","与她交谈"],"“少一合眸，不觉睡去。”"],["众人为何劝将他放走？",["他门第声名不坏，宜再央媒","怕惹麻烦","同情他"],"“此子声名门第，殊不辱玷。不如纵之使去，俾复求媒焉。”"]],"cards":[["青娥的志向？","慕何仙姑，立志不嫁。"],["霍桓拿走了什么？","枕边的一股凤钗。"]],"line":["我非贼，实以爱娘子故，愿以近芳泽耳","他说得坦白：我非贼，实以爱娘子故，愿以近芳泽耳，反倒让人没法再责备。"],"tags":["痴","爱情","穿墙"]},"liaozhai_xianrendao":{"intro":"王勉才高气盛，爱嘲骂他人，被道士带到仙人岛，遇见桓翁的两个女儿，芳云和绿云。他自称“中原才子”，结果在岛上被才女屡屡嘲讽。这里选两段：初入岛宴席上的“诮辱”，以及后来的“房中良言”。故事是一面镜子：自负的才子遇到比自己更有才的女子，如何被磨去棱角。","focus":["初见一幕：“王初以才名自诩，目中实无千古，至此神气沮丧，徒有汗淫。”桓翁让大家属对：“王子身边，无有一点不似玉。”绿云即答“黾翁头上，再着半夕即成龟”。“王”字旁有“玉”，“黾”字下加“半夕”，绿云抓住一个字音做了刁钻的对答，王勉被嘲却只能“神气沮丧”。","芳云的不留情面：“房中牙签满架，靡书不有，略致问难，响答无穷，王至此，始觉望洋堪羞。”她“语言虽虐”，闺房之内却“相爱好”。她劝王生“纵此不作诗，亦藏拙之一道也”，毫不客气，也是一种很实在的关心。","后一段是一个小喜剧：王生与婢女明珰“绸缪”，“前阴尽缩”，芳云用“无止于楚”的咒语治好他，又用“胸中正，则眸子瞭焉”的反讽调侃。她的才学既是玩笑的材料，也是对丈夫的“教育”。故事用夸张的喜剧写出“才”与“德”的平衡。"],"notes":[["属对","作对联"],["牙签","挂在书上做标记的签子，代指藏书"],["望洋","望洋兴叹，自愧不如"],["藏拙","不显露自己的短处"],["句读","文句停顿处"],["眸子","瞳仁，眼睛"],["方剂","药方"],["东风之吹马耳","比喻听而不闻"],["黄鸟","《诗经》篇名，这里用以咒语"],["明珰","婢女之名"]],"think":["芳云对王勉的“嘲弄”，是羞辱还是教育？","更接近“带刺的教育”。她看出他的自负，用才学压住他，使他“始觉望洋堪羞”。但房帷之内她仍“相爱好”，说明嘲笑的底色是关心。边界是：这种“嘴上不饶人”的方式依赖于关系中的信任，换到别的场合会变成伤害。"],"quiz":[["绿云的对句“黾翁头上，再著半夕即成龟”用了什么手法？",["拆字，添笔","谐音","典故"],"“黾”字加“夕”像“龟”，是拆字加笔画。"],["芳云劝王勉“藏拙”指什么？",["不再作诗","不再喝酒","少说话"],"“纵此不作诗，亦藏拙之一道也。”王大惭，遂绝笔。"],["芳云为王勉治病时说的咒语是？",["黄鸟黄鸟，无止于楚","阿弥陀佛","天灵灵地灵灵"],"“乃探衣而咒曰：黄鸟黄鸟，无止于楚！”王大笑而瘳。"]],"cards":[["仙人岛上嘲讽王勉的是谁？","桓翁的两个女儿芳云、绿云。"],["“藏拙”是什么意思？","不显露自己的不足。"]],"line":["纵此不作诗，亦藏拙之一道也","面对不擅长的领域，我常提醒自己：纵此不作诗，亦藏拙之一道也。"],"tags":["才女","喜剧","自负"]},"liaozhai_husiniang":{"intro":"程孝思是个贫寒书生，被银台胡公选为小女婿。胡家的兄姐和仆婢都看不起他，直到他中进士、做大官，才换了脸色。胡四娘一直沉静寡言，直到被冷落多年后，在兄嫂面前“凝重如故”。篇名是“胡四娘”，写的是四娘，其实是写所有“势利”的人。篇末二郎得救、三娘渐贫，更是对“人情冷暖”的回应。","focus":["对程孝思的轻视是一步步叠起来的：“群公子鄙不与同食，仆婢咸揶揄焉”，“又以鸣钲锽聒其侧”。他“默默不较短长，研读甚苦”，“程携卷去，读于闺中”。一个“去”字，写出了他的不争，也写出了他的清醒。","四娘的形象是通过“不反应”写出来的：“四娘端重寡言，若罔闻之”，“桂儿号哗”时“四娘方绩，不怒亦不言，绩自若”。后来“人见其事事类痴，愈益狎之”。李夫人说她“内慧外朴，聪明浑而不露”，一句话把她的深度点出，也为后来的“凝重如故”做铺垫。","结局的对比特别锐利：程孝思做官后，家人“惴惴，惟恐四娘衔恨不至”，四娘“翩然竟来”，“凝重如故”。二郎遇讼，大郎来求，她冷冷说“我以为跋涉来省妹子，乃以大讼求贵人耶！”拂袖入内，却暗里让丈夫办了事。这既是一次“报复”，也是一次“以德报怨”：她让他们知道，自己并不需要求他们。"],"notes":[["银台","通政使司的别称，指胡公的官职"],["惛髦","昏聩糊涂"],["孽出","庶出，妾所生"],["笄年","女子十五岁，可以插簪的年龄"],["遗才","考试时漏考者的补考"],["庶吉士","翰林院中的候补官员"],["膏火","灯油，代指读书的费用"],["纪纲","仆人头目"],["睚疃","同“睚眦”，指小怨"],["揶揄","嘲笑"]],"think":["四娘最后帮了两个哥哥，却又在他们面前拂袖而去。你觉得她的态度是什么？","是一种有底线的宽厚：她可以施恩，但不愿意被当作“可利用的贵人”。让她拒绝的是对方的“求”，而不是对方的“难”。边界是：作者通过“李夫人亦谓其忍”，同时写出了旁人对这种态度的两种看法。"],"quiz":[["胡公为何愿意把四娘嫁给程孝思？",["看出他“不长贫”","程是亲戚","程家富有"],"“此不长贫，可妻也。”"],["桂儿与春香赌的是什么？",["如果程郎做官，二娘就抉去眼睛","赌钱","赌酒"],"二姊说“程郎如作贵官，当抉我眸子去”，桂儿说“到尔时，恐不舍得眸子也”。"],["四娘怎样对待大郎的求助？",["拂袖而去，却暗中通过丈夫相助","痛快答应","直接拒绝"],"“拂袖径入”，后“程力也”，二郎得释。"]],"cards":[["“内慧外朴”形容谁？","胡四娘。"],["程孝思怎样成功？","得岳父助入学，后入都得李兰台赏识，中进士。"]],"line":["四娘内慧外朴，聪明浑而不露","评价一个人，别只看他说话多不多：四娘内慧外朴，聪明浑而不露，说的就是这种人。"],"tags":["势利","庶女","科举"]},"liaozhai_huanniang":{"intro":"温如春爱琴，在山寺遇一道人学得绝技，又在雨夜遇见赵宦娘，向她求婚被婉拒。后来他爱上葛家小姐良工，因一首“惜馀春”词被误会，几乎失了婚事，最后意外结成佳偶。原来这一切背后，是一位鬼女“宦娘”在默默撮合，她也想学琴。这里选后半段：琴声作怪，镜照鬼魂，宦娘现身。","focus":["全篇的悬念是“谁在暗中帮忙”：词笺、绿菊、女舄，都是巧合，直到“斋童闻琴自作声”，才揭开谜底：“其声梗涩，似将效己而未能者。”这是个很雅的细节：鬼女听琴久了，想学，但还未成。温如春“每夕为奏一曲，而设弦任操若师”，居然让鬼学会了琴。","良工的聪明在于听出“此非狐也，调凄楚，有鬼声”。她取古镜照魅，“伺琴声既作，握镜遽入”，宦娘“仓皇室隅，莫能复隐”。镜子在古人想象里能照出精怪的真形，这个小道具用得自然。宦娘说“代作蹇修，不为无德，何相逼之甚也”，语气里有委屈，也有一点调皮。","宦娘道出自己的心事：“妾太守之女，死百年矣。少喜琴筝；筝已颇能谙之，独此技未有嫡传，重泉犹以为憾。”她的爱不是男女之爱，而是对技艺的执念。“君琴瑟之好，自相知音；薄命人乌有此福”，最后留下一卷自己的小像，教温如春“快意时，焚香一炷，对鼓一曲”，以身受之。"],"notes":[["林下","指退休官员"],["及笄","女子十五岁成年"],["蹇修","媒人，典出《离骚》"],["魑魅","山林中的精怪"],["异物","指鬼"],["重泉","九泉，指阴间"],["嫡传","直系传授"],["儇薄","轻佻浅薄"],["方伯","明清对布政使的敬称"],["惜余春","词牌名，这里指词作"]],"think":["宦娘为什么要帮温如春促成婚姻？","她得到了温如春的琴艺指教，想以此回报，也因听琴而对他生出知音之情。她不求得到，只求成全。边界是：文中说“报眷顾之情”，这既是感恩，也是一种自我满足。"],"quiz":[["良工如何识破宦娘？",["听出琴声“有鬼声”，再用古镜照出","看到她的影子","闻到香气"],"“此非狐也，调凄楚，有鬼声。”“握镜遽入……果有女子在。”"],["宦娘为什么要学琴？",["生前爱琴，死后无嫡传","想做温的妻子","受命于神"],"“独此技未有嫡传，重泉犹以为憾。”"],["宦娘离去前留下什么？",["自己的小像一卷","一把琴","一封信"],"“此妾小像。如不忘媒妁，当悬之卧室。”"]],"cards":[["“蹇修”是什么意思？","媒人。"],["宦娘与温如春的关系？","师徒与暗中的媒人。"]],"line":["代作蹇修，不为无德，何相逼之甚也","她委屈地说：代作蹇修，不为无德，何相逼之甚也，替别人做媒反被怀疑。"],"tags":["琴","鬼","知音"]},"liaozhai_shuchi":{"intro":"彭城郎玉柱继承父亲的书，读书到忘记世事，信“书中自有黄金屋、颜如玉”，真的在《汉书》第八卷里发现一位剪纸美人，后来她变成真人，让他明白读书不全是学问。后来他因妻子失踪被县令追逼，书被焚。篇名“书痴”，既写他的痴，也写“书中有颜如玉”这句话被字面化的荒诞。","focus":["郎玉柱的信念是具体的：“实信书中真有金粟，昼夜研读。”风吹走书卷，他追，踏地陷足，“穴有腐草，掘之，乃古人窖粟，朽败已成粪土”，他不但不失望，反而“益信千钟之说不妄，读益力”。每次失望都被他当作证据，这是“痴”的逻辑。","颜如玉是以典故“落地”：“夫妇一章，尚未了悟，枕席二字有工夫。”她劝他：“君所以不能腾达者，徒以读耳。试观春秋榜上，读如君者几人？”“女乃日与饮博，郎遂乐而忘读。”作者借美人之口讽刺死读书，同时让她用游戏教他琴棋，“倜傥之名暴著”。","收尾的转折是官场与书的冲突：县令“少年进士，闻声倾动，窃欲一睹丽容”，拘人，“见书卷盈屋，多不胜搜，乃焚之，庭中烟结不散”。异史氏的评语是“女之妖，书之魔也”，又说“祖龙之虐，不已惨乎”，对焚书之举直接批判。"],"notes":[["劝学篇","宋真宗《励学篇》，有“书中自有黄金屋，书中自有颜如玉”"],["干禄","求取官俸"],["金粟","指黄金与粮食"],["千钟","千钟粟，语出《劝学篇》"],["观察","清代道员的别称"],["天孙","织女"],["揶揄","嘲笑"],["摴蒱","古代赌博游戏"],["祖龙","秦始皇的别称"],["直指","明清御史巡按的别称"]],"think":["颜如玉劝郎玉柱“不要读”，这是作者的意思吗？","她的话是对“死读书”的批评，不是对读书的否定。作者借她写出“学以致用”的重要，同时让郎玉柱学琴棋，说明才华不只在书里。边界是：结尾焚书一段，作者明确谴责权力对书的毁灭。"],"quiz":[["郎玉柱发现颜如玉的地方是？",["《汉书》第八卷中","书房窗外","旧箱子里"],"“读汉书至八卷，卷将半，见纸剪美人夹藏其中。”"],["颜如玉为什么要走？",["他沉迷读书，不听劝，也恐为他招祸","她想嫁别人","她被追杀"],"“妾从君二年，业生子，可以别矣。久恐为君祸。”"],["异史氏批评的“祖龙之虐”指什么？",["县令焚书","焚毁房屋","伤害书生"],"“祖龙之虐，不已惨乎？”指县令焚书，类似秦始皇焚书。"]],"cards":[["“书中自有颜如玉”在篇中如何落实？","书里夹的剪纸美人化为真人。"],["颜如玉的字？","如玉，姓颜，织女的别号。"]],"line":["书中自有颜如玉，我何忧无美妻乎","读书不是为了得到什么，但他确信：书中自有颜如玉，我何忧无美妻乎，这就是痴。"],"tags":["书","痴","焚书"]},"liaozhai_zhuqing":{"intro":"湖南书生鱼容落第，饿困吴王庙，被吴王招为“黑衣队”的乌鸦，与雌乌竹青结为夫妻，后来中弹受伤，醒来仍是人身。多年后，他再次祭庙，竹青化为汉江神女与他相会，赠他黑衣，使他可以化乌去汉水探望。故事浪漫而奇幻，与《庄子》“化蝶”相仿，却更有人情味。","focus":["乌的世界写得轻快：“舟上客旅，争以肉饵抛掷，群于空中接食之，因亦效尤。须臾果腹，翔栖树杪，意亦甚得。”他本是饿肚子的书生，化乌后反而轻松自在。竹青“恒劝谏之”，他“终不能听”，是一个贪嘴的小毛病，也是后来受伤的伏笔。","竹青的形象很有分寸：他受伤时“竹青衔去之”“摄饵哺鱼”，是患难夫妻。多年后重逢，她说“妾今为汉江神女，返故乡时常少。前乌使两道君情，故来一相聚也”。她不是被动的，而是主动前来，且有自己的处境，不能同南同西，只能“置妾于此，为君别院”。","最美的是“衣黑衣可至”的设计：“君旧衣尚在，如念妾时，衣此可至，至时为君解之。”鱼容“两胁生翼，翕然凌空”，飞到汉水，“羽毛划然尽脱”。这件黑衣既是身份的变形，也是情感的信物。他生活在凡间与神界之间，既有人间的妻子，也有神女的家。"],"notes":[["资斧","旅费"],["少牢","羊、猪二牲的祭祀"],["无机","没有机心，指无防备"],["汉江神女","汉水的女神"],["黑衣","乌鸦的羽衣"],["胎衣","胎儿的包衣"],["临蓐","临产"],["擗踊","捶胸顿足，极度悲哀"],["郡庠","府学"],["缓结","解开衣结"]],"think":["竹青说“君家自有妇，将何以处妾乎”，这是理性的拒绝，还是一种委屈？","两者兼有：她明白自己与人间妻的位置，选择在汉水另置别院，既保全体面，也保留情分。边界是：这个安排也反映了作者的时代：一夫多妻的现实被柔化，而竹青的“神女”身份使她有更多自主。"],"quiz":[["鱼容如何变成乌鸦？",["吴王赐他黑衣补黑衣队","喝了药","吃了丹药"],"“黑衣队尚缺一卒，可使补缺。”授黑衣，化为乌。"],["竹青赠他黑衣的作用是？",["让他想念时穿上可飞到汉水","让他化装","让他避祸"],"“如念妾时，衣此可至，至时为君解之。”"],["“汉产”是谁？",["鱼容与竹青的儿子","竹青的哥哥","鱼容的弟子"],"“名之汉产。”"]],"cards":[["竹青的身份？","汉江神女，曾为乌，与鱼容为夫妻。"],["黑衣的作用？","穿上可化乌飞往汉水，回去羽毛尽脱。"]],"line":["如念妾时，衣此可至，至时为君解之","她留给他一件衣服，说：如念妾时，衣此可至，至时为君解之，像一把可以随身携带的钥匙。"],"tags":["神女","化乌","爱情"]},"liaozhai_xiaocui":{"intro":"狐女小翠为报王太常的救命之恩，嫁给他的傻儿子，整天装疯作乱，又靠一个计谋救下全家，最后用一盆热水治好了丈夫的痴病。这里选两段：浴蒸治痴与离去。前半是闹剧，后半是离别。篇末异史氏说狐“有无心之德，而思所报”，反衬身受再造之福者的刻薄。","focus":["治痴一段是最大胆的一笔：小翠“更泻热汤于瓮，解其袍袴，与婢扶入之”，公子“蒙以衾”，“少时，无声，启视，已绝”。她“坦笑不惊”，却对着哭骂的婆婆说“如此痴儿，不如勿有”。这是一次近乎赌博的医治，却是写出她胆识的关键。","婆婆与夫人的反应写得很真实：先“哭而入，骂曰：狂婢何杀吾儿”，转眼“公子呻矣”，“食顷，汗已，忽开目四顾，遍视家人，似不相识，曰：我今回忆往昔，都如梦寐”。一家人从愤怒到惊喜，不过一盏茶，这也是《聊斋》擅长的短时间大转折。","离别一段是小翠的清醒：“请娶妇于家，旦晚侍奉公姑。”她自己“不能产”，怕误了宗嗣，便让位给长得与自己一模一样的钟氏女，并留下“玉玦”。作者没有写她的哭，只写“展巾，则结玉玦一枚”，“始悟钟氏之姻，女预知之，故先化其貌”。“月缺重圆，从容而去”，是对她的最高评价。"],"notes":[["气息休休","呼吸微弱的样子"],["浸淫","渐渐渗透，这里指汗水湿透"],["裀褥","垫褥"],["如获异宝","像得到了奇珍"],["琴瑟静好","夫妻和谐"],["抵死不作茧","宁死也不作茧，比喻不育"],["宗嗣","宗族的继承人"],["纳币","送聘礼"],["玉玦","环形有缺口的玉，暗示决绝"],["破甑","打破的甑，比喻无可挽回之事"]],"think":["小翠为何要为丈夫选一个与自己长相相同的新妇？","这是她的体贴：她知道自己要离开，所以让自己的“影”继续陪伴。这种安排既保全了王家的宗嗣，又保留了对他的情感。边界是：这也是男权社会中“女子为夫家安排”的一面，作者借狐写出一种柔和的牺牲。"],"quiz":[["小翠怎样治好公子的痴病？",["用热水蒸他，令他昏死又醒来","给他吃药","念咒"],"“更泻热汤于瓮……以衾蒙之。少时，无声，启视，已绝……忽开目四顾……”"],["小翠为何离开？",["她不能生育，且已为公子安排新妇","被夫人赶走","被道士收伏"],"“妾实不能产，恐误君宗嗣。请娶妇于家。”"],["异史氏批评的是谁？",["身受恩惠而对破甑失声的人","小翠","公子"],"“身受再造之福者，顾失声于破甑，何其鄙哉！”"]],"cards":[["小翠的真身？","狐，报王太常救命之恩。"],["“玉玦”在文中是什么暗示？","决绝、不返。"]],"line":["月缺重圆，从容而去","项目结束了，她不拖泥带水，月缺重圆，从容而去，留给别人的是体面。"],"tags":["狐","报恩","喜剧"]},"liaozhai_xiliu":{"intro":"细柳娘嫁给高生，做了前妻之子长福的继母，后来生了亲子怙。她对长福苛刻，让他穿破衣放猪，引来邻里议论；对亲子怙却宠，却让他受罚、受监管。结局是长福中举登第，怙做生意致富，也被母亲严厉管束，成为有用的人。篇末异史氏的评语既为细柳辩护，也批评世间“矫枉过正”的继母。","focus":["教子一段：先是“怠情不肯读，辄亡去从牧儿遨”，母亲没有打骂，而是“可更若衣，便与僮仆共操作”，让他放猪，“归则自掇陶器，与诸仆啖饭粥”。他“泣跪庭下，愿仍读”，她“返身向壁，置不闻”。严厉得几乎冷酷，但每一步都是计划好的，这是教育，不是惩罚。","邻里议论她“啧有烦言”，她“漠不为意”。这是篇的核心张力：继母的名誉与孩子的前途。细柳选择了后者，付出的代价是外人的指责。“女亦稍稍闻之，而漠不为意”，写得很淡，却分量很重。","怙的教育是另一面：“母令弃卷而农。怙游闲惮于作苦。母怒曰：四民各有本业……立杖之。”她对亲子同样严厉，还“衣服饮食，母辄以美者归兄”，亲子“心窃不能平”。异史氏的“黑心符出，芦花变生”，借闵子骞的故事（后母以芦花衣待之）说古今继母多被怀疑，而细柳“不引嫌，不辞谤”，把两个儿子都培养成才。"],"notes":[["夏楚","古代的体罚工具，也指鞭打"],["牧豕","放猪"],["游泮","考中秀才入学"],["四民","士农工商四种人"],["沟瘠","死于沟壑"],["淫赌","沉迷赌博"],["黑心符","指后母虐待前子之说，具体典故存疑"],["芦花","闵子骞后母以芦花为其做衣的故事"],["一丘之貉","同一个山丘的貉，比喻同类"],["铮铮","形容刚强正直"]],"think":["细柳对长福严格，对亲子也严格。为什么外人仍指责她？","因为继母的身份天然受猜疑：对前子严厉被看作虐待，对亲子严厉则无人评论。异史氏说“日挞所生，而人不以为暴；施之异腹儿，则指摘从之”。边界是：这并不是说严厉本身一定正确，而是说评价标准有偏。"],"quiz":[["细柳让长福放猪是为了什么？",["让他知苦改悔，重新读书","惩罚他","节省开支"],"“苦之，泣跪庭下，愿仍读。”她后来让他重新入学。"],["怙最终的结局？",["经商致富，被母亲严格管束","当官","出家"],"“弟货殖累巨万矣。”"],["异史氏如何评价细柳？",["不引嫌，不辞谤，使二子一富一贵","对长福太苛","偏爱亲子"],"“而乃不引嫌，不辞谤，卒使二子一富一贵，表表于世。”"]],"cards":[["“四民各有本业”指什么？","士农工商。"],["细柳为什么不辩解？","她认为教育的结果比名声更重要。"]],"line":["不引嫌，不辞谤","带团队有时必须不引嫌，不辞谤，先把事做成，再让时间说话。"],"tags":["继母","教子","世情"]},"liaozhai_juzha":{"intro":"副将军某携重金入京，想谋一个将军实缺，苦无门路。一个骗子说他的内兄是天子近侍，只要签字，将军之位唾手可得；某被引入“朝堂”，见天子、受封，高枕待授，结果被兵部告知缺已有人，自己还被下狱，花了万金才免。这篇是《聊斋·局诈》三则骗局之一，写“官场骗局”最直白的一段，结尾“岂朝门亦可假”，既是惊叹，也是对官场的讥讽。","focus":["骗局的第一步极简：“某处将军缺，倘不吝重金，仆嘱内兄游扬圣主之前”，“言定如干数，署券为信”，“不效，则汝金尚在”。骗子的话每一句都“合理”：先不收钱，只要签字，还说“既能予之，宁不能夺之耶”。这种“后付费”的设计，是真实骗局的典型。","第二步是“戏”：“逾两日，日方西，数人吼奔而入，曰：圣上坐待矣！”某“疾趋入朝”，见“爪牙森立”的天子，“慰问殷勤”，“侯封有日耳”。作者没有写这场“朝见”的机关，只写某的体验，所以读者与他一样被带入。","收尾是冷的：“探访之，则前缺已有人矣。大怒，忿争于兵部之堂……述宠遇，半如梦境。司马怒，执下廷尉。”“朝中并无此人。又耗万金，始得革职而去。”最后作者自问“武弁虽騃，岂朝门亦可假耶？”并猜测“中有幻术”，既是讽刺，也暗示官场之难辨真假。"],"notes":[["握篆","掌权，担任官职"],["游扬","四处宣扬，推荐"],["署券","在契约上签名"],["叵测","不可测度"],["兑付","兑现支付"],["廷尉","古代掌管刑狱的官，这里指法司"],["踟蹰","犹豫不前"],["锱铢","极小的数量"],["武弁","武官"],["矛弧","矛与弓，指兵器"]],"think":["为什么这一骗局看起来“合理”？你怎样识别类似的陷阱？","它抓住了两点：对方先让你相信“成功后再付”，再用“权力场景”制造真实感。识别方法是看是否要求提前签字、是否让你无法核实对方身份。边界是文中的骗局有“幻术”的成分，现实中也许是预先布置的戏班。"],"quiz":[["骗子的承诺是什么？",["事成后再付款","先付一半","免费"],"“待召见后，方求实给；不效，则汝金尚在。”"],["副将军受骗后怎样？",["争于兵部被下狱，再耗万金革职","升官","逃走"],"“司马怒，执下廷尉……又耗万金，始得革职而去。”"],["作者最后的疑问是？",["朝门亦可假吗","骗子是谁","官员是否知情"],"“武弁虽騃，岂朝门亦可假耶？”"]],"cards":[["《局诈》写的是什么？","连环骗局，借官场、商场、艺术的“局”写人心。"],["署券为信的作用？","让受害人心理上以为有保障。"]],"line":["不效，则汝金尚在","遇到“不成不收费”的承诺，我会反问：不效，则汝金尚在，那你的成本从哪里来？"],"tags":["骗局","官场","世情"]},"liaozhai_change":{"intro":"宗子美从父游学，娶了红桥下林媪家的女儿嫦娥，又与西邻狐女颠当私通。颠当被嫦娥识破，又被收服，成为宗家的妾。这里选两段：宗子美自缢，嫦娥将他救回，并制服颠当；以及颠当学“西子捧心”、扮观音的闹剧。整篇像一出喜剧：嫦娥端正，颠当调皮，宗子美夹在中间，被两位女子“管”着。","focus":["第一段是“救命”：宗子美“解带自缢，恍惚觉魂已出舍，怅怅靡适”，嫦娥“捉而提之，足离于地”，推回身体，叫道“痴郎，痴郎！嫦娥在此！”作者用“提”这个动作，写出她既是妻又是仙，有从容的力。","对颠当的惩戒也带着幽默：“君背嫦娥，乌得颠当？请坐待之，当自至。”颠当到后“仓皇伏榻下”，嫦娥“叠指弹之”：“小鬼头陷人不浅！”再罚她“绣枕百幅、履百双”。宗子美为她“缓颊”，才免。人狐之间的“管教”写得极有分寸。","第二段是颠当的“调皮”：“凝妆作己状”，被嫦娥“哂而退”，随后颠当“心暴痛”，嫦娥说“我岂医巫厌胜者？汝欲自捧心效西子耳”。她再扮龙女、扮童子拜，“袜能磨乎其耳”，嫦娥“解颐”，却在一瞬间“媚情一缕”，立刻呵斥。这一段写出了狐的“媚”与仙的“定”之间的张力。"],"notes":[["靡适","不知往哪里去"],["缓颊","替人说情"],["赊死","求缓死"],["广寒","月宫，广寒宫"],["厌胜","用巫术镇压或诅咒"],["捧心","西施捧心，美人病态的姿态"],["瓠犀","瓠瓜的籽，形容牙齿整齐洁白"],["趺坐","盘腿而坐"],["媚情","勾人的媚态"],["夙根","前世的根基，慧根"]],"think":["嫦娥一方面严厉制服颠当，另一方面又默许她存在。你怎样理解这种态度？","她看重的是“规矩”与“分寸”，而不是消灭对手：既惩戒，也给她留位置。边界是故事里的“妻妾”关系被写得轻松，是作者的想象，不代表现实的妻妾关系。"],"quiz":[["嫦娥怎样救宗子美？",["提着他的魂魄入寺，推进身体","请医生","念咒"],"“入寺，取树上尸推挤之，唤曰：痴郎，痴郎！嫦娥在此。”"],["颠当是什么身份？",["西山的狐","嫦娥的姐姐","邻家女"],"“乃知其西山狐也。”"],["嫦娥为何呵斥颠当？",["颠当用媚术扰乱她的心神","颠当偷懒","颠当冲撞客人"],"“忽觉媚情一缕……意荡思淫，若不自主……狐奴当死！”"]],"cards":[["嫦娥罚颠当做什么？","绣枕百幅、履百双。"],["“捧心”指什么？","西施病时捧心的姿态。"]],"line":["君背嫦娥，乌得颠当","她一眼就看穿对方的谎言，语气平静：君背嫦娥，乌得颠当。"],"tags":["狐","仙","夫妻"]},"liaozhai_siwenlang":{"intro":"平阳王平子赴试，寄居报国寺，与才子宋生交好，又与狂傲的馀杭生不合。他们在庙里遇到一位瞎和尚，号称“以鼻论文”：焚烧文章，用鼻子闻就能判断高下。结果馀杭生考中，而宋生、王平子落第，瞎和尚说“我虽盲于目，而不盲于鼻；帘中人并鼻盲矣”。这是《聊斋》对科场最辛辣的讽刺之一，笑中带泪。","focus":["瞎和尚的评文方式荒诞而精彩：“每焚一作，僧嗅而颔之曰：君初法大家，虽未逼真，亦近似矣。我适受之以脾。”脾、心、鬲、膀胱，用不同脏腑来“受”文，把“文气”写成了生理感受。读来既荒唐又可信。","对馀杭生的处理最有戏：他先以古大家文试，僧说“妙哉！此文我心受之矣，非归、胡何解办此”，再焚己作，僧“咳逆数声”，“格格而不能下，强受之以鬲；再焚，则作恶矣”。“非归、胡”指明代八股名家归有光、胡友信，是用名家来对照其平庸。他最后考中，让瞎和尚仰天长叹。","宋生对王平子的安慰是篇的暖点：“凡吾辈读书人，不当尤人，但当克己：不尤人则德益弘，能克己则学益进。”他自己是鬼，却劝活人要“砥砺”，又指点“舍后有窖镪”。王平子答“昔窦、范贫而能廉，今某幸能自给，敢自污乎？”，体现了读书人的清操。"],"notes":[["瞽僧","盲眼的和尚"],["以耳代目","用耳朵代替眼睛"],["大家","指有名的文章大家"],["嗅","用鼻子闻"],["窖镪","窖藏的银钱"],["薪桂米珠","柴像桂木、米像珍珠，形容物价极贵"],["克己","约束自己"],["资斧","路费"],["刺于鼻","刺激鼻子"],["自污","自己玷污名节"]],"think":["瞎和尚说“帘中人并鼻盲矣”，这对科场有什么指向？","指向主考官的失察：他们既没有识人之能，又自以为是。作者借瞎僧的话，让读者看到评价体系本身可能出错。边界是：故事里的“鼻”是荒诞设定，但反映的是真实的科场不公感。"],"quiz":[["瞎和尚评文用的是什么方式？",["焚文后以鼻闻","读出声","用手摸"],"“不如焚之，我视以鼻可也。”"],["馀杭生的文章被和尚评为？",["“格格而不能下，强受之以鬲”","妙品","佳作"],"“僧嗅其余灰，咳逆数声，曰：勿再投矣！”"],["宋生劝王平子的核心是？",["不尤人，克己砥砺","报复","放弃"],"“不尤人则德益弘，能克己则学益进。”"]],"cards":[["“非归、胡何解办此”中的“归、胡”？","明代八股名家归有光、胡友信。"],["宋生的真实身份？","鬼，生前曾是文人。"]],"line":["不尤人则德益弘，能克己则学益进","遇到不顺，我先读一遍：不尤人则德益弘，能克己则学益进，再看下一步。"],"tags":["科场","讽刺","鬼"]},"liaozhai_cuimeng":{"intro":"崔猛勇而暴，被母亲约束，后来仆人李申被他救出，成为他的家臣。土寇来袭，抢走崔妻，崔猛不在，李申独自潜入敌营，设计救出，又在隘口设伏，大败来犯之敌。这是《聊斋》少见的军事小品：写一个小人物如何以智取胜。","focus":["李申的救人写得极具细节：他“断绳数十段”，让仆人在山上点火，“散挂荆棘”；自己“效其装”，“缚驹跨马”，用母马的“恋驹”来引路。每个细节都是真实可操作的计策，不是空想的神勇。","对话里李申的解释很明白：“设火于东，恐其西追也；短，欲其速尽，恐侦知其无人也；既而设于谷口，口甚隘，一夫可以断之，彼即追来，见火必惧：皆一时犯险之下策也。”他把计划里的缺陷都说出来，说明他谋事不求万全，只求险中取胜。","战术是“空间”：置炮于隘口，伐树断归路，两岸伏击，“枕藉沟中”。“遣二十余人，长跪乞命”，“二十余贼，尽劓刖而放之”，写出了战场的冷。最后“威声大震，遂得土团三百余人”，一人之计成就了一方安宁。"],"notes":[["土寇","地方的盗匪"],["啸聚","聚集成群"],["村疃","村庄"],["衔枚","口中含枚，防止出声"],["牝马","母马"],["白梃","白木棍"],["劓刖","割鼻断足的酷刑"],["火铳","火器"],["隘口","狭窄的关口"],["恇怯","胆小怯懦"]],"think":["李申为何说“吾正欲其来也”，要放走奸细？","他想引敌入伏，故意让对方知道村中无人防备，让他们轻敌深入。这是兵法的“示形”。边界是故事把这个冒险写得成功，现实里这种计划需要极高的情报与执行能力。"],"quiz":[["李申救崔妻时用什么办法分散敌人注意？",["在东山点火，让贼人以为有警","直接硬拼","贿赂守卫"],"“忽一人报东山有火……申乘间漏出其右。”"],["对奸细，李申的处置是？",["割耳放回，让敌人更轻敌","杀掉","关押"],"“乃割其耳而纵之”，“吾正欲其来也。”"],["战斗的关键地形是？",["狭窄隘口，设炮伏击","开阔地","河岸"],"“置炮当其冲”“谷东口伐树置崖上”。"]],"cards":[["李申设火的目的？","分散敌人注意，掩护撤离，并在谷口威慑。"],["崔猛的性格？","刚毅勇猛，不善谋。"]],"line":["吾正欲其来也","面对对手的挑衅，不必先急着反击，吾正欲其来也，布好局再说。"],"tags":["军事","智谋","勇"]},"liaozhai_chenxijiu":{"intro":"陈锡九的岳父周某嫌他贫穷，强迫女儿离婚，另配富家。陈母死，陈锡九千里迎父骨，路上昏倒，被亡父救起，父亲说“我非人，太行总管也”，帮他取得骨殖，又让妻子“来”见，最后夫妻团圆。这里选两段：梦遇亡父与夫妻重聚。全篇主题是“孝”与“势利”的对照，也是《聊斋》少见的“孝子得鬼助”故事。","focus":["父子相遇的一幕写得动人：“车中人曰：是吾儿也。孽鬼何敢尔！”锡九“大哭曰：儿为父骨良苦。今固尚在人间耶！”父说“我非人，太行总管也”。亡父居然是阴间官员，这个设定使他有能力救子，也让情节具有秩序感。","亡母的话点出了孝的价值：“汝孝行已达天帝，赐汝金万斤，夫妻享受正远，何言不归？”父亲“挽之甚急，竟不遑别母”，锡九没来得及与母亲诀别，是全篇最疼的一笔。父亲最后的嘱托“向岳索妇，不得妇，勿休也”，让孝子的软弱有了力量。","夫妻重逢一段，由陈妻口中补叙：“忽有人捉起曰：我陈家人也，速从我去。”她也被送入“官廨”，与公姑相见。一阳一阴，两处相会，圆满地回到现实。接下来锡九“设童蒙帐”，被太守赏识，家道渐兴，是对孝子的回报，也是对周家的讽刺。"],"notes":[["太行总管","阴间管辖太行山一带的鬼官"],["孽鬼","作恶的鬼"],["子母白榆","一株大榆树，旁生小榆树"],["超乘","跳上车"],["肩舆","轿子"],["官廨","官署"],["童蒙","蒙童，指启蒙教育"],["铁索","铁链，用来拘系犯人"],["醵钱","凑钱"],["总制","明清总督的别称"]],"think":["陈锡九的“孝”在文中有什么实际回报？","一方面是情感的：与父母相见；另一方面是现实的：获得太守赏识、家业重振。作者让孝既有精神价值，也有现实回报。边界是故事里的“回报”是理想化的，不能当作必然规律。"],"quiz":[["亡父的身份是？",["太行总管","文昌帝君","城隍"],"“我非人，太行总管也。”"],["亡父告诉锡九的葬所标志是？",["子母白榆","三棵松树","石碑"],"“去丛葬处百余步，有子母白榆是也。”"],["陈妻为何能见到锡九的父母？",["被陈家人接去，在官廨相见","托梦","自己走去"],"“我陈家人也，速从我去，夫妻可以相见。”"]],"cards":[["陈锡九的难处？","岳父悔婚，父死在外，母已卒。"],["亡父的嘱咐？","向岳索妇，不得勿休。"]],"line":["汝孝行已达天帝","当一个人长期坚持做对的事，总有人看见：汝孝行已达天帝。"],"tags":["孝","鬼","势利"]},"liaozhai_xifangping":{"intro":"席方平的父亲席廉被富人羊某买通阴间官吏折磨至死，席方平魂入冥府告状，从城隍到郡司再到冥王，都被贿赂收买，他受尽火床、锯解之苦，仍说“必讼”，最后被灌口二郎神平反。这里选两段：冥府受刑的一幕，以及二郎神的判词。前者写“孝”与“倔”，后者写“公”的复归。","focus":["受刑一段逐级升级：先是“命笞二十”，席方平厉声问“小人何罪”，冥王“漠若不闻”，他喊“受笞允当，谁教我无钱耶！”再到“火床”“反复揉捺”，“痛极，骨肉焦黑，苦不得死”。冥王每问“敢再讼乎”，他都说“必讼”，这四个字撑起全篇。","锯解时的细节极为沉重：“鬼曰：壮哉此汉！”又一鬼说“此人大孝无辜，锯令稍偏，勿损其心”。行刑者的怜悯来自对孝的敬重，说明连恶吏也有底线。最后“鬼于腰间出丝带一条授之，曰：赠此以报汝孝”，“一身顿健”，形成了一种非官方的“公义”。","判词是全篇的高潮：“勘得冥王者，职膺王爵，身受帝恩。自应贞洁以率臣僚，不当贪墨以速官谤。”接着指斥“羊狠狼贪，竟玷人臣之节”，“当掬西江之水，为尔湔肠；即烧东壁之床，请君入瓮”。“请君入瓮”用来俊臣整周兴的典故，意即以其人之道还治其人。判词四六对仗，既有文采，又直刺现实的官场腐败。"],"notes":[["皂衣人","衙役，穿黑衣的人"],["火床","烧红的铁床"],["揉捺","反复按压"],["壮哉此汉","称赞席方平勇敢"],["丝带","绑在腰间的带子，有神奇的力量"],["阳界","人间"],["勘得","审查得知"],["贪墨","贪污"],["湔肠","洗涤肠胃，指洗心革面"],["请君入瓮","用对方整人的办法整他自己"]],"think":["席方平“必讼”的执着，是勇气还是固执？","他知道自己要受酷刑，仍不改，说明有明确的目标和底线。作者让他最终被二郎神平反，是对这种执着的肯定。边界是：现实里一味执着可能付出更大的代价，这里的“神”是作者的理想补偿。"],"quiz":[["冥王对席方平用的第一种刑罚是？",["笞二十","火床","锯解"],"“冥王益怒，命笞二十。”随后才是火床、锯解。"],["鬼为什么给他一条丝带？",["敬他孝，帮他恢复","要他闭嘴","作为证物"],"“赠此以报汝孝。受而束之，一身顿健。”"],["判词中“请君入瓮”的含义？",["让作恶者受自己用过的刑","让囚犯入瓮","用瓮盛水"],"“即烧东壁之床，请君入瓮”，意即让冥王也尝尝火床。"]],"cards":[["《席方平》的主旨？","孝子为父申冤，不屈于酷刑，终得公道。"],["二郎神在篇中的作用？","秉公断案，重判贪官污吏，并赐席廉增寿。"]],"line":["大冤未伸，寸心不死","他在受刑后对我说：大冤未伸，寸心不死，要继续把事情讲清楚。"],"tags":["冥府","孝","判词"]},"liaozhai_yanzhi":{"intro":"东昌卞氏女胭脂爱上书生鄂秋隼，邻女王氏的情夫宿介冒名鄂生私会，毛大杀人嫁祸，鄂秋隼被屈打成招。济南知府吴公重审，借城隍庙让众犯面壁，说“杀人者，当有神书其背”。这里选吴公审案到判词的一段：设灰涂壁、以神明诱凶、四六判词。这是《聊斋》最著名的“断案”篇，也是侦探小说的雏形。","focus":["吴公的审案有三步：先从原卷中凝思，认为“此生冤也”；再转问王氏“奸夫有几”，由此牵出毛大与“某甲、某乙”；最后“赴城隍庙，使尽伏案前”，说“曩梦神人相告，杀人者不出汝等四五人中”。每一步都在缩小范围，逻辑清晰。","关键的心理战是“面壁”：他让人“以毡褥悉障殿窗，令无少隙；袒诸囚背，驱入暗中，始授盆水，一一命自盥”，并说“当有神书其背”。他事先在壁上抹灰、盆水中掺烟煤，做贼心虚者不敢让背触墙，“匿背于壁而有灰色”，真相立刻显现。这是利用心理的巧计，也是对“神明”信仰的利用。","判词是骈文的文体示范：对宿介“蹈盆成括杀身之道，成登徒子好色之名”，对毛大“被邻女之投梭，淫心不死”，对胭脂“感关雎而念好逑……怨摽梅而思吉士”，最后“嘉其入门之拒，犹洁白之情人；遂其掷果之心，亦风流之雅事。仰彼邑令，作尔冰人”。判词既定罪，也成全，是“又判案又做媒”的结局。"],"notes":[["招供","犯人供述的罪状"],["三木","古代加在犯人颈、手、足上的刑具"],["淫辞","淫荡的言辞"],["盆成括","《孟子》中因才小而遭杀身之祸的人"],["登徒子","好色之徒"],["将仲子","《诗经》篇名，写女子劝情人勿翻墙"],["摽梅","《诗经》篇名，写女子急于出嫁"],["掷果","晋代潘岳貌美，女子掷果相赠"],["僵李代桃","李树代桃树而死，比喻代人受过"],["冰人","媒人"]],"think":["吴公借神灵来逼真凶自露，这种做法在今天的司法中怎么看？","它依赖对神灵的信仰与心理压力，在今天不能作为证据。但其中“缩小范围、设计测试、观察反应”的思路与现代审讯的心理学有共通之处。边界是：故事把“灰”作为客观证据，已不全是迷信。"],"quiz":[["吴公让囚犯面壁，是为了什么？",["让做贼心虚的人暴露背上的灰色","让神明显灵","使囚犯害怕"],"“杀人者恐神来书，故匿背于壁而有灰色。”"],["判词里毛大被如何判？",["刁猾凶徒，即断首领以快人心","轻责","释放"],"“风流道乃生此恶魔……即断首领，以快人心。”"],["“仰彼邑令，作尔冰人”什么意思？",["请县令为鄂生与胭脂做媒","请县令审案","请县令赐罚"],"“冰人”即媒人，吴公让邑令成全这桩婚事。"]],"cards":[["吴公怎样识破真凶？","在庙里让众犯面壁，灰与烟煤使凶手心虚暴露。"],["“僵李代桃”指谁？","被冤的鄂秋隼，代宿介、毛大受过。"]],"line":["此生冤也","审阅材料时我常停一下：此生冤也，再把案卷从头看一遍。"],"tags":["断案","判词","冤狱"]},"liaozhai_gejin":{"intro":"洛阳人常大用爱牡丹，听说曹州的牡丹最盛，借住在一位缙绅的园中，作了百首怀牡丹诗，在牡丹未开时已满怀爱意。这里选的是他初遇女郎的一段：他远远看到一位宫妆女子，疑是仙人，被老妪呵斥，女郎微笑离去，他回来后相思成疾，夜里老妪送来一杯“鸩汤”，他一饮而尽，病竟好了。这篇是《聊斋》花妖类故事的开端，风格清丽。","focus":["常大用的“痴”写得具体：“微窥之，宫妆艳绝，眩迷之中，忽转一想：此必仙人，世上岂有此女子乎？”他“急反身而搜之”，被老妪叱问，“长跪曰：娘子必是神仙”。“孟浪”二字不是浪荡，而是情急。女郎“微笑曰：去之”，这一笑便是转机。","写病的段落很细：“偃卧空斋，自悔孟浪。”“悔惧交集，终夜而病”，“日已向辰，喜无问罪之师，心渐宁帖。而回忆声容，转惧为想，如是三日，憔悴欲死”。从怕到想，层次分明。","“鸩汤”一段是全篇的奇笔：老妪夜里持瓯，说“吾家葛巾娘子，手合鸩汤，其速饮”，生说“与其相思而病，不如仰药而死”，“遂引而尽之”。结果“药气香冷，似非毒者”，“肺鬲宽舒，头颅清爽”，“病若失”。一杯“毒药”变成了灵药，既幽默，又写出他的痴心，也暗示葛巾的主动。"],"notes":[["宅眷","家眷"],["孟浪","鲁莽"],["令尹","县令的别称"],["鸩汤","毒酒"],["仰药","服药自杀"],["夤缘","攀附，找门路"],["肺鬲","肺和膈，泛指胸腹"],["偃卧","仰卧"],["憔悴","瘦弱萎靡"],["宁帖","安定"]],"think":["葛巾送来“鸩汤”，其实是治病的药。这样的设计你怎样看？","这是一种“以毒试情”的玩笑：她要看他是否真心，愿不愿意为她赴死。结果他愿，她便治他。边界是：这种以生死试探的方式在现实中显得危险，在故事里则是浪漫化的表达。"],"quiz":[["常大用为何病倒？",["对宫妆女郎相思，自悔孟浪","着凉","受惊"],"“偃卧空斋，自悔孟浪……憔悴欲死。”"],["老妪送来什么？",["一碗“鸩汤”，实为良药","毒药","茶"],"“吾家葛巾娘子，手合鸩汤，其速饮。”结果“药气香冷，似非毒者”。"],["常大用对这杯“鸩汤”的态度？",["与其相思而病，不如仰药而死","拒绝","怀疑后再饮"],"原话如此。"]],"cards":[["葛巾是谁？","牡丹花神。"],["“鸩汤”在文中的意义？","既是试探也是疗愈，显示她的心思。"]],"line":["与其相思而病，不如仰药而死","他对她这样说，话里的赌气与真诚，都在这一句。"],"tags":["牡丹","爱情","花神"]},"liaozhai_huangying":{"intro":"马子才爱菊，结识了金陵来的陶生，他们结成好友，陶生姐姐黄英嫁给了马子才。这里选两段：陶生靠卖菊致富，与最后一次醉酒死而化菊。故事的有趣之处，在于“菊”被写成人，写成商，既清高，又会算账；篇末异史氏说“植此种于庭中，如见良友，如对丽人”，是对爱花者的赞美。","focus":["卖菊一段，是对“文人不言商”的轻轻一击：“未几菊开，闻其门嚣喧如市”，买花者“车载肩负，道相属也”。马生“心厌其贪，欲与绝，而又恨其私秘佳本”，上门“就诮让”，结果看到陶生满园菊花，“皆向所拔弃也”，酒馔相待，一场责备变成了品酒。","陶生对马生的态度很有分寸：他笑说“此固非可言传，且君不以谋生，焉用此？”意思是你不为谋生，我不为你传。这里把“雅”与“生计”分开：爱菊是雅，卖菊是生计，并不冲突。","结尾的“醉陶”最动人：他“踏菊畦，玉山倾倒，委衣于侧，即地化为菊，高如人，花十余朵”。马生“始悟姊弟菊精也”，黄英“掐其梗埋盆中，日灌溉之”，次年“九月既开，短干粉朵，嗅之有酒香，名之‘醉陶’，浇以酒则茂”。酒里生、酒里死，又在酒里再生，既奇又合理。"],"notes":[["嚣喧","吵闹喧哗"],["诮让","责备"],["斸","挖，砍"],["蓓蕾","花苞"],["四十三月","黄英所说的“出嫁之期”"],["蒲席","蒲草编的席子"],["玉山倾倒","形容人醉倒"],["花朝","农历二月十二日花神诞日"],["醉陶","由醉死的陶生所化的菊"],["菊精","菊花精灵"]],"think":["陶生卖菊致富，马生却觉得“耻以妻富”。你怎么理解这个冲突？","是“文人清高”与“生计现实”的碰撞：马生看重的是菊的雅，陶生看重的是菊的用。故事最终没有谁对谁错，而是让二者共存。边界是：作者借此提出“雅”不必拒绝“富”的可能。"],"quiz":[["陶生卖菊的方式是？",["靠独到的栽培，花肆日售数车","向人乞求","让姐姐帮忙"],"“车载肩负，道相属也。”"],["陶生最后是怎样死的？",["醉倒后化为菊，枯死","病逝","被杀"],"“即地化为菊……根株已枯。”"],["“醉陶”是什么？",["陶生所化的菊花品种","酒名","陶器"],"“九月既开，短干粉朵，嗅之有酒香，名之醉陶。”"]],"cards":[["黄英是谁？","陶生的姐姐，也是菊精，后嫁马子才。"],["“玉山倾倒”是什么意思？","形容醉倒的样子。"]],"line":["植此种于庭中，如见良友，如对丽人","一个好团队就像一座花园，植此种于庭中，如见良友，如对丽人。"],"tags":["菊","花妖","商"]},"liaozhai_wanxia":{"intro":"镇江少年阿端因落水死去，成为龙宫的一员，被选入“龙窝君”的乐舞部。他在大典上看到一位名叫晚霞的少女，两人隔着队列互相注目，后来在莲花田里相会。这一段是《聊斋》里最华美的描写之一：夜叉部、乳莺部、燕子部、柳条部，各有舞姿，是对中国古代乐舞与龙舟戏的想象。","focus":["龙窝君的巡阅像一场盛大的表演：夜叉部“鬼面鱼服，鸣大钲”，舞起则“巨涛汹涌，横流空际”；乳莺部“皆二八姝丽，笙乐细作，一时清风袅袅，波声俱静，水渐凝，如水晶世界”。前者粗犷，后者轻柔，场景对比强烈。","燕子部中的晚霞“振袖倾鬟，作散花舞，翩翩翔起，襟袖袜履间，皆出五色花朵，随风飏下”。阿端“旁睨，雅爱好之”，一个“旁”字，写出他的偷看；“相去数武，而法严不敢乱部，相视神驰而已”，写出了规矩与情感的冲突。","第二段是“遗钗”与“莲亩”：晚霞回首“故遗珊瑚钗”，阿端“急纳袖中”，回来后“凝思成疾”。蛱蝶部的童子来通消息，把他带到“莲花数十亩”，“叶大如席，花大如盖”。两人在荷叶下相会，“以石压荷盖，令侧，雅可幛蔽”，用荷叶做屏障，写得既浪漫，又不失克制。"],"notes":[["龙窝君","篇中龙宫之君"],["夜叉部","龙宫乐舞队之一"],["乳莺部","由少女组成的乐舞队"],["袴褶","一种骑马服，上褶下袴"],["蛱蝶部","由男女童成对组成的乐舞队"],["珊瑚钗","珊瑚制的发钗"],["吴江王","江神之一"],["凝思成疾","因思念成病"],["解姥","照顾阿端的老妇"],["燕子部","穿燕羽的少女乐队"]],"think":["龙宫乐舞被写得如此华丽，作者想表达的是什么？","一方面是对幻想世界的描写，另一方面是在“舞”的秩序里写“情”的越界：队伍严格，感情却在眼神里流动。边界是：这是对龙舟戏的文学化，不是现实的描写。"],"quiz":[["阿端第一次注意到晚霞是在什么场合？",["龙窝君按部，燕子部的散花舞","龙王大宴","莲池"],"“内一女郎……作散花舞……阿端旁睨，雅爱好之，问之同部，即晚霞也。”"],["晚霞怎样传情？",["故意遗落珊瑚钗","送信","直接说话"],"“回首见端，故遗珊瑚钗，端急纳袖中。”"],["两人在什么地方相会？",["莲花田中","宫殿","海边"],"“见莲花数十亩……少时，一美人拨莲花而入，则晚霞也。”"]],"cards":[["晚霞的舞？","散花舞，袖间生出五色花朵。"],["阿端怎样病愈？","晚霞与他在莲田相会，病愈。"]],"line":["相去数武，而法严不敢乱部","他们之间只有几步远，却是相去数武，而法严不敢乱部，克制往往比放纵更打动人。"],"tags":["龙宫","乐舞","爱情"]},"liaozhai_xiangyu":{"intro":"黄生在劳山下清宫读书，爱上白牡丹的花神香玉，又与耐冬的花神绛雪成为好友。后来香玉被人挖走枯死，黄生每日哭她，绛雪劝他，最后香玉重生，两人相聚。这里选两段：香玉“复降”的相聚，与黄生寄魂牡丹之下，二花相随而殁。篇末异史氏说“情之结者，鬼神可通”。","focus":["香玉复降一段，是对“虚”与“实”的细腻处理：香玉回来，“生望见，泣下流离，急起把握，香玉以一手捉绛雪，相对悲哽。已而坐道离苦，生把之觉虚，如手自握”。她解释“昔妾花之神，故凝；今妾花之鬼，故散也”。这段写出了“死而不能真聚”的遗憾，是全篇最苦的一笔。","绛雪的态度也值得注意：她笑着对黄生说“喜信报君知”，却又半嗔半笑地说“妾被汝家男子纠缠死矣”，隔着“朋友”和“情人”的界线，让黄生的情感没有完全倾斜。她是篇中的“旁观者”，也是最清醒的一个。","结尾是“寄魂”：黄生妻死后入山不归，牡丹“大如臂”，他指着说“我他日寄魂于此，当生卿之左”；十余年后他病逝，次年“果有肥芽突出，叶如其数”。三年后“老道士死，其弟子不知爱惜”，把它斫去，“白牡丹亦憔悴寻死，无何，耐冬亦死”。异史氏用“仲尼读唐棣而曰未思”作结，意思是：不爱，才是“未思”，因为真爱必有所至。"],"notes":[["团艾","把艾叶团成团，用来灸"],["创痏","伤痕"],["泫然","流泪的样子"],["白蔹屑","白蔹的粉末，中药名"],["硫黄","一种矿物，可入药"],["酹","把酒洒在地上祭奠"],["悲哽","悲痛得喉咙哽咽"],["耐冬","山茶的一种"],["寄魂","把灵魂寄放于某物"],["唐棣","《诗经》中的植物，孔子借以论“思”"]],"think":["异史氏引孔子“未之思也，夫何远之有”，是什么意思？","孔子说，不是远，是你没真正想念。作者借此说，真正的“情”无论生死都可相通。边界是：这是对故事主旨的点评，也是一种文学化的“情至论”，不是现实结论。"],"quiz":[["香玉重来时为什么黄生“把之觉虚”？",["她已是花鬼，不如花神凝实","她生病","她在撒谎"],"“昔妾花之神，故凝；今妾花之鬼，故散也。”"],["香玉教黄生怎样让她重生？",["以白蔹屑、硫黄，日酹一杯水","烧香","念咒"],"“君以白蔹屑，少杂硫黄，日酹妾一杯水，明年此日报君恩。”"],["结尾牡丹与耐冬为何死去？",["被道士弟子砍去，二花相继死去","自然枯死","被虫蛀"],"“其弟子不知爱惜，因其不花，斫去之。白牡丹亦憔悴寻死，无何，耐冬亦死。”"]],"cards":[["香玉是什么花神？","白牡丹。"],["绛雪是什么花神？","耐冬。"]],"line":["情之结者，鬼神可通","真正的投入，不分生死，情之结者，鬼神可通。"],"tags":["花神","爱情","生死"]}});
